{
  "name": "B2KS Daily Routines",
  "description": "Game RPG Gia Đình B2KS: Nhiệm vụ hằng ngày, Sở thú ảo học tiếng Anh, Trung tâm giao dịch, Chợ trời, Phòng thí nghiệm sáng tạo và Khu vui chơi đối kháng.",
  "requestFramePermissions": [],
  "majorCapabilities": ["MAJOR_CAPABILITY_SERVER_SIDE_GEMINI_API"]
}

const CACHE_NAME = 'b2ks-daily-routines-v19';
const STATIC_ASSETS = [
  './',
  './index.html',
  './manifest.json',
  './animals.json',
  './icon.svg',
  './pwa-192x192.png',
  './pwa-512x512.png',
  './apple-touch-icon.png'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return cache.addAll(STATIC_ASSETS).catch(() => {});
    })
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(
        keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))
      )
    )
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);

  // Never cache Firebase RTDB or translation/wiki APIs aggressively; network-first with fallback
  if (
    url.hostname.includes('firebasedatabase.app') ||
    url.hostname.includes('firebaseio.com') ||
    url.hostname.includes('wikipedia.org') ||
    url.hostname.includes('mymemory.translated.net') ||
    url.hostname.includes('dictionaryapi.dev')
  ) {
    event.respondWith(
      fetch(req).catch(() => caches.match(req))
    );
    return;
  }

  event.respondWith(
    caches.match(req).then((cached) => {
      const fetchPromise = fetch(req)
        .then((networkResp) => {
          if (networkResp && networkResp.status === 200 && url.origin === self.location.origin) {
            const copy = networkResp.clone();
            caches.open(CACHE_NAME).then((cache) => cache.put(req, copy));
          }
          return networkResp;
        })
        .catch(() => cached);
      return cached || fetchPromise;
    })
  );
});

import { useCallback, useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { HelpCircle, X } from 'lucide-react';
import { ActiveReactModal, B2KSBridge } from './types/b2ks';
import { CrossWorldModal } from './components/CrossWorldModal';
import { FleaMarketModal } from './components/FleaMarketModal';
import { VirtualZooModal } from './components/VirtualZooModal';
import { ParentalDashboardModal } from './components/ParentalDashboardModal';
import { ParentMiniWindow } from './components/ParentMiniWindow';
import { OfflineIndicator, PWAInstallButton } from './components/PWAInstallButton';
import { ComicLibraryModal } from './components/ComicLibraryModal';
import { GamePasswordGate } from './components/GamePasswordGate';
import { SoundThemePicker } from './components/SoundThemePicker';
import { AdminPanelModal } from './components/AdminPanelModal';
import { AchievementsModal } from './components/AchievementsModal';
import { SpeakingPracticeModal } from './components/SpeakingPracticeModal';

export default function App() {
  const [activeModal, setActiveModal] = useState<ActiveReactModal>(null);
  const [bridge, setBridge] = useState<B2KSBridge | undefined>(() => window.B2KS);
  const [hudPwaHost, setHudPwaHost] = useState<HTMLElement | null>(null);
  const [hudSoundHost, setHudSoundHost] = useState<HTMLElement | null>(null);
  const [unlocked, setUnlocked] = useState(false);
  const [showGuideHint, setShowGuideHint] = useState(false);
  const [guideAnchor, setGuideAnchor] = useState<{ left: number; top?: number; bottom?: number; arrowOffset: number; above: boolean } | null>(null);

  const updateGuideAnchor = useCallback(() => {
    const btn = document.getElementById('hud-guide-btn');
    if (!btn) {
      setGuideAnchor({ left: Math.max(12, window.innerWidth - 280), bottom: 76, arrowOffset: 120, above: true });
      return;
    }
    const r = btn.getBoundingClientRect();
    const boxWidth = 256;
    const clampedLeft = Math.max(10, Math.min(window.innerWidth - boxWidth - 10, r.left + r.width / 2 - boxWidth / 2));
    const arrowOffset = Math.max(18, Math.min(boxWidth - 22, r.left + r.width / 2 - clampedLeft));
    const above = r.top > window.innerHeight * 0.5;
    setGuideAnchor(
      above
        ? { left: clampedLeft, bottom: Math.max(68, window.innerHeight - r.top + 10), arrowOffset, above: true }
        : { left: clampedLeft, top: r.bottom + 10, arrowOffset, above: false }
    );
  }, []);

  useEffect(() => {
    setHudPwaHost(document.getElementById('hud-pwa-slot'));
    setHudSoundHost(document.getElementById('hud-sound-slot'));

    window.__OPEN_B2KS_MODAL__ = (modal: ActiveReactModal) => {
      if (window.B2KS) setBridge(window.B2KS);
      setActiveModal(modal);
    };

    const syncBridge = (b: B2KSBridge) => {
      b.setGameUnlocked?.(false);
      setBridge(b);
      setHudPwaHost(document.getElementById('hud-pwa-slot'));
      setHudSoundHost(document.getElementById('hud-sound-slot'));
    };

    if (window.B2KS) {
      syncBridge(window.B2KS);
    }

    const timer = window.setInterval(() => {
      if (window.B2KS) {
        syncBridge(window.B2KS);
        window.clearInterval(timer);
      }
    }, 80);

    return () => {
      window.clearInterval(timer);
    };
  }, []);

  useEffect(() => {
    if (!showGuideHint) return;
    updateGuideAnchor();
    const onResize = () => updateGuideAnchor();
    const onGuideClick = () => setShowGuideHint(false);
    const guideBtn = document.getElementById('hud-guide-btn');
    guideBtn?.addEventListener('click', onGuideClick);
    window.addEventListener('resize', onResize);
    const timeout = window.setTimeout(() => setShowGuideHint(false), 8500);
    return () => {
      window.clearTimeout(timeout);
      window.removeEventListener('resize', onResize);
      guideBtn?.removeEventListener('click', onGuideClick);
    };
  }, [showGuideHint, updateGuideAnchor]);

  const handleUnlocked = () => {
    setUnlocked(true);
    setShowGuideHint(true);
    window.setTimeout(updateGuideAnchor, 80);
  };

  const close = () => setActiveModal(null);

  return (
    <>
      {hudPwaHost && createPortal(<PWAInstallButton />, hudPwaHost)}
      {hudSoundHost && bridge && unlocked && createPortal(<SoundThemePicker bridge={bridge} />, hudSoundHost)}
      <OfflineIndicator />

      {bridge && !unlocked && (
        <GamePasswordGate bridge={bridge} onUnlocked={handleUnlocked} />
      )}

      {unlocked && showGuideHint && guideAnchor && (
        <div
          style={{
            left: guideAnchor.left,
            ...(guideAnchor.above ? { bottom: guideAnchor.bottom } : { top: guideAnchor.top }),
          }}
          className="fixed z-[350] w-64 rounded-2xl border border-amber-300 bg-amber-50/95 text-slate-900 shadow-2xl p-2.5 animate-bounce"
        >
          <div
            style={{ left: guideAnchor.arrowOffset - 6 }}
            className={
              guideAnchor.above
                ? 'absolute -bottom-2 w-3.5 h-3.5 rotate-45 bg-amber-50 border-r border-b border-amber-300'
                : 'absolute -top-2 w-3.5 h-3.5 rotate-45 bg-amber-50 border-l border-t border-amber-300'
            }
          />
          <div className="flex items-start justify-between gap-2">
            <div className="flex items-start gap-2 text-xs leading-snug">
              <HelpCircle className="w-4 h-4 text-amber-600 shrink-0 mt-0.5" />
              <div>
                <div className="font-extrabold text-amber-950">Cần xem Hướng dẫn chơi?</div>
                <div className="text-[11px] text-slate-700 mt-0.5">
                  Bấm nút <b>❓ Hướng dẫn</b> {guideAnchor.above ? 'ngay phía dưới' : 'ngay phía trên'} bất cứ lúc nào nhé!
                </div>
              </div>
            </div>
            <button
              type="button"
              onClick={() => setShowGuideHint(false)}
              className="p-0.5 rounded hover:bg-amber-200/60 text-slate-600 cursor-pointer shrink-0"
              aria-label="Đóng gợi ý"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      )}

      {bridge && unlocked && <ParentMiniWindow bridge={bridge} />}

      {bridge && unlocked && activeModal === 'cross_world' && (
        <CrossWorldModal bridge={bridge} onClose={close} />
      )}
      {bridge && unlocked && activeModal === 'flea_market' && (
        <FleaMarketModal bridge={bridge} onClose={close} />
      )}
      {bridge && unlocked && activeModal === 'virtual_zoo' && (
        <VirtualZooModal bridge={bridge} onClose={close} />
      )}
      {bridge && unlocked && activeModal === 'parental_dashboard' && (
        <ParentalDashboardModal bridge={bridge} onClose={close} />
      )}
      {bridge && unlocked && activeModal === 'comic_library' && (
        <ComicLibraryModal bridge={bridge} onClose={close} />
      )}
      {bridge && unlocked && activeModal === 'admin_panel' && (
        <AdminPanelModal bridge={bridge} onClose={close} />
      )}
      {bridge && unlocked && activeModal === 'achievements' && (
        <AchievementsModal bridge={bridge} onClose={close} />
      )}
      {bridge && unlocked && activeModal === 'speaking_practice' && (
        <SpeakingPracticeModal bridge={bridge} onClose={close} />
      )}
    </>
  );
}

import React, { useMemo, useState } from 'react';
import { Trophy, Lock, CheckCircle2, X } from 'lucide-react';
import {
  ACHIEVEMENT_CATALOG,
  getAchievementProgress,
  getTotalCompletedTasksForMember,
} from '../game/speakingAndAchievements';
import type { AchievementCategory, B2KSBridge, Member } from '../types/b2ks';

interface Props {
  bridge: B2KSBridge;
  onClose: () => void;
}

const CATEGORY_TABS: Array<{ id: 'all' | AchievementCategory; label: string }> = [
  { id: 'all', label: '🌟 Tất cả' },
  { id: 'tasks', label: '📋 Nhiệm vụ' },
  { id: 'english', label: '🗣️ Tiếng Anh' },
  { id: 'world', label: '🎨 Thế giới & Thú cưng' },
];

export const AchievementsModal: React.FC<Props> = ({ bridge, onClose }) => {
  const state = bridge.getState();
  const currentUser = bridge.getCurrentUser();
  const kids = useMemo(() => state.members.filter((m) => !bridge.isParent(m)), [state.members, bridge]);

  const [selectedMemberId, setSelectedMemberId] = useState<string>(
    !bridge.isParent(currentUser) ? currentUser.id : kids[0]?.id || currentUser.id
  );
  const [catFilter, setCatFilter] = useState<'all' | AchievementCategory>('all');

  const targetMember: Member =
    state.members.find((m) => m.id === selectedMemberId) || currentUser;

  const unlockedMap = useMemo(() => {
    const map = new Map<string, number>();
    (targetMember.unlockedAchievements || []).forEach((u) => {
      map.set(u.id, u.unlockedAt);
    });
    return map;
  }, [targetMember]);

  const unlockedCount = ACHIEVEMENT_CATALOG.filter((a) => unlockedMap.has(a.id)).length;
  const totalCount = ACHIEVEMENT_CATALOG.length;
  const pct = Math.round((unlockedCount / Math.max(1, totalCount)) * 100);

  const visibleBadges = ACHIEVEMENT_CATALOG.filter(
    (b) => catFilter === 'all' || b.category === catFilter
  );

  const completedTasks = getTotalCompletedTasksForMember(targetMember, state.tasks);
  const distinctWords = (targetMember.englishWordsUsed || []).length;
  const speakingLv = targetMember.speakingLevel || 1;
  const streak = targetMember.speakingStreak || 0;

  return (
    <div
      className="modal-overlay"
      style={{ display: 'flex', zIndex: 245 }}
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        className="modal-content pixel-box"
        style={{
          maxWidth: '780px',
          width: '96vw',
          maxHeight: '90dvh',
          display: 'flex',
          flexDirection: 'column',
          background: 'linear-gradient(180deg, #FFFDF5 0%, #FEF3C7 100%)',
          borderColor: '#0F172A',
        }}
      >
        {/* Header */}
        <div
          className="modal-header"
          style={{
            background: 'linear-gradient(90deg, #D97706, #F59E0B, #EA580C)',
            color: '#FFFFFF',
            margin: '-16px -16px 12px -16px',
            padding: '12px 16px',
            borderRadius: '13px 13px 0 0',
            borderBottom: '3px solid #0F172A',
          }}
        >
          <div className="flex items-center gap-2">
            <Trophy className="w-6 h-6 text-yellow-200" />
            <div>
              <h2 style={{ color: '#FFFFFF', margin: 0, fontSize: '18px' }}>
                Bảng Thành Tựu &amp; Huy Hiệu
              </h2>
              <div className="text-[11px] text-amber-100 font-semibold">
                Hoàn thành nhiệm vụ, luyện nói Tiếng Anh &amp; khám phá khu phố để mở khóa!
              </div>
            </div>
          </div>
          <button
            type="button"
            className="btn btn-sm"
            style={{ background: '#FFF', color: '#B45309' }}
            onClick={onClose}
          >
            <X className="w-4 h-4" />
            <span>Đóng</span>
          </button>
        </div>

        {/* Member Selector (kids only — parents are not tracked for achievements) */}
        <div className="flex flex-wrap items-center justify-between gap-2 mb-3">
          <div className="flex flex-wrap items-center gap-1.5">
            {(kids.length > 0 ? kids : [targetMember]).map((m) => {
              const active = m.id === targetMember.id;
              return (
                <button
                  key={m.id}
                  type="button"
                  onClick={() => setSelectedMemberId(m.id)}
                  className={`px-3 py-1 rounded-full text-xs font-bold border-2 cursor-pointer transition ${
                    active
                      ? 'bg-[#0F172A] text-white border-[#0F172A]'
                      : 'bg-white text-slate-700 border-slate-300 hover:border-amber-500'
                  }`}
                >
                  {m.outfit || '🙂'} {m.name} ({(m.unlockedAchievements || []).length}/{totalCount})
                </button>
              );
            })}
          </div>

          <div className="px-3 py-1 rounded-full bg-amber-500 text-white text-xs font-extrabold border-2 border-[#0F172A]">
            🏆 Đã mở {unlockedCount}/{totalCount} ({pct}%)
          </div>
        </div>

        {/* Quick stats strip */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 mb-3">
          <div className="rounded-xl bg-white border-2 border-slate-800 px-3 py-2 text-center">
            <div className="text-[10.5px] font-bold text-slate-500">✅ Nhiệm vụ xong</div>
            <div className="text-base font-extrabold text-emerald-700">{completedTasks}</div>
          </div>
          <div className="rounded-xl bg-white border-2 border-slate-800 px-3 py-2 text-center">
            <div className="text-[10.5px] font-bold text-slate-500">🔤 Từ Tiếng Anh</div>
            <div className="text-base font-extrabold text-sky-700">{distinctWords} từ</div>
          </div>
          <div className="rounded-xl bg-white border-2 border-slate-800 px-3 py-2 text-center">
            <div className="text-[10.5px] font-bold text-slate-500">🗣️ Speaking Level</div>
            <div className="text-base font-extrabold text-violet-700">
              Lv.{speakingLv} ({streak}/5)
            </div>
          </div>
          <div className="rounded-xl bg-white border-2 border-slate-800 px-3 py-2 text-center">
            <div className="text-[10.5px] font-bold text-slate-500">⭐ Điểm hiện tại</div>
            <div className="text-base font-extrabold text-amber-600">{targetMember.points}⭐</div>
          </div>
        </div>

        {/* Category Filter */}
        <div className="flex flex-wrap gap-1.5 mb-3">
          {CATEGORY_TABS.map((t) => (
            <button
              key={t.id}
              type="button"
              onClick={() => setCatFilter(t.id)}
              className={`px-3 py-1 rounded-lg text-xs font-bold border-2 cursor-pointer ${
                catFilter === t.id
                  ? 'bg-amber-600 text-white border-[#0F172A]'
                  : 'bg-white text-slate-700 border-slate-300'
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>

        {/* Badges Grid */}
        <div className="overflow-y-auto pr-1 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2.5 flex-1">
          {visibleBadges.map((badge) => {
            const unlockedAt = unlockedMap.get(badge.id);
            const isUnlocked = unlockedAt !== undefined;
            const prog = getAchievementProgress(badge.id, targetMember, state.tasks);
            const progPct = Math.min(100, Math.round((prog.current / Math.max(1, prog.target)) * 100));

            return (
              <div
                key={badge.id}
                className={`rounded-2xl border-2 p-3 flex flex-col justify-between gap-2 transition ${
                  isUnlocked
                    ? 'border-[#0F172A] shadow-[0_3px_0_#0F172A]'
                    : 'border-slate-300 bg-slate-200/80 grayscale opacity-75'
                }`}
                style={
                  isUnlocked
                    ? {
                        background: `linear-gradient(135deg, #FFFFFF 0%, ${badge.color}22 100%)`,
                      }
                    : undefined
                }
              >
                <div className="flex items-start gap-2.5">
                  <div
                    className={`w-12 h-12 rounded-2xl border-2 flex items-center justify-center text-2xl shrink-0 ${
                      isUnlocked ? 'border-[#0F172A] shadow-sm' : 'border-slate-400 bg-slate-300'
                    }`}
                    style={
                      isUnlocked
                        ? { background: `${badge.color}28` }
                        : undefined
                    }
                  >
                    {badge.icon}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between gap-1">
                      <div className="font-extrabold text-xs sm:text-sm text-slate-900 leading-tight">
                        {badge.title}
                      </div>
                      {isUnlocked ? (
                        <CheckCircle2 className="w-4 h-4 text-emerald-600 shrink-0" />
                      ) : (
                        <Lock className="w-3.5 h-3.5 text-slate-500 shrink-0" />
                      )}
                    </div>
                    <div className="text-[11px] text-slate-600 mt-0.5 leading-snug">
                      {badge.description}
                    </div>
                  </div>
                </div>

                <div>
                  <div className="flex items-center justify-between text-[10.5px] font-bold mb-1">
                    <span className={isUnlocked ? 'text-emerald-700' : 'text-slate-600'}>
                      {isUnlocked ? '✅ Đã mở khóa!' : `Tiến độ: ${prog.current}/${prog.target}`}
                    </span>
                    {isUnlocked && unlockedAt > 0 ? (
                      <span className="text-slate-500">
                        {new Date(unlockedAt).toLocaleDateString('vi-VN')}
                      </span>
                    ) : (
                      <span className="text-slate-500">{progPct}%</span>
                    )}
                  </div>
                  <div className="h-2 w-full rounded-full bg-slate-300 overflow-hidden border border-slate-400">
                    <div
                      className="h-full rounded-full transition-all"
                      style={{
                        width: `${isUnlocked ? 100 : progPct}%`,
                        background: isUnlocked ? badge.color : '#64748B',
                      }}
                    />
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import {
  Building2,
  Coins,
  KeyRound,
  Palette,
  PlusCircle,
  RefreshCw,
  RotateCcw,
  Save,
  ShieldAlert,
  Trash2,
  X,
} from 'lucide-react';
import { AdminNeighborhoodRecord, B2KSBridge } from '../types/b2ks';
import { AssetLibraryTab } from './AssetLibraryTab';

interface Props {
  bridge: B2KSBridge;
  onClose: () => void;
}

export const AdminPanelModal: React.FC<Props> = ({ bridge, onClose }) => {
  const [tab, setTab] = useState<'neighborhoods' | 'parent_points' | 'assets'>('neighborhoods');
  const [records, setRecords] = useState<AdminNeighborhoodRecord[]>([]);
  const [loading, setLoading] = useState(false);

  // Create Neighborhood form
  const [newFamilyName, setNewFamilyName] = useState('');
  const [newDadName, setNewDadName] = useState('Bố');
  const [newMomName, setNewMomName] = useState('Mẹ');
  const [creating, setCreating] = useState(false);
  const [confirmDeleteSlug, setConfirmDeleteSlug] = useState<string | null>(null);
  const [confirmResetSlug, setConfirmResetSlug] = useState<string | null>(null);

  // Parent allowance, max cap & points drafts keyed by slug
  const [allowanceDrafts, setAllowanceDrafts] = useState<Record<string, string>>({});
  const [maxPointsDrafts, setMaxPointsDrafts] = useState<Record<string, string>>({});
  const [parentPointDrafts, setParentPointDrafts] = useState<Record<string, Record<string, string>>>({});
  const [savingSlug, setSavingSlug] = useState<string | null>(null);

  const isAuthorized = Boolean(bridge.isB2KSDad?.());

  const loadNeighborhoods = async () => {
    if (!bridge.adminListNeighborhoods) return;
    setLoading(true);
    try {
      const list = await bridge.adminListNeighborhoods();
      setRecords(list);
      const nextAllow: Record<string, string> = {};
      const nextMaxPts: Record<string, string> = {};
      const nextPts: Record<string, Record<string, string>> = {};
      list.forEach((rec) => {
        nextAllow[rec.slug] = String(rec.dailyParentAllowance ?? 100);
        nextMaxPts[rec.slug] = String(rec.maxParentPoints ?? 500);
        nextPts[rec.slug] = {};
        rec.parents.forEach((p) => {
          nextPts[rec.slug][p.id] = String(p.points ?? 0);
        });
      });
      setAllowanceDrafts(nextAllow);
      setMaxPointsDrafts(nextMaxPts);
      setParentPointDrafts(nextPts);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (isAuthorized) {
      loadNeighborhoods();
    }
  }, [isAuthorized]);

  if (!isAuthorized) {
    return (
      <div className="fixed inset-0 z-[260] flex items-center justify-center bg-black/75 p-4">
        <div className="w-full max-w-md rounded-2xl border-[3px] border-[#2C3E50] bg-white p-5 text-[#2C3E50] shadow-2xl space-y-4">
          <div className="flex items-center gap-2 text-rose-700 font-extrabold text-base">
            <ShieldAlert className="w-5 h-5" />
            <span>Không có quyền truy cập Admin</span>
          </div>
          <p className="text-sm text-slate-600">
            Công cụ Admin chỉ dành riêng cho nhân vật <b>Bố</b> của khu phố gốc <b>B2KS</b>.
          </p>
          <button
            type="button"
            onClick={() => {
              bridge.playClick();
              onClose();
            }}
            className="btn btn-primary w-full justify-center"
          >
            Đóng
          </button>
        </div>
      </div>
    );
  }

  const handleCreateNeighborhood = async (e: React.FormEvent) => {
    e.preventDefault();
    if (creating || !bridge.adminCreateNeighborhood) return;
    const clean = newFamilyName.trim();
    if (!clean) {
      bridge.playError();
      bridge.showToast('⚠️ Vui lòng nhập tên khu phố / gia đình mới!');
      return;
    }
    setCreating(true);
    try {
      const res = await bridge.adminCreateNeighborhood(clean, newDadName.trim() || 'Bố', newMomName.trim() || 'Mẹ');
      bridge.showToast(res.msg);
      if (res.ok) {
        bridge.playSuccess();
        setNewFamilyName('');
        setNewDadName('Bố');
        setNewMomName('Mẹ');
        await loadNeighborhoods();
      } else {
        bridge.playError();
      }
    } finally {
      setCreating(false);
    }
  };

  const handleResetPasswords = async (slug: string) => {
    if (!bridge.adminResetNeighborhoodPasswords) return;
    setSavingSlug(slug);
    try {
      const res = await bridge.adminResetNeighborhoodPasswords(slug);
      setConfirmResetSlug(null);
      bridge.showToast(res.msg);
      if (res.ok) {
        bridge.playSuccess();
      } else {
        bridge.playError();
      }
    } finally {
      setSavingSlug(null);
    }
  };

  const handleDeleteNeighborhood = async (slug: string) => {
    if (!bridge.adminDeleteNeighborhood) return;
    setSavingSlug(slug);
    try {
      const res = await bridge.adminDeleteNeighborhood(slug);
      setConfirmDeleteSlug(null);
      bridge.showToast(res.msg);
      if (res.ok) {
        bridge.playClick();
        await loadNeighborhoods();
      } else {
        bridge.playError();
      }
    } finally {
      setSavingSlug(null);
    }
  };

  const handleSaveParentAdjustment = async (rec: AdminNeighborhoodRecord) => {
    if (!bridge.adminAdjustParentAccount) return;
    setSavingSlug(rec.slug);
    try {
      const allowanceVal = Math.max(0, Math.min(10000, Math.round(Number(allowanceDrafts[rec.slug] ?? rec.dailyParentAllowance) || 0)));
      const maxPointsVal = Math.max(0, Math.min(999999, Math.round(Number(maxPointsDrafts[rec.slug] ?? rec.maxParentPoints ?? 500) || 0)));
      const ptsMap: Record<string, number> = {};
      rec.parents.forEach((p) => {
        const raw = parentPointDrafts[rec.slug]?.[p.id];
        ptsMap[p.id] = Math.max(0, Math.min(999999, Math.round(Number(raw ?? p.points) || 0)));
      });
      const res = await bridge.adminAdjustParentAccount(rec.slug, {
        dailyParentAllowance: allowanceVal,
        maxParentPoints: maxPointsVal,
        parentPoints: ptsMap,
      });
      bridge.showToast(res.msg);
      if (res.ok) {
        bridge.playSuccess();
        await loadNeighborhoods();
      } else {
        bridge.playError();
      }
    } finally {
      setSavingSlug(null);
    }
  };

  const bumpParentDraftPoint = (slug: string, parentId: string, currentFallback: number, delta: number) => {
    setParentPointDrafts((prev) => {
      const famMap = { ...(prev[slug] || {}) };
      const curVal = Number(famMap[parentId] ?? currentFallback) || 0;
      famMap[parentId] = String(Math.max(0, curVal + delta));
      return { ...prev, [slug]: famMap };
    });
  };

  return (
    <div className="fixed inset-0 z-[260] flex items-center justify-center bg-black/75 p-3">
      <div className={`w-full ${tab === 'assets' ? 'max-w-5xl' : 'max-w-4xl'} max-h-[90dvh] flex flex-col rounded-2xl border-[3px] border-[#2C3E50] bg-[#F8FAFC] text-[#2C3E50] shadow-2xl overflow-hidden`}>
        {/* Header */}
        <div className="flex items-center justify-between px-4 py-3 bg-gradient-to-r from-[#4C1D95] via-[#6D28D9] to-[#7C3AED] text-white border-b-[3px] border-[#2C3E50]">
          <div className="flex items-center gap-2.5">
            <span className="text-2xl">🛠️</span>
            <div>
              <h2 className="text-base sm:text-lg font-extrabold">
                Công Cụ Admin Hệ Thống (Chỉ Bố B2KS)
              </h2>
              <p className="text-xs text-violet-100">
                Quản lý danh sách khu phố, reset mật khẩu mặc định (1111 / 1234) &amp; điều chỉnh ngân sách Phụ huynh toàn hệ thống
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={() => {
              bridge.playClick();
              onClose();
            }}
            className="p-1.5 rounded-lg bg-white text-[#2C3E50] hover:bg-slate-100 cursor-pointer"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Navigation Tabs */}
        <div className="flex flex-wrap items-center justify-between gap-2 px-4 py-2.5 bg-slate-200 border-b-2 border-[#2C3E50]">
          <div className="flex flex-wrap gap-2">
            <button
              type="button"
              onClick={() => {
                bridge.playClick();
                setTab('neighborhoods');
              }}
              className={`px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1.5 cursor-pointer ${
                tab === 'neighborhoods' ? 'bg-[#6D28D9] text-white shadow' : 'bg-white text-[#2C3E50]'
              }`}
            >
              <Building2 className="w-3.5 h-3.5" />
              <span>Quản lý các khu phố ({records.length})</span>
            </button>
            <button
              type="button"
              onClick={() => {
                bridge.playClick();
                setTab('parent_points');
              }}
              className={`px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1.5 cursor-pointer ${
                tab === 'parent_points' ? 'bg-[#D97706] text-white shadow' : 'bg-white text-[#2C3E50]'
              }`}
            >
              <Coins className="w-3.5 h-3.5" />
              <span>Điều chỉnh điểm Phụ huynh</span>
            </button>
            <button
              type="button"
              onClick={() => {
                bridge.playClick();
                setTab('assets');
              }}
              className={`px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1.5 cursor-pointer ${
                tab === 'assets' ? 'bg-[#0284C7] text-white shadow' : 'bg-white text-[#2C3E50]'
              }`}
            >
              <Palette className="w-3.5 h-3.5" />
              <span>Thư viện Hình ảnh 2D &amp; 3D</span>
            </button>
          </div>
          {tab !== 'assets' && (
            <button
              type="button"
              disabled={loading}
              onClick={loadNeighborhoods}
              className="btn btn-sm btn-accent"
            >
              <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
              <span>{loading ? 'Đang tải...' : 'Làm mới'}</span>
            </button>
          )}
        </div>

        {/* Body */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {tab === 'neighborhoods' && (
            <>
              {/* Create New Neighborhood Box */}
              <form
                onSubmit={handleCreateNeighborhood}
                className="rounded-xl border-2 border-[#2C3E50] bg-violet-50 p-3.5 space-y-2.5"
              >
                <div>
                  <h3 className="font-extrabold text-sm text-violet-950 flex items-center gap-1.5">
                    <PlusCircle className="w-4 h-4 text-violet-700" />
                    <span>Tạo Khu Phố Gia Đình Mới</span>
                  </h3>
                  <p className="text-[11.5px] text-violet-800 mt-0.5">
                    Gia đình mới chỉ gồm <b>Bố</b> và <b>Mẹ</b> mặc định, database tách biệt hoàn toàn (chỉ dùng chung Ngân Hàng Tiếng Anh) và có mật khẩu mặc định: vào game <code className="bg-white px-1 rounded font-bold">1111</code> · Phụ huynh <code className="bg-white px-1 rounded font-bold">1234</code>.
                  </p>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-4 gap-2">
                  <input
                    type="text"
                    maxLength={24}
                    value={newFamilyName}
                    onChange={(e) => setNewFamilyName(e.target.value)}
                    placeholder="Tên khu phố (VD: MINH, ANH...)"
                    className="sm:col-span-2 px-3 py-1.5 rounded-lg border-2 border-[#2C3E50] bg-white text-xs font-bold"
                  />
                  <input
                    type="text"
                    maxLength={20}
                    value={newDadName}
                    onChange={(e) => setNewDadName(e.target.value)}
                    placeholder="Tên Bố (mặc định: Bố)"
                    className="px-2.5 py-1.5 rounded-lg border-2 border-[#2C3E50] bg-white text-xs font-bold"
                  />
                  <input
                    type="text"
                    maxLength={20}
                    value={newMomName}
                    onChange={(e) => setNewMomName(e.target.value)}
                    placeholder="Tên Mẹ (mặc định: Mẹ)"
                    className="px-2.5 py-1.5 rounded-lg border-2 border-[#2C3E50] bg-white text-xs font-bold"
                  />
                </div>
                <div className="flex justify-end">
                  <button
                    type="submit"
                    disabled={creating}
                    className="btn btn-sm btn-purple disabled:opacity-60"
                  >
                    <PlusCircle className="w-3.5 h-3.5" />
                    <span>{creating ? 'Đang khởi tạo...' : 'Tạo Khu Phố Mới (Chỉ gồm Bố & Mẹ)'}</span>
                  </button>
                </div>
              </form>

              {/* Neighborhood Directory */}
              <div className="space-y-2.5">
                {loading && records.length === 0 ? (
                  <div className="text-center py-8 text-xs text-slate-500">Đang tải danh sách các khu phố...</div>
                ) : records.length === 0 ? (
                  <div className="text-center py-8 text-xs text-slate-500">Chưa có dữ liệu khu phố.</div>
                ) : (
                  records.map((rec) => {
                    const isB2KS = rec.slug === 'b2ks';
                    const isBusy = savingSlug === rec.slug;
                    const confirmingReset = confirmResetSlug === rec.slug;
                    const confirmingDel = confirmDeleteSlug === rec.slug;
                    return (
                      <div
                        key={rec.slug}
                        className={`rounded-xl border-2 p-3 flex flex-wrap items-center justify-between gap-3 ${
                          isB2KS ? 'border-violet-600 bg-white shadow-sm' : 'border-[#2C3E50] bg-white'
                        }`}
                      >
                        <div className="space-y-1 min-w-[210px]">
                          <div className="flex items-center gap-2 flex-wrap">
                            <span className="font-extrabold text-sm text-[#2C3E50]">
                              🏡 {rec.familyName}
                            </span>
                            <code className="text-[10.5px] px-1.5 py-0.5 rounded bg-slate-100 border border-slate-300 text-slate-600">
                              slug: {rec.slug}
                            </code>
                            {isB2KS && (
                              <span className="px-2 py-0.5 rounded-full bg-violet-100 border border-violet-400 text-[10px] font-extrabold text-violet-800">
                                ⭐ Khu phố gốc
                              </span>
                            )}
                          </div>
                          <div className="text-xs text-slate-600 flex flex-wrap gap-3">
                            <span>👥 {rec.memberCount} thành viên ({rec.kidCount} con)</span>
                            <span>📅 Nhận/ngày: <b>{rec.dailyParentAllowance}⭐</b></span>
                            <span>🔒 Tối đa PH: <b>{rec.maxParentPoints ?? 500}⭐</b></span>
                            <span>
                              💰 PH:{' '}
                              {rec.parents.map((p) => `${p.name} (${p.points}⭐)`).join(' · ') || 'Chưa có'}
                            </span>
                          </div>
                        </div>

                        <div className="flex flex-wrap items-center gap-2">
                          {confirmingReset ? (
                            <div className="flex items-center gap-1">
                              <button
                                type="button"
                                disabled={isBusy}
                                onClick={() => handleResetPasswords(rec.slug)}
                                className="btn btn-sm btn-accent"
                              >
                                <KeyRound className="w-3.5 h-3.5" />
                                <span>Xác nhận Reset (1111 / 1234)</span>
                              </button>
                              <button
                                type="button"
                                onClick={() => setConfirmResetSlug(null)}
                                className="btn btn-sm"
                                style={{ background: '#64748B' }}
                              >
                                Hủy
                              </button>
                            </div>
                          ) : (
                            <button
                              type="button"
                              disabled={isBusy}
                              onClick={() => {
                                setConfirmDeleteSlug(null);
                                setConfirmResetSlug(rec.slug);
                              }}
                              className="btn btn-sm btn-accent"
                              title="Reset mật khẩu vào game về 1111 và Passcode phụ huynh về 1234"
                            >
                              <RotateCcw className="w-3.5 h-3.5" />
                              <span>Reset 2 Mật Khẩu</span>
                            </button>
                          )}

                          {confirmingDel ? (
                            <div className="flex items-center gap-1">
                              <button
                                type="button"
                                disabled={isBusy || isB2KS}
                                onClick={() => handleDeleteNeighborhood(rec.slug)}
                                className="btn btn-sm btn-danger"
                              >
                                <Trash2 className="w-3.5 h-3.5" />
                                <span>Xóa vĩnh viễn</span>
                              </button>
                              <button
                                type="button"
                                onClick={() => setConfirmDeleteSlug(null)}
                                className="btn btn-sm"
                                style={{ background: '#64748B' }}
                              >
                                Hủy
                              </button>
                            </div>
                          ) : (
                            <button
                              type="button"
                              disabled={isB2KS || isBusy}
                              onClick={() => {
                                setConfirmResetSlug(null);
                                setConfirmDeleteSlug(rec.slug);
                              }}
                              title={isB2KS ? 'Không thể xóa khu phố gốc B2KS' : `Xóa khu phố ${rec.familyName}`}
                              className="btn btn-sm bg-rose-100 text-rose-700 border border-rose-300 disabled:opacity-40 disabled:cursor-not-allowed"
                            >
                              <Trash2 className="w-3.5 h-3.5" />
                              <span>Xóa</span>
                            </button>
                          )}
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            </>
          )}

          {tab === 'parent_points' && (
            <div className="space-y-3">
              <div className="rounded-xl border-2 border-amber-300 bg-amber-50 p-3 text-xs text-amber-950">
                Tại đây Admin <b>Bố B2KS</b> có thể điều chỉnh <b>điểm ngân sách hàng ngày</b>, <b>điểm số tối đa của Phụ huynh</b> (mặc định 500⭐ — đạt mức này ba mẹ sẽ không nhận thêm điểm) và <b>số điểm hiện có</b> của tất cả Phụ huynh (Bố/Mẹ) trong từng khu phố.
              </div>

              {records.map((rec) => {
                const isBusy = savingSlug === rec.slug;
                const allowVal = allowanceDrafts[rec.slug] ?? String(rec.dailyParentAllowance ?? 100);
                const maxPtsVal = maxPointsDrafts[rec.slug] ?? String(rec.maxParentPoints ?? 500);
                return (
                  <div
                    key={rec.slug}
                    className="rounded-xl border-2 border-[#2C3E50] bg-white p-3.5 space-y-3 shadow-sm"
                  >
                    <div className="flex flex-wrap items-center justify-between gap-2 border-b border-slate-200 pb-2">
                      <div className="flex items-center gap-2">
                        <span className="font-extrabold text-sm text-[#2C3E50]">
                          🏡 Gia đình {rec.familyName}
                        </span>
                        <span className="text-[11px] text-slate-500">
                          ({rec.parents.length} Phụ huynh · {rec.kidCount} con)
                        </span>
                      </div>
                      <div className="flex flex-wrap items-center gap-2.5">
                        <label className="text-xs font-bold text-amber-900 flex items-center gap-1.5">
                          <span>📅 Nhận hàng ngày:</span>
                          <input
                            type="number"
                            min={0}
                            max={10000}
                            value={allowVal}
                            onChange={(e) =>
                              setAllowanceDrafts((prev) => ({ ...prev, [rec.slug]: e.target.value }))
                            }
                            className="w-20 px-2 py-1 rounded-lg border-2 border-[#2C3E50] bg-amber-50 text-xs font-extrabold text-center"
                          />
                          <span>⭐/ngày</span>
                        </label>
                        <label className="text-xs font-bold text-violet-900 flex items-center gap-1.5">
                          <span>🔒 Điểm tối đa PH:</span>
                          <input
                            type="number"
                            min={0}
                            max={999999}
                            value={maxPtsVal}
                            onChange={(e) =>
                              setMaxPointsDrafts((prev) => ({ ...prev, [rec.slug]: e.target.value }))
                            }
                            className="w-20 px-2 py-1 rounded-lg border-2 border-[#2C3E50] bg-violet-50 text-xs font-extrabold text-center"
                          />
                          <span>⭐</span>
                        </label>
                        <button
                          type="button"
                          disabled={isBusy}
                          onClick={() => handleSaveParentAdjustment(rec)}
                          className="btn btn-sm btn-primary disabled:opacity-60"
                        >
                          <Save className="w-3.5 h-3.5" />
                          <span>{isBusy ? 'Đang lưu...' : 'Lưu khu phố này'}</span>
                        </button>
                      </div>
                    </div>

                    {rec.parents.length === 0 ? (
                      <div className="text-xs text-slate-400 italic">Khu phố này chưa có tài khoản Phụ huynh.</div>
                    ) : (
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                        {rec.parents.map((p) => {
                          const draftStr = parentPointDrafts[rec.slug]?.[p.id] ?? String(p.points ?? 0);
                          return (
                            <div
                              key={p.id}
                              className="rounded-xl border border-slate-300 bg-slate-50 p-2.5 space-y-2"
                            >
                              <div className="flex items-center justify-between text-xs font-bold">
                                <span>
                                  {p.role === 'Bố' ? '👨' : '👩'} {p.name}{' '}
                                  <span className="text-slate-500 font-normal">({p.role})</span>
                                </span>
                                <span className="points-pill text-[11px]">Hiện tại: {p.points}⭐</span>
                              </div>
                              <div className="flex items-center gap-1.5 flex-wrap">
                                <button
                                  type="button"
                                  onClick={() => bumpParentDraftPoint(rec.slug, p.id, p.points, -50)}
                                  className="px-2 py-1 rounded bg-rose-500 text-white text-[11px] font-bold cursor-pointer"
                                >
                                  -50⭐
                                </button>
                                <button
                                  type="button"
                                  onClick={() => bumpParentDraftPoint(rec.slug, p.id, p.points, +50)}
                                  className="px-2 py-1 rounded bg-emerald-500 text-white text-[11px] font-bold cursor-pointer"
                                >
                                  +50⭐
                                </button>
                                <button
                                  type="button"
                                  onClick={() => bumpParentDraftPoint(rec.slug, p.id, p.points, +100)}
                                  className="px-2 py-1 rounded bg-emerald-600 text-white text-[11px] font-bold cursor-pointer"
                                >
                                  +100⭐
                                </button>
                                <input
                                  type="number"
                                  min={0}
                                  max={999999}
                                  value={draftStr}
                                  onChange={(e) =>
                                    setParentPointDrafts((prev) => ({
                                      ...prev,
                                      [rec.slug]: {
                                        ...(prev[rec.slug] || {}),
                                        [p.id]: e.target.value,
                                      },
                                    }))
                                  }
                                  className="flex-1 min-w-[72px] px-2 py-1 rounded-lg border-2 border-[#2C3E50] bg-white text-xs font-extrabold text-center"
                                />
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}

          {tab === 'assets' && <AssetLibraryTab bridge={bridge} />}
        </div>
      </div>
    </div>
  );
};

