                          }`}
                        >
                          {tr.label}
                        </button>
                      );
                    })}
                  </div>
                </div>
              )}

              {selectedEntry.kind === 'pet' && (
                <div className="rounded-xl border border-amber-200 bg-amber-50/70 p-2.5 space-y-2 text-[11px]">
                  <div className="flex flex-wrap items-center gap-1.5">
