function renderSpeechBubble(
  dlg: ComicDialogue,
  panel: PanelRect,
  idx: number,
  totalInPanel: number,
  globalIdx: number,
  isActive: boolean,
  onSpeakLine: (text: string, idx: number) => void
): React.ReactNode {
  const maxChars = panel.w > 500 ? 44 : 27;
  const lines = wrapText(`${dlg.speaker}: ${dlg.text}`, maxChars);
  const lineH = 17;
  const boxW = Math.min(
    panel.w - 28,
    Math.max(150, Math.max(...lines.map((l) => l.length)) * 7.6 + 26)
  );
  const boxH = lines.length * lineH + 18;

  const yOffset = panel.y + 44 + idx * (boxH + 10);
  let bx = panel.x + 14;
  if (dlg.side === 'right') {
    bx = panel.x + panel.w - boxW - 14;
  } else if (dlg.side === 'center' || totalInPanel === 1) {
    bx = panel.x + (panel.w - boxW) / 2;
  }

  const tailX = bx + boxW * (dlg.side === 'right' ? 0.72 : dlg.side === 'left' ? 0.28 : 0.5);
  const isShout = dlg.bubbleType === 'shout';
  const isThought = dlg.bubbleType === 'thought';

  return (
    <g
      key={globalIdx}
      onClick={() => onSpeakLine(dlg.text, globalIdx)}
      style={{ cursor: 'pointer' }}
    >
      <polygon
        points={`${tailX - 8},${yOffset + boxH - 2} ${tailX + 8},${yOffset + boxH - 2} ${tailX},${yOffset + boxH + 13}`}
        fill={isActive ? '#FEF08A' : isShout ? '#FEF9C3' : '#FFFFFF'}
        stroke="#1E293B"
        strokeWidth="2.5"
      />
      <rect
        x={bx}
        y={yOffset}
        width={boxW}
        height={boxH}
        rx={isShout ? 6 : 14}
        fill={isActive ? '#FEF08A' : isShout ? '#FEF9C3' : '#FFFFFF'}
        stroke={isActive ? '#EA580C' : '#1E293B'}
        strokeWidth={isActive ? 3.5 : 2.5}
        strokeDasharray={isThought ? '5 3' : undefined}
      />
      {lines.map((ln, li) => (
        <text
          key={li}
          x={bx + 13}
          y={yOffset + 20 + li * lineH}
          fontSize="13.5"
          fontWeight={li === 0 ? '700' : '600'}
          fontFamily="Fredoka, Plus Jakarta Sans, sans-serif"
          fill="#0F172A"
        >
          {ln}
        </text>
      ))}
    </g>
  );
}

export const ComicPageSvg: React.FC<ComicPageSvgProps> = ({
  page,
  accentColor,
  activeSpeechIdx,
  onSpeakLine
}) => {
  const rects = getPanelRects(page.layout, page.panels.length);
  let dialogueCounter = 0;

  return (
    <svg
      viewBox="0 0 820 1040"
      className="w-full h-auto block select-none bg-[#FFFDF7] rounded-xl shadow-md border-2 border-[#1E293B]"
      role="img"
      aria-label={`Comic page ${page.pageNumber}`}
    >
      <rect x="0" y="0" width="820" height="1040" fill="#FFFDF7" rx="10" />

      {page.panels.map((panel: ComicPanel, pIdx: number) => {
        const rect = rects[pIdx] || rects[rects.length - 1];
        const theme = getSceneTheme(panel.scene);
        const clipId = `panel-clip-${page.pageNumber}-${pIdx}`;
        const gradId = `panel-grad-${page.pageNumber}-${pIdx}`;

        // Determine speakers to place cleanly along bottom floor of panel
        const speakers = Array.from(new Set(panel.dialogues.map((d) => d.speaker))).slice(0, 2);
        const charBaseY = rect.y + rect.h - 48;
        const capLines = panel.caption ? wrapText(panel.caption, rect.w > 500 ? 72 : 38) : [];

        return (
          <g key={pIdx}>
            <defs>
              <clipPath id={clipId}>
                <rect x={rect.x} y={rect.y} width={rect.w} height={rect.h} rx="10" />
              </clipPath>
              <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={theme.skyTop} />
                <stop offset="100%" stopColor={theme.skyBot} />
              </linearGradient>
            </defs>

            <g clipPath={`url(#${clipId})`}>
              {/* Background Sky */}
              <rect x={rect.x} y={rect.y} width={rect.w} height={rect.h} fill={`url(#${gradId})`} />

              {/* Stars or Sun */}
              {theme.stars &&
                [0.14, 0.28, 0.48, 0.68, 0.85, 0.22, 0.6, 0.78].map((sx, si) => (
                  <circle
                    key={si}
                    cx={rect.x + rect.w * sx}
                    cy={rect.y + 34 + ((si * 37) % 110)}
                    r={si % 3 === 0 ? 2.4 : 1.5}
                    fill="#FEF9C3"
                    opacity="0.85"
                  />
                ))}
              {theme.sun && (
                <circle cx={rect.x + rect.w * 0.8} cy={rect.y + 72} r="32" fill="#FDE047" opacity="0.9" />
              )}

              {/* Floor */}
              <rect
                x={rect.x}
                y={rect.y + rect.h - 76}
                width={rect.w}
                height="76"
                fill={theme.ground}
                opacity="0.92"
              />

              {/* Scene Props */}
              {renderPanelProp(panel.scene, rect)}

              {/* Characters */}
              {speakers.length === 1 && renderCharacterFigure(speakers[0], rect.x + rect.w * 0.34, charBaseY, 1.05)}
              {speakers.length >= 2 && (
                <>
                  {renderCharacterFigure(speakers[0], rect.x + rect.w * 0.25, charBaseY, 1)}
                  {renderCharacterFigure(speakers[1], rect.x + rect.w * 0.75, charBaseY, 1)}
                </>
              )}

              {/* Yellow Narration Caption Strip */}
              {capLines.length > 0 && (
                <g>
                  <rect
                    x={rect.x + 10}
                    y={rect.y + 8}
                    width={rect.w - 20}
                    height={capLines.length * 16 + 10}
                    rx="6"
                    fill="#FEF3C7"
                    stroke="#1E293B"
                    strokeWidth="2"
                  />
                  {capLines.map((cl, ci) => (
                    <text
                      key={ci}
                      x={rect.x + 20}
                      y={rect.y + 24 + ci * 16}
                      fontSize="12.5"
                      fontWeight="700"
                      fontFamily="Plus Jakarta Sans, Fredoka, sans-serif"
                      fill="#78350F"
                    >
                      {cl}
                    </text>
                  ))}
                </g>
              )}

              {/* Comic SFX Burst */}
              {panel.sfx && (
                <g transform={`translate(${rect.x + rect.w - 78},${rect.y + rect.h - 108}) rotate(-9)`}>
                  <polygon
                    points="-48,-16 -18,-22 0,-36 18,-20 50,-22 34,0 48,18 14,16 0,32 -18,16 -46,20 -32,0"
                    fill="#FACC15"
                    stroke="#DC2626"
                    strokeWidth="2.5"
                  />
                  <text
                    x="0"
                    y="6"
                    textAnchor="middle"
                    fontSize="14"
                    fontWeight="900"
                    fontFamily="Fredoka, sans-serif"
                    fill="#B91C1C"
                  >
                    {panel.sfx}
                  </text>
                </g>
              )}

              {/* Speech Balloons */}
              {panel.dialogues.map((dlg, di) => {
                const currentIdx = dialogueCounter++;
                return renderSpeechBubble(
                  dlg,
                  rect,
                  di,
                  panel.dialogues.length,
                  currentIdx,
                  activeSpeechIdx === currentIdx,
                  onSpeakLine
                );
              })}
            </g>

            {/* Ink Panel Border */}
            <rect
              x={rect.x}
              y={rect.y}
              width={rect.w}
              height={rect.h}
              rx="10"
              fill="none"
              stroke="#1E293B"
              strokeWidth="4"
            />
          </g>
        );
      })}

      {/* Bottom Page Folio */}
      <rect x="355" y="1012" width="110" height="22" rx="6" fill={accentColor} />
      <text
        x="410"
        y="1027"
        textAnchor="middle"
        fontSize="12"
        fontWeight="700"
        fill="#FFFFFF"
        fontFamily="Fredoka, sans-serif"
      >
        Page {page.pageNumber}
      </text>
    </svg>
  );
};

import React, { useState } from 'react';
import { Gift, Plus, ShieldCheck, Sparkles, Trash2, X } from 'lucide-react';
import { B2KSBridge, CrossWorldItem, CrossWorldRequest } from '../types/b2ks';

interface Props {
  bridge: B2KSBridge;
  onClose: () => void;
}

export const CrossWorldModal: React.FC<Props> = ({ bridge, onClose }) => {
  const [tab, setTab] = useState<'shop' | 'history' | 'manage'>('shop');
  const [, setTick] = useState(0);

  // Parent management form state
  const [newName, setNewName] = useState('');
  const [newIcon, setNewIcon] = useState('💵');
  const [newCategory, setNewCategory] = useState<'money' | 'privilege'>('privilege');
  const [newPoints, setNewPoints] = useState(100);
  const [newRealValue, setNewRealValue] = useState('');
  const [newQty, setNewQty] = useState(1);

  const state = bridge.getState();
  const user = bridge.getCurrentUser();
  const isUserParent = bridge.isParent(user);

  const forceRefresh = () => setTick((t) => t + 1);

  const handleOpenManageTab = () => {
    bridge.playClick();
    if (isUserParent) {
      setTab('manage');
    } else {
      bridge.requestParentAccess(() => {
        setTab('manage');
        forceRefresh();
      });
    }
  };

  const handleRedeem = (item: CrossWorldItem) => {
    if (item.quantity <= 0) {
      bridge.playError();
      bridge.showToast('⚠️ Vật phẩm này đã hết hàng!');
      return;
    }
    if (user.points < item.pointsCost) {
      bridge.playError();
      bridge.showToast(`❌ Bạn cần ${item.pointsCost}⭐ để đổi "${item.name}"!`);
      return;
    }

    user.points -= item.pointsCost;
    item.quantity -= 1;

    // Remove item from shelf once exchanged/depleted
    if (item.quantity <= 0) {
      state.crossWorldItems = state.crossWorldItems.filter((x) => x.id !== item.id);
    }

    const req: CrossWorldRequest = {
      id: `cw_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
      childId: user.id,
      childName: user.name,
      itemId: item.id,
      itemName: item.name,
      itemIcon: item.icon,
      pointsCost: item.pointsCost,
      realValue: item.realValue,
      status: 'pending',
      createdAt: Date.now(),
      approvedAt: null,
      approvedBy: null,
    };

    state.crossWorldRequests.unshift(req);
    bridge.logActivity({
      memberId: user.id,
      memberName: user.name,
      action: 'cross_world',
      detail: `Đổi quà xuyên thế giới: ${item.name} (${item.realValue}) - ${item.pointsCost}⭐`,
    });

    bridge.syncCrossWorldRequestsToFirebase(state.crossWorldRequests);
