                  />
                </div>
                <button
                  type="submit"
                  className="w-full py-2 rounded-lg bg-violet-500 hover:bg-violet-400 text-white font-bold text-xs cursor-pointer"
                >
                  ➕ Thêm Vào Kệ Giao Dịch
