      const fb = deps.getFirebaseUrl();
      badge.textContent = fb ? '🟢 ONLINE 4 MÁY' : '🟡 ĐỒNG BỘ CỤC BỘ';
      badge.style.background = fb ? '#27AE60' : '#F39C12';
