          vouchers: m.vouchers || [],
          customLabItems: m.customLabItems || [],
          roomSlots: m.roomSlots || {},
          roomSlotSpecs: m.roomSlotSpecs || {},
          roomDecor: m.roomDecor || [],
          roomDecorSpecs: m.roomDecorSpecs || {},
          inventoryConsumedMigrated: Boolean(m.inventoryConsumedMigrated),
