        privacyBtn.textContent = unlocked ? '🔓 Đang mở' : '🔒 Khóa';
        privacyBtn.style.background = unlocked ? '#D1FAE5' : '#FEE2E2';
        privacyBtn.style.borderColor = unlocked ? '#059669' : '#DC2626';
        privacyBtn.style.color = unlocked ? '#065F46' : '#991B1B';
