        <div style="font-size:15.5px; font-weight:700; color:#2C3E50; margin-bottom:12px; line-height:1.45;">
          ${qNum}. ${escapeHtml(qObj.q)}
        </div>
        <div id="eng-options-list" style="display:flex; flex-direction:column; gap:8px;">
          ${qObj.opts
