    const ctrlEl = document.getElementById('fashion-tryon-controls');
    const labels: string[] = [];
    if (setIt) labels.push(setIt.name);
    if (shirtIt) labels.push(shirtIt.name);
    if (pantsIt) labels.push(pantsIt.name);
    if (accIt) labels.push(accIt.name);
