        clean.forEach((s) => {
          if (byId.has(s.id)) updated += 1;
          else added += 1;
          byId.set(s.id, s);
        });
        nextBank = Array.from(byId.values());
      }
      saveSharedSpeakingBank(nextBank, Date.now(), true);
      notifySubscribers();
      return {
