  function gameLoop() {
    const nowPerf = performance.now();
    const deltaSec = Math.max(0, Math.min(2, (nowPerf - lastGameLoopPerf) / 1000));
    lastGameLoopPerf = nowPerf;

    const me = getCurrentUser();
