import { EnglishQuestion } from '../types/b2ks';
import { CURRICULUM_GRADES_6_7, RawUnitCurriculum } from './englishData67';
import { CURRICULUM_GRADES_8_9 } from './englishData89';

export const CURRICULUM_BANK_VERSION = 2; // Global Success 6-9 (1920 items)

export interface GlobalSuccessUnitMeta {
  grade: 6 | 7 | 8 | 9;
  unit: number;
  title: string;
  grammarFocus: string;
}

const ALL_RAW_UNITS: RawUnitCurriculum[] = [...CURRICULUM_GRADES_6_7, ...CURRICULUM_GRADES_8_9];

export const GLOBAL_SUCCESS_UNITS: GlobalSuccessUnitMeta[] = ALL_RAW_UNITS.map((u) => ({
  grade: u.grade,
  unit: u.unit,
  title: u.title,
  grammarFocus: u.grammarFocus,
}));

export function getGlobalSuccessUnitMeta(grade: number, unit: number): GlobalSuccessUnitMeta | undefined {
  return GLOBAL_SUCCESS_UNITS.find((u) => u.grade === grade && u.unit === unit);
}

export function getGlobalSuccessUnitTitle(grade: number, unit: number): string {
  const meta = getGlobalSuccessUnitMeta(grade, unit);
  return meta ? `Unit ${meta.unit}: ${meta.title}` : `Unit ${unit}`;
}

function buildFourOptions<T>(
  allItems: T[],
  correctIdx: number,
  seed: number,
  getLabel: (item: T) => string
): { opts: [string, string, string, string]; ans: number } {
  const correctLabel = getLabel(allItems[correctIdx]);
  const distractors: string[] = [];
  const total = allItems.length;
  for (let offset = 1; offset < total && distractors.length < 3; offset++) {
    const candidateIdx = (correctIdx + offset * 3 + seed) % total;
    const label = getLabel(allItems[candidateIdx]);
    if (label && label !== correctLabel && !distractors.includes(label)) {
      distractors.push(label);
    }
  }
  for (let i = 0; i < total && distractors.length < 3; i++) {
    const label = getLabel(allItems[i]);
    if (label && label !== correctLabel && !distractors.includes(label)) {
      distractors.push(label);
    }
  }
  const ansPos = (correctIdx * 3 + seed) % 4;
  const opts: string[] = [];
  let dPtr = 0;
  for (let pos = 0; pos < 4; pos++) {
    if (pos === ansPos) {
      opts.push(correctLabel);
    } else {
      opts.push(distractors[dPtr++] || 'N/A');
    }
  }
  return {
    opts: [opts[0], opts[1], opts[2], opts[3]],
    ans: ansPos,
  };
}

function expandCurriculumBank(): EnglishQuestion[] {
  const bank: EnglishQuestion[] = [];

  for (const unitDef of ALL_RAW_UNITS) {
    const unitTitle = `Unit ${unitDef.unit}: ${unitDef.title}`;
    const vList = unitDef.vocab;

    // 1. 10 Contextual fill-in-the-blank Vocab questions
    vList.forEach(([word, viMeaning, sentence], idx) => {
      const { opts, ans } = buildFourOptions(vList, idx, unitDef.unit + unitDef.grade, (item) => item[0]);
      bank.push({
        id: `gs_g${unitDef.grade}_u${unitDef.unit}_v${idx + 1}`,
        cat: 'vocab',
        grade: unitDef.grade,
        unit: unitDef.unit,
        unitTitle,
        q: sentence,
        opts,
        ans,
        exp: `"${word}" nghĩa là "${viMeaning}" (${unitTitle} - Lớp ${unitDef.grade}).`,
      });
    });

    // 2. 5 English -> Vietnamese + 5 Vietnamese -> English Vocab questions (Total = 20 Vocab / Unit)
    vList.forEach(([word, viMeaning], idx) => {
      if (idx < 5) {
        const { opts, ans } = buildFourOptions(vList, idx, unitDef.unit * 2 + 1, (item) => item[1]);
        bank.push({
          id: `gs_g${unitDef.grade}_u${unitDef.unit}_v${idx + 11}`,
          cat: 'vocab',
          grade: unitDef.grade,
          unit: unitDef.unit,
          unitTitle,
          q: `What does "${word}" mean in Vietnamese? (Global Success ${unitDef.grade} - Unit ${unitDef.unit})`,
          opts,
          ans,
          exp: `Trong ${unitTitle} (Lớp ${unitDef.grade}), "${word}" có nghĩa là "${viMeaning}".`,
        });
      } else {
        const { opts, ans } = buildFourOptions(vList, idx, unitDef.unit * 3 + 2, (item) => item[0]);
        bank.push({
          id: `gs_g${unitDef.grade}_u${unitDef.unit}_v${idx + 11}`,
          cat: 'vocab',
          grade: unitDef.grade,
          unit: unitDef.unit,
          unitTitle,
          q: `Which English word or phrase means "${viMeaning}"? (Unit ${unitDef.unit}: ${unitDef.title})`,
          opts,
          ans,
          exp: `Từ tiếng Anh tương ứng với "${viMeaning}" là "${word}".`,
        });
      }
    });

    // 3. 20 Distinct Grammar questions per Unit
    unitDef.grammar.forEach(([q, opts, ans, exp], idx) => {
      bank.push({
        id: `gs_g${unitDef.grade}_u${unitDef.unit}_g${idx + 1}`,
        cat: 'grammar',
        grade: unitDef.grade,
        unit: unitDef.unit,
        unitTitle,
        q,
        opts: [opts[0], opts[1], opts[2], opts[3]],
        ans,
        exp,
      });
    });
  }

  return bank;
}

export const GLOBAL_SUCCESS_ENGLISH_BANK: EnglishQuestion[] = expandCurriculumBank();

function escapeCsvCell(val: string | number | undefined): string {
  const s = String(val ?? '');
  if (s.includes('"') || s.includes(',') || s.includes('\n') || s.includes('\r')) {
    return `"${s.replace(/"/g, '""')}"`;
  }
  return s;
}

export function exportEnglishBankToCsv(questions: EnglishQuestion[]): string {
  const header = ['id', 'grade', 'unit', 'cat', 'q', 'optA', 'optB', 'optC', 'optD', 'ans', 'exp'];
  const ansLetters = ['A', 'B', 'C', 'D'];
  const lines = [header.join(',')];
  questions.forEach((item) => {
    const row = [
      escapeCsvCell(item.id),
      escapeCsvCell(item.grade ?? 6),
      escapeCsvCell(item.unit ?? 1),
      escapeCsvCell(item.cat),
      escapeCsvCell(item.q),
      escapeCsvCell(item.opts[0] || ''),
      escapeCsvCell(item.opts[1] || ''),
      escapeCsvCell(item.opts[2] || ''),
      escapeCsvCell(item.opts[3] || ''),
      escapeCsvCell(ansLetters[item.ans] || 'A'),
      escapeCsvCell(item.exp || ''),
    ];
    lines.push(row.join(','));
  });
  return '\uFEFF' + lines.join('\r\n');
}

export function parseCsvRows(rawText: string): string[][] {
  const text = rawText.replace(/^\uFEFF/, '');
  const rows: string[][] = [];
  let row: string[] = [];
  let cell = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          cell += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        cell += ch;
      }
    } else {
      if (ch === '"') {
        inQuotes = true;
      } else if (ch === ',') {
        row.push(cell);
        cell = '';
      } else if (ch === '\r') {
        if (text[i + 1] === '\n') i++;
        row.push(cell);
        if (row.some((c) => c.trim() !== '')) rows.push(row);
        row = [];
        cell = '';
      } else if (ch === '\n') {
        row.push(cell);
        if (row.some((c) => c.trim() !== '')) rows.push(row);
        row = [];
        cell = '';
      } else {
        cell += ch;
      }
    }
  }
  if (cell.length > 0 || row.length > 0) {
    row.push(cell);
    if (row.some((c) => c.trim() !== '')) rows.push(row);
  }
  return rows;
}

export function parseEnglishBankCsv(csvText: string): { questions: EnglishQuestion[]; errors: number } {
  const rows = parseCsvRows(csvText);
  if (rows.length === 0) return { questions: [], errors: 0 };

  let startIdx = 0;
  const firstRowLower = rows[0].map((c) => c.trim().toLowerCase());
  const colIdx = {
    id: firstRowLower.indexOf('id'),
    grade: firstRowLower.indexOf('grade'),
    unit: firstRowLower.indexOf('unit'),
    cat: firstRowLower.indexOf('cat'),
    q: firstRowLower.indexOf('q'),
    optA: firstRowLower.indexOf('opta'),
    optB: firstRowLower.indexOf('optb'),
    optC: firstRowLower.indexOf('optc'),
    optD: firstRowLower.indexOf('optd'),
    ans: firstRowLower.indexOf('ans'),
    exp: firstRowLower.indexOf('exp'),
  };

  if (colIdx.q !== -1 && colIdx.optA !== -1) {
    startIdx = 1;
  } else {
    // Fallback fixed column order: id,grade,unit,cat,q,optA,optB,optC,optD,ans,exp
    colIdx.id = 0;
    colIdx.grade = 1;
    colIdx.unit = 2;
    colIdx.cat = 3;
    colIdx.q = 4;
    colIdx.optA = 5;
    colIdx.optB = 6;
    colIdx.optC = 7;
    colIdx.optD = 8;
    colIdx.ans = 9;
    colIdx.exp = 10;
  }

  const out: EnglishQuestion[] = [];
  let errors = 0;

  for (let r = startIdx; r < rows.length; r++) {
    const cells = rows[r];
    const qText = (cells[colIdx.q] || '').trim();
    const o0 = (cells[colIdx.optA] || '').trim();
    const o1 = (cells[colIdx.optB] || '').trim();
    const o2 = (cells[colIdx.optC] || '').trim();
    const o3 = (cells[colIdx.optD] || '').trim();
    if (!qText || !o0 || !o1 || !o2 || !o3) {
      errors++;
      continue;
    }

    const gradeNum = Number((cells[colIdx.grade] || '6').trim());
    const grade = (gradeNum === 7 || gradeNum === 8 || gradeNum === 9 ? gradeNum : 6) as 6 | 7 | 8 | 9;
    const unitNum = Math.max(1, Math.min(12, Math.round(Number((cells[colIdx.unit] || '1').trim()) || 1)));
    const catRaw = (cells[colIdx.cat] || 'vocab').trim().toLowerCase();
    const cat: 'grammar' | 'vocab' = catRaw === 'grammar' || catRaw === 'ngữ pháp' ? 'grammar' : 'vocab';

    const ansRaw = (cells[colIdx.ans] || 'A').trim().toUpperCase();
    let ans = 0;
    if (ansRaw === 'B' || ansRaw === '1') ans = 1;
    else if (ansRaw === 'C' || ansRaw === '2') ans = 2;
    else if (ansRaw === 'D' || ansRaw === '3') ans = 3;
    else if (ansRaw === '4') ans = 3;
    else if (ansRaw === 'A' || ansRaw === '0') ans = 0;

    const rawId = (colIdx.id >= 0 ? cells[colIdx.id] : '')?.trim();
    const exp = (colIdx.exp >= 0 ? cells[colIdx.exp] : '')?.trim() || `Global Success ${grade} - Unit ${unitNum}`;

    out.push({
      id: rawId || `csv_g${grade}_u${unitNum}_${cat}_${r}_${Date.now()}`,
      grade,
      unit: unitNum,
      unitTitle: getGlobalSuccessUnitTitle(grade, unitNum),
      cat,
      q: qText,
      opts: [o0, o1, o2, o3],
      ans,
      exp,
      custom: !rawId || !rawId.startsWith('gs_'),
    });
  }

  return { questions: out, errors };
}

/**
 * ============================================================================
 * B2KS 3D GAME CONTROLLER (Tap-to-move, Isometric Camera, Input Routing)
 * ============================================================================
 * File này kết nối logic game B2KS với hệ thống đồ họa 3D (scene3d.js):
 * - Tap-to-move: chạm trực tiếp lên mặt đất 3D để nhân vật tự đi tới
 * - Điều khiển hướng chuẩn góc nhìn Isometric (WASD / Phím mũi tên / Joystick ảo)
 * - Thao tác vuốt/kéo để xoay hoặc lia camera, chụm ngón tay / cuộn chuột để zoom
 */

import { createScene3D } from './scene3d.js';

function clamp(val, min, max) {
  return Math.max(min, Math.min(max, val));
}

export function createB2KS3DController({ canvasEl, labelLayerEl, isUnlocked, onZoomSync }) {
  let scene3d = null;
  let tapTarget = null;
  let sceneBounds = { minX: 40, maxX: 2480, minY: 265, maxY: 1660 };

  const activePointers = new Map();
  let tapCandidate = null;
  let lastPointer = null;
  let pinchStartDist = 0;
  let pinchStartZoom = 1.0;

  // Khởi tạo Three.js 3D Engine (qua CDN importmap)
  createScene3D(canvasEl)
    .then((inst) => {
      scene3d = inst;
      scene3d.resize();
      if (onZoomSync) onZoomSync(scene3d.camState.targetZoom);
    })
    .catch((err) => {
      console.error('[B2KS 3D] Không thể khởi tạo WebGL 3D:', err);
    });

  // Ngăn menu chuột phải mặc định trên canvas để chuột phải kéo lia camera mượt hơn
  canvasEl.addEventListener('contextmenu', (e) => {
    e.preventDefault();
  });

  // Cuộn chuột để Zoom
  canvasEl.addEventListener(
    'wheel',
    (e) => {
      if (!scene3d || !isUnlocked()) return;
      e.preventDefault();
      const nextZoom = clamp(scene3d.camState.targetZoom - e.deltaY * 0.0012, 0.55, 2.2);
      scene3d.setZoom(nextZoom);
      if (onZoomSync) onZoomSync(nextZoom);
    },
    { passive: false }
  );

  // Chạm / Nhấn chuột: Tap-to-move & Vuốt xoay/lia Camera & Pinch Zoom
  canvasEl.addEventListener('pointerdown', (e) => {
    if (!isUnlocked()) return;
    if (typeof window.startAudioOnce === 'function') window.startAudioOnce();
    try {
      canvasEl.setPointerCapture(e.pointerId);
    } catch {
      // ignore if synthetic event
    }
    activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });

    if (activePointers.size === 1) {
      tapCandidate = {
        id: e.pointerId,
        startX: e.clientX,
        startY: e.clientY,
        moved: false,
        button: e.button,
      };
      lastPointer = { x: e.clientX, y: e.clientY };
    } else if (activePointers.size === 2 && scene3d) {
      tapCandidate = null;
      const pts = Array.from(activePointers.values());
      pinchStartDist = Math.max(10, Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y));
      pinchStartZoom = scene3d.camState.targetZoom;
      lastPointer = {
        x: (pts[0].x + pts[1].x) * 0.5,
        y: (pts[0].y + pts[1].y) * 0.5,
      };
    }
  });

  canvasEl.addEventListener('pointermove', (e) => {
    if (!activePointers.has(e.pointerId)) return;
    activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    if (!scene3d || !isUnlocked()) return;

    if (activePointers.size === 2) {
      const pts = Array.from(activePointers.values());
      const dist = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y);
      const midX = (pts[0].x + pts[1].x) * 0.5;
      const midY = (pts[0].y + pts[1].y) * 0.5;

      const nextZoom = clamp(pinchStartZoom * (dist / pinchStartDist), 0.55, 2.2);
      scene3d.setZoom(nextZoom);
      if (onZoomSync) onZoomSync(nextZoom);

      if (lastPointer) {
        const dx = midX - lastPointer.x;
        const dy = midY - lastPointer.y;
        panCameraByScreenDelta(dx, dy);
      }
      lastPointer = { x: midX, y: midY };
      return;
    }

    if (activePointers.size === 1 && lastPointer) {
      const dx = e.clientX - lastPointer.x;
      const dy = e.clientY - lastPointer.y;
      if (tapCandidate && Math.hypot(e.clientX - tapCandidate.startX, e.clientY - tapCandidate.startY) > 8) {
        tapCandidate.moved = true;
      }

      if ((tapCandidate && tapCandidate.moved) || (e.buttons & 2) !== 0) {
        if ((e.buttons & 2) !== 0 || e.shiftKey) {
          // Chuột phải hoặc giữ Shift: lia (pan) camera trên mặt đất
          panCameraByScreenDelta(dx, dy);
        } else {
          // Kéo 1 ngón hoặc chuột trái: xoay góc nhìn Isometric quanh nhân vật
          scene3d.camState.targetYaw -= dx * 0.007;
          scene3d.camState.targetPitch = clamp(scene3d.camState.targetPitch + dy * 0.005, 0.42, 1.15);
        }
      }
      lastPointer = { x: e.clientX, y: e.clientY };
    }
  });

  function finishPointer(e, allowTap) {
    activePointers.delete(e.pointerId);
    if (allowTap && activePointers.size === 0 && tapCandidate && !tapCandidate.moved && tapCandidate.button !== 2) {
      if (scene3d && isUnlocked()) {
        const hit = scene3d.raycastGround(e.clientX, e.clientY);
        if (hit) {
          tapTarget = {
            x: clamp(hit.x2d, sceneBounds.minX, sceneBounds.maxX),
            y: clamp(hit.y2d, sceneBounds.minY, sceneBounds.maxY),
          };
        }
      }
    }
    if (activePointers.size === 1) {
      const rem = Array.from(activePointers.values())[0];
      lastPointer = { x: rem.x, y: rem.y };
      tapCandidate = null;
    } else if (activePointers.size === 0) {
      lastPointer = null;
      tapCandidate = null;
    }
  }

  canvasEl.addEventListener('pointerup', (e) => finishPointer(e, true));
  canvasEl.addEventListener('pointercancel', (e) => finishPointer(e, false));

  function panCameraByScreenDelta(dx, dy) {
    if (!scene3d) return;
    const yaw = scene3d.camState.yaw;
    const scale = 0.05 / Math.max(0.5, scene3d.camState.zoom);
    const sx = -dx * scale;
    const sy = -dy * scale;
    const worldDX = sx * Math.cos(yaw) + sy * Math.sin(yaw);
    const worldDZ = -sx * Math.sin(yaw) + sy * Math.cos(yaw);
    scene3d.camState.panX = clamp(scene3d.camState.panX + worldDX, -45, 45);
    scene3d.camState.panZ = clamp(scene3d.camState.panZ + worldDZ, -45, 45);
  }

  function updateSceneBounds(sceneName, houseHeight) {
    if (sceneName === 'neighborhood') {
      sceneBounds = { minX: 40, maxX: 2480, minY: 265, maxY: 1660 };
    } else if (sceneName === 'private_room') {
      sceneBounds = { minX: 12, maxX: 748, minY: 16, maxY: 406 };
    } else {
      sceneBounds = { minX: 100, maxX: 1020, minY: 110, maxY: (houseHeight || 800) - 55 };
    }
  }

  /**
   * Tính vector di chuyển chuẩn theo góc camera Isometric hiện tại + hỗ trợ Tap-to-move
   */
  function computeInputVector({ keys, joyActive, joyVector, me, speed, sceneName, houseHeight }) {
    updateSceneBounds(sceneName, houseHeight);

    let sx = 0;
    let sy = 0;
    if (keys['arrowup'] || keys['w']) sy -= 1;
    if (keys['arrowdown'] || keys['s']) sy += 1;
    if (keys['arrowleft'] || keys['a']) sx -= 1;
    if (keys['arrowright'] || keys['d']) sx += 1;
    if (joyActive) {
      sx = joyVector.x;
      sy = joyVector.y;
    }

    const inputLen = Math.hypot(sx, sy);
    if (inputLen > 0.05) {
      tapTarget = null; // Ưu tiên phím điều hướng / joystick nếu người chơi đang nhấn
      if (inputLen > 1) {
        sx /= inputLen;
        sy /= inputLen;
      }
      const yaw = scene3d ? scene3d.camState.yaw : Math.PI / 4;
      const dx = sx * Math.cos(yaw) + sy * Math.sin(yaw);
      const dy = -sx * Math.sin(yaw) + sy * Math.cos(yaw);
      return { dx, dy, moving: true, viaTap: false };
    }

    if (tapTarget) {
      const dx = tapTarget.x - me.x;
      const dy = tapTarget.y - me.y;
      const dist = Math.hypot(dx, dy);
      if (dist <= Math.max(8, speed * 1.8)) {
        tapTarget = null;
        return { dx: 0, dy: 0, moving: false, viaTap: false };
      }
      return { dx: dx / dist, dy: dy / dist, moving: true, viaTap: true };
    }

    return { dx: 0, dy: 0, moving: false, viaTap: false };
  }

  return {
    computeInputVector,
    clearTapTarget() {
      tapTarget = null;
    },
    setZoom(nextZoom) {
      if (!scene3d) return nextZoom;
      scene3d.setZoom(nextZoom);
      return scene3d.camState.targetZoom;
    },
    getZoom() {
      return scene3d ? scene3d.camState.targetZoom : 1.0;
    },
    getCamYaw() {
      return scene3d ? scene3d.camState.yaw : Math.PI / 4;
    },
    resetCamera() {
      if (scene3d) scene3d.resetCamera();
    },
    onResize() {
      if (scene3d) scene3d.resize();
    },
    render(renderParams) {
      if (!scene3d) return;
      scene3d.renderFrame({
        ...renderParams,
        tapTarget,
        labelLayerEl,
      });
    },
    dispose() {
      if (scene3d) scene3d.dispose();
    },
  };
}

