      <!-- Dragon Claws -->
      <ellipse cx="30" cy="64" rx="5.5" ry="3.4" fill="${c1}" stroke="#2C3E50" stroke-width="2"/>
      <ellipse cx="50" cy="64" rx="5.5" ry="3.4" fill="${c1}" stroke="#2C3E50" stroke-width="2"/>
