  return `
    <svg width="${size}" height="${size}" viewBox="0 0 80 80" xmlns="http://www.w3.org/2000/svg">
      ${auraRing}
      <ellipse cx="40" cy="68" rx="19" ry="5" fill="rgba(0,0,0,0.16)"/>
      <g transform="translate(40,42) scale(${stageScale}) translate(-40,-42)">
        ${art}
        ${crownSvg}
      </g>
      ${stageStars}
    </svg>
  `;
}

/**
 * Draw active companion pet trailing beside/behind owner character on Canvas2D
 * with clearly distinct species silhouettes & evolution stages!
 */
export function drawCompanionPetOnContext(
  ctx: CanvasRenderingContext2D,
  owner: Member,
  isMoving: boolean
) {
  const pet = getActivePet(owner);
  if (!pet) return;

  const sp = getPetSpecies(pet.speciesId);
  const resolved = getPetResolvedColors(sp, pet.variant);
  const c1 = resolved.primary;
  const c2 = resolved.accent;
  const stageDef = sp.stages.find((s) => s.stage === pet.stage) || sp.stages[0];
  const dir = owner.dir || 'down';
  const t = Date.now();

  let ox = -30;
  let oy = 12;
  if (dir === 'left') { ox = 32; oy = 10; }
  else if (dir === 'right') { ox = -32; oy = 10; }
  else if (dir === 'up') { ox = 26; oy = 18; }
  else { ox = -28; oy = 8; }

  const px = owner.x + ox;
  const py = owner.y + oy;
  const bounce = isMoving ? Math.abs(Math.sin(t / 110)) * 5.8 : Math.sin(t / 320) * 1.9;
  const scale = stageDef.scale * 0.78;
  const isRightBaseSpecies = sp.id === 'pet_corgi' || sp.id === 'pet_unicorn';
  const flipX =
    dir === 'left'
      ? (isRightBaseSpecies ? -1 : 1)
      : dir === 'right'
        ? (isRightBaseSpecies ? 1 : -1)
        : 1;
  const faceShiftX =
    dir === 'left' || dir === 'right'
      ? (isRightBaseSpecies ? 2.2 : -2.8)
      : 0;

  ctx.save();
  ctx.translate(px, py);

  ctx.fillStyle = 'rgba(0,0,0,0.22)';
  ctx.beginPath();
  ctx.ellipse(0, 12 * scale, 15 * scale, 5 * scale, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.translate(0, -bounce);
  ctx.scale(scale * flipX, scale);

  if (!pet.hatched) {
    const wobble = Math.sin(t / 240) * 0.09;
    ctx.rotate(wobble);
    ctx.fillStyle = c2;
    ctx.strokeStyle = '#2C3E50';
    ctx.lineWidth = 2.6;
    ctx.beginPath();
    ctx.ellipse(0, -4, 13, 17, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    ctx.strokeStyle = c1;
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(-10, -4); ctx.lineTo(-4, -8); ctx.lineTo(3, -3); ctx.lineTo(10, -6);
    ctx.stroke();

    ctx.restore();
    ctx.save();
    ctx.font = 'bold 9px Fredoka, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#FEF3C7';
    ctx.strokeStyle = '#2C3E50';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.roundRect(px - 22, py - 28, 44, 13, 6);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#92400E';
    ctx.fillText(`🥚 ${Math.round(pet.hatchProgress)}%`, px, py - 18);
    ctx.restore();
    return;
  }

  // Stage >= 2 or rare variant pulsing aura
  if (pet.stage >= 2 || resolved.isRare) {
    ctx.save();
    ctx.strokeStyle = resolved.auraColor;
    ctx.globalAlpha = 0.5 + Math.sin(t / 220) * 0.25;
    ctx.lineWidth = pet.stage >= 3 ? 2.8 : 2;
    ctx.beginPath();
    ctx.arc(0, -9, pet.stage >= 4 ? 26 : 22, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  }

  const flap = Math.sin(t / 120) * 0.35;
  ctx.strokeStyle = '#2C3E50';
  ctx.lineWidth = 2.4;

  // Wings (species-specific styling + stage 3+ unlocks wings for all pets!)
  if (pet.stage >= 3 || sp.id === 'pet_owl' || sp.id === 'pet_phoenix' || (sp.id === 'pet_dragon' && pet.stage >= 2)) {
    const wingColor =
      sp.id === 'pet_phoenix' ? '#FACC15' :
      sp.id === 'pet_dragon' ? '#F59E0B' :
      sp.id === 'pet_unicorn' ? '#FFFFFF' :
      sp.id === 'pet_kitty' ? '#F9A8D4' :
      sp.id === 'pet_owl' ? c1 : c2;
    [-1, 1].forEach((side) => {
      ctx.save();
      ctx.translate(side * 14, -6);
      ctx.rotate(side * (0.35 - flap));
      ctx.fillStyle = wingColor;
      ctx.beginPath();
      if (sp.id === 'pet_dragon') {
        ctx.moveTo(0, 0); ctx.lineTo(side * 15, -11); ctx.lineTo(side * 13, 5); ctx.lineTo(side * 5, 2); ctx.closePath();
      } else {
        ctx.ellipse(side * 7, 0, sp.id === 'pet_phoenix' ? 12 : 9.5, 5, 0, 0, Math.PI * 2);
      }
      ctx.fill();
      ctx.stroke();
      ctx.restore();
    });
  }

  // Tail by species
  if (sp.id === 'pet_corgi') {
    ctx.fillStyle = '#FFF';
    ctx.beginPath(); ctx.arc(-18, -1, 5, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  } else if (sp.id === 'pet_kitty') {
    ctx.strokeStyle = c1; ctx.lineWidth = 4.5; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(11, 4); ctx.quadraticCurveTo(22, -4, 18, -16); ctx.stroke();
    ctx.strokeStyle = '#2C3E50'; ctx.lineWidth = 2.4;
  } else if (sp.id === 'pet_unicorn') {
    ctx.strokeStyle = '#EC4899'; ctx.lineWidth = 4.5; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(-14, 1); ctx.quadraticCurveTo(-24, 0, -21, 10); ctx.stroke();
    ctx.strokeStyle = '#38BDF8'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(-14, 3); ctx.quadraticCurveTo(-22, 4, -19, 12); ctx.stroke();
    ctx.strokeStyle = '#2C3E50'; ctx.lineWidth = 2.4;
  } else if (sp.id === 'pet_fox') {
    const tCount = pet.stage >= 3 ? 3 : pet.stage === 2 ? 2 : 1;
    for (let ti = 0; ti < tCount; ti++) {
      const ang = -0.3 + ti * 0.35;
      ctx.save();
      ctx.translate(10, 2);
      ctx.rotate(ang);
      ctx.fillStyle = c1;
      ctx.beginPath(); ctx.ellipse(9, -6, 9, 4.5, -0.5, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.fillStyle = '#FFF';
      ctx.beginPath(); ctx.arc(15, -10, 3.2, 0, Math.PI * 2); ctx.fill();
      ctx.restore();
    }
  } else if (sp.id === 'pet_phoenix') {
    ctx.strokeStyle = '#F59E0B'; ctx.lineWidth = 4.2; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(9, 4); ctx.quadraticCurveTo(23, 2, 22, -13); ctx.stroke();
    ctx.strokeStyle = '#2C3E50'; ctx.lineWidth = 2.4;
  } else if (sp.id === 'pet_dragon') {
    ctx.strokeStyle = c1; ctx.lineWidth = 4.5; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(11, 4); ctx.quadraticCurveTo(23, 3, 22, -10); ctx.stroke();
    ctx.fillStyle = '#FACC15'; ctx.strokeStyle = '#2C3E50'; ctx.lineWidth = 1.6;
    ctx.beginPath(); ctx.moveTo(22, -14); ctx.lineTo(18, -8); ctx.lineTo(26, -8); ctx.closePath(); ctx.fill(); ctx.stroke();
    ctx.lineWidth = 2.4;
  } else if (sp.id === 'pet_bunny') {
    ctx.fillStyle = '#FFF';
    ctx.beginPath(); ctx.arc(14, 4, 5.2, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  }

  // Body silhouette
  if (sp.id === 'pet_corgi') {
    // Wide loaf dog body + stubby legs
    ctx.fillStyle = '#FFF';
    ctx.fillRect(-13, 6, 5, 7); ctx.strokeRect(-13, 6, 5, 7);
    ctx.fillRect(6, 6, 5, 7); ctx.strokeRect(6, 6, 5, 7);
    ctx.fillStyle = c1;
    ctx.beginPath(); ctx.ellipse(-2, 1, 17, 10, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#FFF';
    ctx.beginPath(); ctx.ellipse(7, 2, 7, 7, 0, 0, Math.PI * 2); ctx.fill();
  } else if (sp.id === 'pet_unicorn') {
    ctx.fillStyle = c2;
    ctx.fillRect(-11, 5, 4.5, 8); ctx.strokeRect(-11, 5, 4.5, 8);
    ctx.fillRect(4, 5, 4.5, 8); ctx.strokeRect(4, 5, 4.5, 8);
    ctx.beginPath(); ctx.ellipse(-2, 0, 15, 9.5, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  } else if (sp.id === 'pet_owl' || sp.id === 'pet_penguin') {
    // Tall egg/oval bird body
    ctx.fillStyle = c1;
    ctx.beginPath(); ctx.ellipse(0, -6, 15, 19, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#FFFFFF';
    ctx.beginPath(); ctx.ellipse(0, 1, 10, 11, 0, 0, Math.PI * 2); ctx.fill();
    if (sp.id === 'pet_penguin') {
      ctx.fillStyle = '#F59E0B';
      ctx.beginPath(); ctx.ellipse(-6, 12, 5.5, 2.8, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.beginPath(); ctx.ellipse(6, 12, 5.5, 2.8, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    }
  } else {
    ctx.fillStyle = sp.id === 'pet_panda' ? '#FFFFFF' : c1;
    ctx.beginPath(); ctx.ellipse(0, 1, 13.5, 11.5, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    if (sp.id === 'pet_panda') {
      ctx.fillStyle = '#0F172A';
      ctx.fillRect(-12, -4, 24, 6);
    } else {
      ctx.fillStyle = sp.id === 'pet_dragon' ? '#FDE047' : sp.id === 'pet_phoenix' ? '#FEF08A' : '#FFFFFF';
      ctx.beginPath(); ctx.ellipse(0, 3, 7.5, 7.5, 0, 0, Math.PI * 2); ctx.fill();
    }
  }

  // Head & Ears (shifted along travel direction so every species visibly turns!)
  const headX = (isRightBaseSpecies ? 6 : 0) + faceShiftX;
  const headY = (sp.id === 'pet_owl' || sp.id === 'pet_penguin' ? -15 : -14) + (dir === 'up' ? -1.5 : 0);

  // Ears
  if (sp.id === 'pet_bunny') {
    ctx.fillStyle = c1;
    ctx.beginPath(); ctx.ellipse(headX - 6, headY - 16, 4, 10.5, -0.2, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.beginPath(); ctx.ellipse(headX + 6, headY - 16, 4, 10.5, 0.2, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  } else if (sp.id === 'pet_panda') {
    ctx.fillStyle = '#0F172A';
    ctx.beginPath(); ctx.arc(headX - 10, headY - 10, 4.8, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.beginPath(); ctx.arc(headX + 10, headY - 10, 4.8, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  } else if (sp.id === 'pet_phoenix') {
    ctx.fillStyle = '#FACC15';
    ctx.beginPath(); ctx.moveTo(headX, headY - 22); ctx.lineTo(headX - 5, headY - 10); ctx.lineTo(headX + 5, headY - 10); ctx.closePath(); ctx.fill(); ctx.stroke();
  } else if (sp.id !== 'pet_penguin') {
    ctx.fillStyle = sp.id === 'pet_dragon' ? '#FACC15' : c1;
    ctx.beginPath();
    ctx.moveTo(headX - 11, headY - 5); ctx.lineTo(headX - 15, headY - 18); ctx.lineTo(headX - 3, headY - 10); ctx.closePath();
    ctx.fill(); ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(headX + 11, headY - 5); ctx.lineTo(headX + 15, headY - 18); ctx.lineTo(headX + 3, headY - 10); ctx.closePath();
    ctx.fill(); ctx.stroke();
  }

  if (sp.id === 'pet_unicorn') {
    ctx.fillStyle = '#FACC15';
    ctx.beginPath();
    ctx.moveTo(headX - 3.5, headY - 10); ctx.lineTo(headX, headY - 25); ctx.lineTo(headX + 3.5, headY - 10); ctx.closePath();
    ctx.fill(); ctx.stroke();
  }

  if (sp.id !== 'pet_owl' && sp.id !== 'pet_penguin') {
    ctx.fillStyle = sp.id === 'pet_panda' ? '#FFFFFF' : sp.id === 'pet_unicorn' ? c2 : c1;
    ctx.beginPath();
    ctx.arc(headX, headY, 12.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }

  // Face details
  const gazeShift = dir === 'left' || dir === 'right' ? (isRightBaseSpecies ? 1.8 : -1.8) : 0;
  if (sp.id === 'pet_panda') {
    ctx.fillStyle = '#0F172A';
    ctx.beginPath(); ctx.ellipse(headX + gazeShift - 5, headY - 1, 3.6, 4.4, -0.2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(headX + gazeShift + 5, headY - 1, 3.6, 4.4, 0.2, 0, Math.PI * 2); ctx.fill();
  } else if (sp.id === 'pet_owl' || sp.id === 'pet_penguin') {
    ctx.fillStyle = '#FFFFFF';
    ctx.beginPath(); ctx.arc(headX + gazeShift - 5, headY - 1, 5.2, 0, Math.PI * 2); ctx.arc(headX + gazeShift + 5, headY - 1, 5.2, 0, Math.PI * 2); ctx.fill();
    if (sp.id === 'pet_owl') {
      ctx.strokeStyle = '#2C3E50'; ctx.lineWidth = 1.5; ctx.stroke();
    }
  }

  // Eyes (when facing UP, hide eyes slightly like back-of-head for realistic depth)
  if (dir !== 'up') {
    ctx.fillStyle = sp.id === 'pet_panda' ? '#FFFFFF' : '#1E293B';
    ctx.beginPath();
    ctx.arc(headX + gazeShift - 4.8, headY - 1, 2.3, 0, Math.PI * 2);
    ctx.arc(headX + gazeShift + 4.8, headY - 1, 2.3, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = sp.id === 'pet_panda' ? '#0F172A' : '#FFFFFF';
    ctx.beginPath();
    ctx.arc(headX + gazeShift - 4, headY - 1.8, 0.9, 0, Math.PI * 2);
    ctx.arc(headX + gazeShift + 5.6, headY - 1.8, 0.9, 0, Math.PI * 2);
    ctx.fill();

    // Muzzle / Beak
    const snoutX = headX + gazeShift * 1.2;
    if (sp.id === 'pet_owl' || sp.id === 'pet_penguin' || sp.id === 'pet_phoenix') {
      ctx.fillStyle = '#F59E0B';
      ctx.beginPath();
      ctx.moveTo(snoutX, headY + 5); ctx.lineTo(snoutX - 3.2, headY + 1); ctx.lineTo(snoutX + 3.2, headY + 1); ctx.closePath();
      ctx.fill();
    } else {
      ctx.fillStyle = sp.id === 'pet_dragon' || sp.id === 'pet_unicorn' ? '#FDE68A' : '#FFFFFF';
      ctx.beginPath();
      ctx.ellipse(snoutX, headY + 5, 5.5, 3.5, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#1E293B';
      ctx.beginPath();
      ctx.arc(snoutX, headY + 4, 1.6, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // Accessories & Stage crown
  if (pet.accessoryId === 'pacc_scarf') {
    ctx.strokeStyle = '#EF4444'; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.moveTo(headX - 10, headY + 11); ctx.quadraticCurveTo(headX, headY + 15, headX + 10, headY + 11); ctx.stroke();
  } else if (pet.accessoryId === 'pacc_bell' || pet.stage >= 2) {
    ctx.strokeStyle = pet.accessoryId === 'pacc_bell' ? '#EF4444' : '#FACC15'; ctx.lineWidth = 3.2;
    ctx.beginPath(); ctx.moveTo(headX - 9, headY + 11); ctx.quadraticCurveTo(headX, headY + 15, headX + 9, headY + 11); ctx.stroke();
    if (pet.accessoryId === 'pacc_bell') {
      ctx.fillStyle = '#FACC15'; ctx.beginPath(); ctx.arc(headX, headY + 15, 3, 0, Math.PI * 2); ctx.fill();
    }
  }
  if (pet.accessoryId === 'pacc_glasses' && dir !== 'up') {
    ctx.fillStyle = '#0F172A'; ctx.strokeStyle = '#FACC15'; ctx.lineWidth = 1.4;
    ctx.fillRect(headX + gazeShift - 9, headY - 4, 7, 5); ctx.strokeRect(headX + gazeShift - 9, headY - 4, 7, 5);
    ctx.fillRect(headX + gazeShift + 2, headY - 4, 7, 5); ctx.strokeRect(headX + gazeShift + 2, headY - 4, 7, 5);
  }
  if (pet.accessoryId === 'pacc_bow') {
    ctx.fillStyle = '#EC4899';
    ctx.beginPath(); ctx.arc(headX - 4, headY - 12, 3.5, 0, Math.PI * 2); ctx.arc(headX + 4, headY - 12, 3.5, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#FACC15'; ctx.beginPath(); ctx.arc(headX, headY - 12, 2, 0, Math.PI * 2); ctx.fill();
  }
  if (pet.accessoryId === 'pacc_wizard') {
    ctx.fillStyle = '#4F46E5'; ctx.strokeStyle = '#2C3E50'; ctx.lineWidth = 1.6;
    ctx.beginPath(); ctx.moveTo(headX - 10, headY - 10); ctx.lineTo(headX, headY - 26); ctx.lineTo(headX + 10, headY - 10); ctx.closePath(); ctx.fill(); ctx.stroke();
  }
  if (pet.stage >= 4 || pet.accessoryId === 'pacc_crown') {
    ctx.fillStyle = '#FACC15'; ctx.strokeStyle = '#2C3E50'; ctx.lineWidth = 1.8;
    ctx.beginPath();
    ctx.moveTo(headX - 7, headY - 12); ctx.lineTo(headX - 5, headY - 20); ctx.lineTo(headX, headY - 15); ctx.lineTo(headX + 5, headY - 20); ctx.lineTo(headX + 7, headY - 12);
    ctx.closePath(); ctx.fill(); ctx.stroke();
  }

  ctx.restore();

  ctx.save();
  const isHungry = Math.round(pet.hunger ?? 100) <= 0;
  const genderSymbol = pet.gender === 'female' ? '♀' : pet.gender === 'male' ? '♂' : '';
  const stageShort = `GĐ${pet.stage}`;
  const tagText = `${genderSymbol ? `${genderSymbol} ` : ''}${pet.nickname} ${stageShort} Lv.${pet.level}`;
  ctx.font = 'bold 8.5px Fredoka, sans-serif';
  ctx.textAlign = 'center';
  const tw = Math.max(44, ctx.measureText(tagText).width + 10);
  const tagY = py - 34 * scale - 12;
  ctx.fillStyle = 'rgba(255,255,255,0.94)';
  ctx.strokeStyle = isHungry ? '#DC2626' : c1;
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.roundRect(px - tw / 2, tagY, tw, 13, 6);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = '#1E293B';
  ctx.fillText(tagText, px, tagY + 9);

  if (isHungry) {
    const bob = Math.sin(t / 180) * 2;
    ctx.fillStyle = '#DC2626';
    ctx.strokeStyle = '#FFFFFF';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.roundRect(px - 22, tagY - 16 + bob, 44, 13, 6);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#FFFFFF';
    ctx.font = 'bold 8px Fredoka, sans-serif';
    ctx.fillText('❗ ĐÓI!', px, tagY - 6.5 + bob);
  }
  ctx.restore();
}

/**
 * ============================================================================
 * B2KS 3D LOW-POLY ISOMETRIC SCENE RENDERER (Three.js via CDN)
 * ============================================================================
 * Module này chuyên dựng toàn bộ thế giới 3D phong cách Low-poly Isometric:
 * - Camera trực giao (OrthographicCamera) nghiêng 45 độ + bóng đổ mềm (Soft Shadows)
 * - Bảng màu Pastel tươi sáng, không viền đen (Zero black outlines)
 * - Khu phố 3D (đường nhựa vạch vàng, vỉa hè lát gạch, cỏ xanh mạ, cây, đèn đường, xe cộ, 15+ công trình)
 * - Nội thất Nhà phố 3D nhiều tầng & Phòng riêng 3D
 * - Nhân vật Chibi 3D đầu to thân nhỏ (12 kiểu tóc, trang phục, bóng tròn, xoay hướng mượt)
 * - Thú cưng 3D đồng hành (10 loài + trứng + tiến hóa + phụ kiện)
 */

import { buildCatalogItem3D, buildProceduralLabItem3D } from './itemModels3d';

export { buildCatalogItem3D, buildProceduralLabItem3D };
export const WORLD_SCALE = 0.05; // 100px (2D) = 5 đơn vị 3D

export const PASTEL_PALETTE = {
  grassMain: '#63C13B',
  grassAlt: '#4FA92B',
  grassSnow: '#D2F2DC',
  hillFar: '#72CB4E',
  sidewalk: '#E3BA91',
  sidewalkTile: '#BA8552',
  asphalt: '#334155',
  roadLine: '#FBBF24',
  crosswalk: '#F8FAFC',
  wallCream: '#FFF3DA',
  wallTeal: '#0D9488',
  tealLight: '#14B8A6',
  accentOrange: '#F97316',
  accentYellow: '#FACC15',
  accentCoral: '#F43F5E',
  roofTerracotta: '#DC4C3E',
  woodWarm: '#B47B48',
  woodDark: '#7C4D2B',
  glassDay: '#7DD3FC',
  glassNight: '#FEF08A',
  skyDay: '#BAE6FD',
  skyDawn: '#FDE2C8',
  skySunset: '#FAC39D',
  skyNight: '#17203A',
  skyRain: '#94A3B8',
};

// Reusable math objects (zero GC allocations in animation loop)
let _THREE = null;
const _tmpVec3 = { x: 0, y: 0, z: 0 };

function createSeededRandom(seed) {
  let s = (seed || 1) >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

/**
 * Phát hiện GPU phần mềm (SwiftShader/llvmpipe) để tự động tối ưu shadow & pixelRatio
 */
export function detectSoftwareWebGL() {
  try {
    const probe = document.createElement('canvas');
    const gl = probe.getContext('webgl2') || probe.getContext('webgl');
    if (!gl) return true;
    const ext = gl.getExtension('WEBGL_debug_renderer_info');
    const param = ext ? ext.UNMASKED_RENDERER_WEBGL : gl.RENDERER;
    const gpu = String(gl.getParameter(param) || '');
    gl.getExtension('WEBGL_lose_context')?.loseContext();
    return /SwiftShader|llvmpipe|softpipe|Software|Basic Render/i.test(gpu);
  } catch {
    return false;
  }
}

/**
 * Tạo texture cỏ pastel, vỉa hè lát gạch, mặt đường, sân bóng & bóng tròn mềm
 */
export function createProceduralTextures(THREE, maxAnisotropy = 1) {
  // 1. Grass subtle checkerboard / blades texture
  const grassCanvas = document.createElement('canvas');
  grassCanvas.width = 256;
  grassCanvas.height = 256;
  const gCtx = grassCanvas.getContext('2d');
  gCtx.fillStyle = PASTEL_PALETTE.grassMain;
  gCtx.fillRect(0, 0, 256, 256);
  gCtx.fillStyle = PASTEL_PALETTE.grassAlt;
  gCtx.globalAlpha = 0.34;
  gCtx.fillRect(0, 0, 128, 128);
  gCtx.fillRect(128, 128, 128, 128);
  gCtx.globalAlpha = 0.42;
  for (let i = 0; i < 90; i++) {
    const gx = (i * 73) % 256;
    const gy = (i * 137) % 256;
    gCtx.fillStyle = i % 2 === 0 ? '#7EE054' : '#3E9421';
    gCtx.fillRect(gx, gy, 4, 8);
  }
  const grassTex = new THREE.CanvasTexture(grassCanvas);
  grassTex.wrapS = THREE.RepeatWrapping;
  grassTex.wrapT = THREE.RepeatWrapping;
  grassTex.repeat.set(22, 16);
  grassTex.colorSpace = THREE.SRGBColorSpace;
  grassTex.anisotropy = maxAnisotropy;

  // 2. Sidewalk warm light-brown brick paving texture
  const swCanvas = document.createElement('canvas');
  swCanvas.width = 256;
  swCanvas.height = 256;
  const sCtx = swCanvas.getContext('2d');
  sCtx.fillStyle = PASTEL_PALETTE.sidewalkTile;
  sCtx.fillRect(0, 0, 256, 256);
  const brickShades = ['#E8C29B', '#DFB68C', '#E4BE96', '#D9AE82'];
  const brickH = 64;
  const brickW = 128;
  for (let row = 0; row < 4; row++) {
    const offsetX = row % 2 === 1 ? brickW / 2 : 0;
    for (let col = -1; col < 3; col++) {
      const bx = col * brickW + offsetX;
      const by = row * brickH;
      sCtx.fillStyle = brickShades[(row * 3 + col + 4) % brickShades.length];
      sCtx.fillRect(bx + 3, by + 3, brickW - 6, brickH - 6);
      sCtx.fillStyle = 'rgba(255, 248, 238, 0.28)';
      sCtx.fillRect(bx + 4, by + 4, brickW - 8, 5);
    }
  }
  const sidewalkTex = new THREE.CanvasTexture(swCanvas);
  sidewalkTex.wrapS = THREE.RepeatWrapping;
  sidewalkTex.wrapT = THREE.RepeatWrapping;
  sidewalkTex.repeat.set(24, 2.2);
  sidewalkTex.colorSpace = THREE.SRGBColorSpace;
  sidewalkTex.anisotropy = maxAnisotropy;

  const sidewalkVTex = sidewalkTex.clone();
  sidewalkVTex.needsUpdate = true;
  sidewalkVTex.wrapS = THREE.RepeatWrapping;
  sidewalkVTex.wrapT = THREE.RepeatWrapping;
  sidewalkVTex.repeat.set(2.2, 16);
  sidewalkVTex.colorSpace = THREE.SRGBColorSpace;
  sidewalkVTex.anisotropy = maxAnisotropy;

  // 3. Soft radial contact shadow disc
  const shCanvas = document.createElement('canvas');
  shCanvas.width = 64;
  shCanvas.height = 64;
  const shCtx = shCanvas.getContext('2d');
  const grad = shCtx.createRadialGradient(32, 32, 4, 32, 32, 30);
  grad.addColorStop(0, 'rgba(15, 23, 42, 0.45)');
  grad.addColorStop(0.6, 'rgba(15, 23, 42, 0.2)');
  grad.addColorStop(1, 'rgba(15, 23, 42, 0)');
  shCtx.fillStyle = grad;
  shCtx.fillRect(0, 0, 64, 64);
  const shadowTex = new THREE.CanvasTexture(shCanvas);
  shadowTex.colorSpace = THREE.SRGBColorSpace;

  // 4. Warm honey-oak wood plank floor texture (shared between house rooms & private room)
  const woodCanvas = document.createElement('canvas');
  woodCanvas.width = 128;
  woodCanvas.height = 128;
  const wCtx = woodCanvas.getContext('2d');
  wCtx.fillStyle = '#E5AA6C';
  wCtx.fillRect(0, 0, 128, 128);
  wCtx.fillStyle = '#DB9B59';
  wCtx.fillRect(0, 32, 128, 32);
  wCtx.fillRect(0, 96, 128, 32);
  wCtx.fillStyle = '#C47D3B';
  for (let y = 0; y < 128; y += 32) {
    wCtx.fillRect(0, y, 128, 2);
    wCtx.fillRect((y * 2 + 24) % 128, y, 2, 32);
  }
  const woodTex = new THREE.CanvasTexture(woodCanvas);
  woodTex.wrapS = THREE.RepeatWrapping;
  woodTex.wrapT = THREE.RepeatWrapping;
  woodTex.repeat.set(8, 5);
  woodTex.colorSpace = THREE.SRGBColorSpace;
  woodTex.anisotropy = maxAnisotropy;

  return { grassTex, sidewalkTex, sidewalkVTex, shadowTex, woodTex };
}

/**
 * Helper tạo vật liệu PBR chuẩn Low-Poly (không viền đen, chia roughness rõ khối)
 */
export function createMaterialCache(THREE) {
  const cache = new Map();
  return {
    get(color, opts = {}) {
      const key = `${color}|${opts.roughness ?? 0.72}|${opts.metalness ?? 0.04}|${opts.emissive ?? 0}|${opts.opacity ?? 1}|${opts.flatShading ? 1 : 0}`;
      if (cache.has(key)) return cache.get(key);
      const mat = new THREE.MeshStandardMaterial({
        color: new THREE.Color(color),
        roughness: opts.roughness ?? 0.72,
        metalness: opts.metalness ?? 0.04,
        flatShading: opts.flatShading ?? false,
        transparent: opts.transparent ?? (opts.opacity !== undefined && opts.opacity < 1),
        opacity: opts.opacity ?? 1,
        emissive: opts.emissive ? new THREE.Color(opts.emissive) : new THREE.Color(0x000000),
        emissiveIntensity: opts.emissiveIntensity ?? (opts.emissive ? 0.65 : 0),
        side: opts.side ?? THREE.FrontSide,
      });
      cache.set(key, mat);
      return mat;
    },
    disposeAll() {
      cache.forEach((m) => m.dispose());
      cache.clear();
    },
  };
}

function makeBox(THREE, w, h, d, mat, castShadow = true, receiveShadow = true) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.castShadow = castShadow;
  m.receiveShadow = receiveShadow;
  return m;
}

function makeCyl(THREE, rt, rb, h, segs, mat, castShadow = true, receiveShadow = true) {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, segs), mat);
  m.castShadow = castShadow;
  m.receiveShadow = receiveShadow;
  return m;
}

function makeSphere(THREE, r, ws, hs, mat, castShadow = true, receiveShadow = true) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, ws, hs), mat);
  m.castShadow = castShadow;
  m.receiveShadow = receiveShadow;
  return m;
}

/**
 * Dựng 5 loại cây Low-poly 3D chi tiết (nhiều tán, cành nhánh, bồn cây/quả)
 */
function buildTree3D(THREE, mats, kind, x, z, withPlanter = false) {
  const group = new THREE.Group();
  group.position.set(x, 0, z);
  const rand = createSeededRandom(Math.round(x * 13 + z * 7));
  const scaleVar = 0.9 + rand() * 0.22;
  group.scale.setScalar(scaleVar);

  if (withPlanter) {
    const curb = makeCyl(THREE, 0.95, 1.05, 0.28, 8, mats.get('#CBD5E1', { roughness: 0.78 }), false, true);
    curb.position.y = 0.14;
    const soil = makeCyl(THREE, 0.78, 0.78, 0.3, 8, mats.get('#78350F', { roughness: 0.92 }), false, true);
    soil.position.y = 0.15;
    group.add(curb, soil);
  }

  const canopyGroup = new THREE.Group();
  group.add(canopyGroup);
  group.userData.canopy = canopyGroup;
  group.userData.swayPhase = x * 0.2 + z * 0.15;

  if (kind === 'pine') {
    const trunk = makeCyl(THREE, 0.2, 0.34, 1.4, 8, mats.get('#6D3E21', { roughness: 0.88 }));
    trunk.position.y = 0.7;
    group.add(trunk);

    const tiers = [
      { r: 1.52, h: 1.7, y: 1.85, col: '#15803D' },
      { r: 1.2, h: 1.55, y: 2.75, col: '#16A34A' },
      { r: 0.88, h: 1.4, y: 3.6, col: '#22C55E' },
      { r: 0.52, h: 1.05, y: 4.3, col: '#4ADE80' },
    ];
    tiers.forEach((t, idx) => {
      const cone = new THREE.Mesh(
        new THREE.ConeGeometry(t.r, t.h, 7),
        mats.get(t.col, { roughness: 0.76, flatShading: true })
      );
      cone.position.y = t.y;
      cone.rotation.y = idx * 0.45;
      cone.castShadow = true;
      cone.receiveShadow = true;
      canopyGroup.add(cone);
    });
  } else if (kind === 'sakura') {
    const barkMat = mats.get('#5C3A2E', { roughness: 0.88 });
    const trunk = makeCyl(THREE, 0.22, 0.36, 1.65, 8, barkMat);
    trunk.position.y = 0.82;
    const brL = makeCyl(THREE, 0.1, 0.15, 0.95, 6, barkMat);
    brL.position.set(-0.32, 1.55, 0.1);
    brL.rotation.z = 0.58;
    const brR = makeCyl(THREE, 0.1, 0.14, 0.9, 6, barkMat);
    brR.position.set(0.32, 1.6, -0.08);
    brR.rotation.z = -0.52;
    group.add(trunk, brL, brR);

    const puffs = [
      [0, 2.42, 0, 1.24, '#F472B6'],
      [-0.82, 2.08, 0.36, 0.85, '#F9A8D4'],
      [0.8, 2.15, -0.28, 0.88, '#EC4899'],
      [0.18, 2.95, 0.24, 0.8, '#FBCFE8'],
      [-0.25, 2.65, -0.58, 0.72, '#F472B6'],
    ];
    puffs.forEach(([px, py, pz, pr, col]) => {
      const sph = makeSphere(THREE, pr, 10, 8, mats.get(col, { roughness: 0.74, flatShading: true }));
      sph.position.set(px, py, pz);
      canopyGroup.add(sph);
    });
  } else if (kind === 'palm') {
    const trunkMat = mats.get('#A16207', { roughness: 0.86 });
    const ringMat = mats.get('#78350F', { roughness: 0.88 });
    for (let i = 0; i < 5; i++) {
      const seg = makeCyl(THREE, 0.19 - i * 0.018, 0.24 - i * 0.018, 0.68, 8, i % 2 === 0 ? trunkMat : ringMat);
      seg.position.set(i * 0.09, 0.34 + i * 0.62, 0);
      seg.rotation.z = -0.09;
      group.add(seg);
    }
    const crownX = 0.42;
    const crownY = 3.32;
    const cocoMat = mats.get('#78350F', { roughness: 0.6 });
    [[-0.18, 0.16], [0.2, -0.12], [0.02, 0.22]].forEach(([cx, cz]) => {
      const coco = makeSphere(THREE, 0.17, 8, 6, cocoMat);
      coco.position.set(crownX + cx, crownY - 0.18, cz);
      canopyGroup.add(coco);
    });
    const frondMat = mats.get('#22C55E', { roughness: 0.68, flatShading: true });
    const tipMat = mats.get('#4ADE80', { roughness: 0.68, flatShading: true });
    for (let a = 0; a < 7; a++) {
      const ang = (a * Math.PI * 2) / 7;
      const frondGroup = new THREE.Group();
      frondGroup.position.set(crownX, crownY, 0);
      frondGroup.rotation.y = ang;
      const inner = makeBox(THREE, 1.0, 0.1, 0.42, frondMat);
      inner.position.set(0.5, 0.06, 0);
      inner.rotation.z = -0.14;
      const outer = makeBox(THREE, 0.78, 0.08, 0.3, tipMat);
      outer.position.set(1.22, -0.12, 0);
      outer.rotation.z = -0.45;
      frondGroup.add(inner, outer);
      canopyGroup.add(frondGroup);
    }
  } else if (kind === 'orange') {
    const barkMat = mats.get('#78350F', { roughness: 0.86 });
    const trunk = makeCyl(THREE, 0.21, 0.34, 1.55, 8, barkMat);
    trunk.position.y = 0.77;
    const root = makeCyl(THREE, 0.28, 0.46, 0.35, 7, barkMat);
    root.position.y = 0.17;
    group.add(trunk, root);

    const leaves = makeSphere(THREE, 1.24, 10, 8, mats.get('#16A34A', { roughness: 0.76, flatShading: true }));
    leaves.position.y = 2.28;
    const sub1 = makeSphere(THREE, 0.86, 9, 7, mats.get('#22C55E', { roughness: 0.74, flatShading: true }));
    sub1.position.set(0.56, 2.48, 0.38);
    const sub2 = makeSphere(THREE, 0.72, 9, 7, mats.get('#4ADE80', { roughness: 0.72, flatShading: true }));
    sub2.position.set(-0.55, 2.35, -0.35);
    canopyGroup.add(leaves, sub1, sub2);

    const orangeMat = mats.get('#F97316', { roughness: 0.42 });
    [
      [-0.82, 2.15, 0.78],
      [0.78, 2.3, 0.86],
      [0.12, 2.75, 0.96],
      [-0.45, 1.98, -0.92],
      [0.52, 2.82, -0.35],
    ].forEach(([ox, oy, oz]) => {
      const fruit = makeSphere(THREE, 0.17, 7, 6, orangeMat);
      fruit.position.set(ox, oy, oz);
      canopyGroup.add(fruit);
    });
  } else {
    const barkMat = mats.get('#7C4D2B', { roughness: 0.86 });
    const trunk = makeCyl(THREE, 0.22, 0.36, 1.65, 8, barkMat);
    trunk.position.y = 0.82;
    const br = makeCyl(THREE, 0.1, 0.15, 0.85, 6, barkMat);
    br.position.set(-0.3, 1.48, 0.2);
    br.rotation.z = 0.52;
    group.add(trunk, br);

    const puffs = [
      [0, 2.32, 0, 1.28, '#16A34A'],
      [-0.64, 2.52, 0.44, 0.86, '#22C55E'],
      [0.68, 2.22, -0.32, 0.82, '#15803D'],
      [0.12, 2.9, 0.12, 0.76, '#4ADE80'],
    ];
    puffs.forEach(([px, py, pz, pr, col]) => {
      const sp = makeSphere(THREE, pr, 10, 8, mats.get(col, { roughness: 0.75, flatShading: true }));
      sp.position.set(px, py, pz);
      canopyGroup.add(sp);
    });
  }

  return group;
}

/**
 * Dựng cụm hoa 3D pastel có viền gỗ/đá nhẹ
 */
function buildFlowerCluster3D(THREE, mats, x, z, color, kind) {
  const g = new THREE.Group();
  g.position.set(x, 0, z);
  const bed = makeCyl(THREE, 0.68, 0.75, 0.12, 8, mats.get('#A16207', { roughness: 0.85 }), false, true);
  bed.position.y = 0.06;
  const soil = makeCyl(THREE, 0.56, 0.56, 0.14, 8, mats.get('#57534E', { roughness: 0.92 }), false, true);
  soil.position.y = 0.07;
  g.add(bed, soil);

  const leafMat = mats.get('#22C55E', { roughness: 0.8 });
  const stemMat = mats.get('#16A34A', { roughness: 0.8 });
  const petalCol = kind === 'sunflower' ? '#FACC15' : kind === 'lavender' ? '#A855F7' : color;
  const petalMat = mats.get(petalCol, { roughness: 0.52 });
  const centerMat = mats.get(kind === 'sunflower' ? '#78350F' : '#FEF08A', { roughness: 0.45 });

  [[-0.26, 0.14, 0.92], [0.24, -0.16, 1.08], [0.02, 0.25, 0.84], [-0.14, -0.22, 0.9]].forEach(([ox, oz, s]) => {
    const leaf = makeCyl(THREE, 0.18 * s, 0.22 * s, 0.06, 6, leafMat, false, true);
    leaf.position.set(ox, 0.14, oz);
    g.add(leaf);

    const stem = makeCyl(THREE, 0.035, 0.04, 0.34 * s, 5, stemMat, false, false);
    stem.position.set(ox, 0.14 + 0.17 * s, oz);
    g.add(stem);

    const head = makeSphere(THREE, 0.15 * s, 7, 6, petalMat, true, false);
    head.scale.y = 0.65;
    head.position.set(ox, 0.14 + 0.36 * s, oz);
    g.add(head);

    const core = makeSphere(THREE, 0.065 * s, 6, 5, centerMat, false, false);
    core.position.set(ox, 0.14 + 0.42 * s, oz);
    g.add(core);
  });
  return g;
}

/**
 * Dựng đèn đường 3D cổ điển hiện đại (tay đèn đôi trang trí & chóa phản quang)
 */
function buildStreetLamp3D(THREE, mats, x, z, isNight) {
  const g = new THREE.Group();
  g.position.set(x, 0, z);

  const poleMat = mats.get('#1E293B', { roughness: 0.4, metalness: 0.45 });
  const goldMat = mats.get('#F59E0B', { roughness: 0.35, metalness: 0.5 });

  const base = makeCyl(THREE, 0.22, 0.34, 0.36, 8, poleMat);
  base.position.y = 0.18;
  const collar = makeCyl(THREE, 0.16, 0.22, 0.14, 8, goldMat);
  collar.position.y = 0.42;
  const post = makeCyl(THREE, 0.08, 0.12, 2.65, 8, poleMat);
  post.position.y = 1.75;
  const arm = makeBox(THREE, 0.62, 0.09, 0.09, poleMat);
  arm.position.set(0.28, 2.98, 0);
  const brace = makeBox(THREE, 0.42, 0.06, 0.06, goldMat);
  brace.position.set(0.18, 2.8, 0);
  brace.rotation.z = 0.65;
  const cap = new THREE.Mesh(new THREE.ConeGeometry(0.28, 0.2, 8), poleMat);
  cap.position.set(0.54, 3.02, 0);
  g.add(base, collar, post, arm, brace, cap);

  const bulb = makeSphere(
    THREE,
    0.19,
    10,
    8,
    mats.get(isNight ? '#FEF08A' : '#F8FAFC', {
      roughness: 0.22,
      emissive: isNight ? '#FDE047' : null,
      emissiveIntensity: isNight ? 1.5 : 0,
    }),
    false,
    false
  );
  bulb.position.set(0.54, 2.82, 0);
  g.add(bulb);

  if (isNight) {
    const glow = new THREE.Mesh(
      new THREE.CircleGeometry(1.8, 16),
      new THREE.MeshBasicMaterial({ color: 0xfef08a, transparent: true, opacity: 0.2, depthWrite: false })
    );
    glow.rotation.x = -Math.PI / 2;
    glow.position.set(0.54, 0.17, 0);
    g.add(glow);
  }
  return g;
}

/**
 * Dựng ghế băng công viên vỉa hè
 */
function buildParkBench3D(THREE, mats, x, z, rotY = 0) {
  const g = new THREE.Group();
  g.position.set(x, 0.14, z);
  g.rotation.y = rotY;
  const woodMat = mats.get('#D97706', { roughness: 0.72 });
  const ironMat = mats.get('#334155', { roughness: 0.45, metalness: 0.45 });

  [-0.85, 0.85].forEach((lx) => {
    const leg = makeBox(THREE, 0.14, 0.44, 0.62, ironMat);
    leg.position.set(lx, 0.22, 0);
