  };

  return root;
}

/**
 * Dựng NPC Người Nước Ngoài 3D (Mr. Alex & Ms. Emma) đi dạo học Speaking
 */
function buildForeignNpc3D(THREE, mats, shadowTex, npc) {
  const isFemale = npc.gender === 'female';
  const proxyMember = {
    id: npc.id,
