    // Rounded cushioned mecha thruster boots + sculpted greaves
    [-0.17, 0.17].forEach((lx) => {
      const boot = makeRoundedExtrude(THREE, 0.22, 0.15, 0.06, 0.28, 0.025, mechaRed);
