    return grp;
  }

  // Camera state (Isometric 45° + smooth damping)
  const camState = {
    targetX: 43,
    targetZ: 21,
    panX: 0,
    panZ: 0,
    yaw: Math.PI / 4, // 45° azimuth
    targetYaw: Math.PI / 4,
    pitch: Math.PI / 4, // 45° elevation tilt
    targetPitch: Math.PI / 4,
    zoom: 1.0,
    targetZoom: 1.0,
  };

  const raycaster = new THREE.Raycaster();
  const groundPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
  const ndcVec = new THREE.Vector2();
  const hitVec = new THREE.Vector3();
  const projVec = new THREE.Vector3();

  function raycastGround(clientX, clientY) {
    const rect = canvasEl.getBoundingClientRect();
    ndcVec.x = ((clientX - rect.left) / rect.width) * 2 - 1;
    ndcVec.y = -((clientY - rect.top) / rect.height) * 2 + 1;
    raycaster.setFromCamera(ndcVec, camera);
    const hit = raycaster.ray.intersectPlane(groundPlane, hitVec);
    if (!hit) return null;
    return { x2d: hit.x / WORLD_SCALE, y2d: hit.z / WORLD_SCALE };
  }

  function resize() {
    const w = window.innerWidth;
    const h = Math.max(1, window.innerHeight);
    const asp = w / h;
    camera.left = -baseHalfH * asp;
    camera.right = baseHalfH * asp;
    camera.top = baseHalfH;
    camera.bottom = -baseHalfH;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h, false);
    renderer.setPixelRatio(isSoftwareGl ? 1 : Math.min(window.devicePixelRatio || 1, 2));
  }

  function updateAtmosphere(lighting, weather, sceneName) {
    const wCond = weather?.condition || 'clear';
    let skyCol = PASTEL_PALETTE.skyDay;
    let sunCol = '#FFF3D6';
    let sunInt = 1.34;
    let hemiInt = 0.58;

    if (sceneName !== 'neighborhood') {
      skyCol = '#172338';
      sunInt = lighting.isNight ? 0.92 : 1.28;
      hemiInt = 0.56;
    } else if (lighting.phase === 'night') {
      skyCol = PASTEL_PALETTE.skyNight;
      sunCol = '#93C5FD';
      sunInt = 0.58;
      hemiInt = 0.42;
    } else if (lighting.phase === 'dawn') {
      skyCol = PASTEL_PALETTE.skyDawn;
      sunCol = '#FDBA74';
      sunInt = 1.12;
      hemiInt = 0.52;
    } else if (lighting.phase === 'sunset') {
      skyCol = PASTEL_PALETTE.skySunset;
      sunCol = '#FB923C';
      sunInt = 1.08;
      hemiInt = 0.5;
    } else if (wCond === 'rain' || wCond === 'thunder') {
      skyCol = PASTEL_PALETTE.skyRain;
      sunInt = 0.85;
      hemiInt = 0.54;
    }

    scene.background.set(skyCol);
    scene.fog.color.set(skyCol);
    scene.fog.near = wCond === 'fog' ? 35 : 95;
    scene.fog.far = wCond === 'fog' ? 110 : 225;
    sunLight.color.set(sunCol);
    sunLight.intensity = sunInt;
    hemiLight.intensity = hemiInt;

    if (sceneName === 'neighborhood') {
      if (wCond === 'rain' || wCond === 'thunder' || wCond === 'snow') rebuildWeatherParticles(wCond);
      else if (lighting.phase === 'night') rebuildWeatherParticles('fireflies');
      else rebuildWeatherParticles('clear');
    } else {
      rebuildWeatherParticles('clear');
    }
  }

  function renderFrame(params) {
    const {
      deltaSec,
      nowMs,
      state,
      me,
      lighting,
      weather,
      locations,
      streetCars,
      arcadeRoom,
      arcadeCatalog,
      soccerRoom,
      houseRooms,
      wardrobeOpenedRoomId,
      roomDecorSlots,
      findAnyCatalogItem,
      memberMovingMap,
      foreignNpcs,
      helperRobots,
      kidsLeaderboard,
      tapTarget,
      getPetForMember,
      getPetSpecies,
      getPetResolvedColors,
      labelLayerEl,
    } = params;

    updateAtmosphere(lighting, weather, me.scene);
    updateLeaderBoardTexture(kidsLeaderboard, (state.familyName || 'B2KS').trim() || 'B2KS');
    ledAdTex.offset.x = (nowMs * 0.00018) % 1;

    // 1. Rebuild static world only when scene / building layouts / night state / rooms change
    const locSig = locations.map((l) => `${l.id}:${l.x}:${l.y}:${l.shape}`).join('|');
    const roomSig =
      me.scene === 'house'
        ? houseRooms.map((r) => `${r.id}:${r.isUnlocked}:${r.isDisabled}:${r.wall}`).join('|') +
          `|${wardrobeOpenedRoomId}|` +
          state.members
            .map((m) => `${m.roomWall || ''}:${JSON.stringify(m.roomSlots || {})}:${(m.roomDecor || []).map((d) => `${d.id}@${d.x},${d.y}`).join(',')}`)
            .join(';')
        : me.scene === 'private_room'
          ? `${me.privateRoomId}|${wardrobeOpenedRoomId}|` +
            JSON.stringify(state.members.find((m) => m.id === (houseRooms.find((r) => r.id === me.privateRoomId)?.ownerIds?.[0]))?.roomSlots || {}) +
            '|' +
            (state.members.find((m) => m.id === (houseRooms.find((r) => r.id === me.privateRoomId)?.ownerIds?.[0]))?.roomWall || '')
          : `${locSig}|${state.house?.plotIndex}|${state.house?.style}|${state.familyName}|${weather?.condition}|${arcadeRoom?.status}|${soccerRoom?.status}`;
    const worldSig = `${me.scene}|${lighting.isNight ? 'N' : 'D'}|${roomSig}`;

    if (worldSig !== lastWorldSignature) {
      lastWorldSignature = worldSig;
      clearGroupChildren(worldGroup);
      if (me.scene === 'neighborhood') {
        worldGroup.add(buildNeighborhoodGroup(state, lighting, weather, locations, arcadeRoom, arcadeCatalog, soccerRoom));
      } else if (me.scene === 'house') {
        animatedProps.length = 0;
        labelTargets.length = 0;
        worldGroup.add(
          buildHouseInterior3D(THREE, mats, textures, houseRooms, state, wardrobeOpenedRoomId, lighting.isNight, findAnyCatalogItem, roomDecorSlots)
        );
        houseRooms.forEach((r) => {
          const isBedroomOrClosed = r.isDisabled || r.id === 'f2_parents' || (!r.id.startsWith('f1_') && !r.id.startsWith('f2_'));
          labelTargets.push({
            x: (r.x + r.w / 2) * WORLD_SCALE,
            y: isBedroomOrClosed ? 3.85 : 3.6,
            z: (isBedroomOrClosed ? r.y + r.h * 0.48 : r.y + 24) * WORLD_SCALE,
            text: r.name + (r.isDisabled ? ' 🚫' : r.ownerIds?.length ? (r.isUnlocked ? ' 🔓' : ' 🔒') : ''),
            kind: 'building',
          });
        });
      } else {
        animatedProps.length = 0;
        labelTargets.length = 0;
        const room = houseRooms.find((r) => r.id === (me.privateRoomId || '')) || null;
        const ownerMember = (room && room.ownerIds && state.members.find((m) => m.id === room.ownerIds[0])) || null;
        worldGroup.add(
          buildPrivateRoom3D(THREE, mats, textures, room, houseRooms, ownerMember, wardrobeOpenedRoomId, lighting.isNight, roomDecorSlots, findAnyCatalogItem)
        );
        const exitX = room?.doorSide === 'right' ? 742 : 18;
        labelTargets.push({ x: 68 * WORLD_SCALE, y: 2.2, z: 68 * WORLD_SCALE, text: '🛏️ Giường ngủ', kind: 'building' });
        labelTargets.push({ x: 706 * WORLD_SCALE, y: 4.5, z: 46 * WORLD_SCALE, text: '🧥 Tủ quần áo', kind: 'building' });
        labelTargets.push({ x: exitX * WORLD_SCALE, y: 2.2, z: 310 * WORLD_SCALE, text: '🚪 Ra hành lang', kind: 'building' });
      }
    }

    // 2. Animate world props (trees, portal, fountain spray, soccer ball, barber pole)
    animatedProps.forEach((obj) => {
      if (obj.userData.canopy) {
        obj.userData.canopy.rotation.z = Math.sin(nowMs * 0.0016 + (obj.userData.swayPhase || 0)) * 0.04;
      }
      if (obj.userData.portalRing) {
        obj.userData.portalRing.rotation.z = nowMs * 0.0018;
      }
      if (obj.userData.floatingEgg) {
        obj.userData.floatingEgg.position.y = 5.85 + Math.sin(nowMs * 0.003) * 0.18;
        obj.userData.floatingEgg.rotation.y = nowMs * 0.0012;
      }
      if (obj.userData.floatingCrystal) {
        obj.userData.floatingCrystal.position.y = 6.45 + Math.sin(nowMs * 0.0028) * 0.22;
        obj.userData.floatingCrystal.rotation.y = nowMs * 0.0018;
      }
      if (obj.userData.beacon) {
        obj.userData.beacon.scale.setScalar(1 + Math.sin(nowMs * 0.006) * 0.18);
      }
      if (obj.userData.barberPole) {
        obj.userData.barberPole.rotation.y = nowMs * 0.005;
      }
      if (obj.userData.waterSpray) {
        obj.userData.waterSpray.position.y = 2.4 + Math.sin(nowMs * 0.007) * 0.25;
      }
      if (obj.userData.soccerBall) {
        obj.userData.soccerBall.position.x = Math.sin(nowMs * 0.0025) * 1.6;
        obj.userData.soccerBall.position.y = 0.45 + Math.abs(Math.sin(nowMs * 0.005)) * 0.25;
      }
    });

    // 3. Update & render 3D Vehicles in neighborhood
    vehiclesGroup.visible = me.scene === 'neighborhood';
    if (me.scene === 'neighborhood') {
      streetCars.forEach((car, idx) => {
        if (car.axis === 'h') {
          car.x += car.speed;
          if (car.x > 2520 + 110) car.x = -110;
          if (car.x < -110) car.x = 2520 + 110;
        } else {
          car.y += car.speed;
          if (car.y > 1700 + 110) car.y = 220;
          if (car.y < 220) car.y = 1700 + 110;
        }
        const key = `car_${idx}`;
        let mesh = vehicleMeshes.get(key);
        if (!mesh) {
          mesh = buildVehicle3D(THREE, mats, car);
          vehicleMeshes.set(key, mesh);
          vehiclesGroup.add(mesh);
        }
        mesh.position.set(car.x * WORLD_SCALE, 0.17, car.y * WORLD_SCALE);
        mesh.rotation.y = car.axis === 'h' ? (car.dir > 0 ? 0 : Math.PI) : car.dir > 0 ? -Math.PI / 2 : Math.PI / 2;
      });
    }

    // 4. Sync 3D Chibi Characters & Companion Pets
    const visibleMembers = state.members.filter((m) => {
      if (m.scene !== me.scene) return false;
      if (me.scene === 'private_room') {
        return (m.privateRoomId || null) === (me.privateRoomId || null);
      }
      return true;
    });
    const visibleIds = new Set(visibleMembers.map((m) => m.id));

    memberMeshes.forEach((entry, id) => {
      if (!visibleIds.has(id)) {
        actorsGroup.remove(entry.mesh);
        memberMeshes.delete(id);
      }
    });
    petMeshes.forEach((entry, id) => {
      if (!visibleIds.has(id)) {
        actorsGroup.remove(entry.mesh);
        petMeshes.delete(id);
      }
    });

    const dynamicLabels = [];

    visibleMembers.forEach((m) => {
      const appearanceSig = `${m.role}|${m.hairStyle}|${m.hairColor}|${m.shirtColor}|${m.shirtPattern}|${m.pantsColor}|${m.pantsStyle}|${m.outfit}|${m.id === me.id}`;
      let entry = memberMeshes.get(m.id);
      if (!entry || entry.sig !== appearanceSig) {
        if (entry) actorsGroup.remove(entry.mesh);
        const charMesh = buildChibiCharacter3D(THREE, mats, textures.shadowTex, m, m.id === me.id);
        charMesh.position.set(m.x * WORLD_SCALE, 0.1, m.y * WORLD_SCALE);
        actorsGroup.add(charMesh);
        entry = { mesh: charMesh, sig: appearanceSig, prevX: m.x, prevY: m.y };
        memberMeshes.set(m.id, entry);
      }

      const targetX = m.x * WORLD_SCALE;
      const targetZ = m.y * WORLD_SCALE;
      const moveDX = m.x - entry.prevX;
      const moveDY = m.y - entry.prevY;
      entry.prevX = m.x;
      entry.prevY = m.y;

      // Smoothly position & rotate Chibi to face movement direction!
      entry.mesh.position.x = THREE.MathUtils.damp(entry.mesh.position.x, targetX, 20, deltaSec);
      entry.mesh.position.z = THREE.MathUtils.damp(entry.mesh.position.z, targetZ, 20, deltaSec);
      entry.mesh.position.y = me.scene === 'neighborhood' ? 0.08 : 0.1;

      const ud = entry.mesh.userData;
      const isMoving = Boolean(memberMovingMap.get(m.id));
      if (Math.hypot(moveDX, moveDY) > 0.05) {
        ud.targetYaw = Math.atan2(moveDX, moveDY);
      } else {
        if (m.dir === 'left') ud.targetYaw = -Math.PI / 2;
        else if (m.dir === 'right') ud.targetYaw = Math.PI / 2;
        else if (m.dir === 'up') ud.targetYaw = Math.PI;
        else ud.targetYaw = 0;
      }

      // Shortest-angle yaw damping
      let diff = ud.targetYaw - ud.currentYaw;
      while (diff > Math.PI) diff -= Math.PI * 2;
      while (diff < -Math.PI) diff += Math.PI * 2;
      ud.currentYaw += diff * Math.min(1, deltaSec * 14);
      ud.bodyRoot.rotation.y = ud.currentYaw;

      // Walk cycle or gentle idle breathing
      if (isMoving) {
        const phase = nowMs * 0.015;
        const swing = Math.sin(phase) * 0.65;
        ud.leftLegPivot.rotation.x = swing;
        ud.rightLegPivot.rotation.x = -swing;
        ud.leftArmPivot.rotation.x = -swing * 0.85;
        ud.rightArmPivot.rotation.x = swing * 0.85;
        ud.upperGroup.position.y = 0.48 + Math.abs(Math.sin(phase)) * 0.09;
      } else {
        ud.leftLegPivot.rotation.x = THREE.MathUtils.damp(ud.leftLegPivot.rotation.x, 0, 12, deltaSec);
        ud.rightLegPivot.rotation.x = THREE.MathUtils.damp(ud.rightLegPivot.rotation.x, 0, 12, deltaSec);
        ud.leftArmPivot.rotation.x = THREE.MathUtils.damp(ud.leftArmPivot.rotation.x, 0, 12, deltaSec);
        ud.rightArmPivot.rotation.x = THREE.MathUtils.damp(ud.rightArmPivot.rotation.x, 0, 12, deltaSec);
        ud.upperGroup.position.y = 0.48 + Math.sin(nowMs * 0.003 + m.x) * 0.025;
      }

      dynamicLabels.push({
        x: entry.mesh.position.x,
        y: entry.mesh.position.y + 2.45,
        z: entry.mesh.position.z,
        text: m.name,
        kind: m.id === me.id ? 'name-me' : 'name',
      });
      if (m.speech && nowMs < m.speech.expiresAt) {
        dynamicLabels.push({
          x: entry.mesh.position.x,
          y: entry.mesh.position.y + 3.05,
          z: entry.mesh.position.z,
          text: m.speech.isEng ? `${m.speech.text} (+5⭐)` : m.speech.text,
          kind: m.speech.isEng ? 'speech-eng' : 'speech',
        });
      }

      // Companion Pet 3D
      const pet = getPetForMember(m);
      if (pet) {
        const sp = getPetSpecies(pet.speciesId);
        const col = getPetResolvedColors(sp, pet.variant);
        const petSig = `${pet.id}|${pet.speciesId}|${pet.stage}|${pet.hatched}|${pet.variant}|${pet.accessoryId}`;
        let pEntry = petMeshes.get(m.id);
        if (!pEntry || pEntry.sig !== petSig) {
          if (pEntry) actorsGroup.remove(pEntry.mesh);
          const pm = buildPet3D(THREE, mats, textures.shadowTex, pet, sp, col);
          pm.position.set(entry.mesh.position.x - 1.2, 0.08, entry.mesh.position.z + 0.6);
          actorsGroup.add(pm);
          pEntry = { mesh: pm, sig: petSig };
          petMeshes.set(m.id, pEntry);
        }
        const followAngle = ud.currentYaw + Math.PI * 0.72;
        const pTargetX = entry.mesh.position.x + Math.sin(followAngle) * 1.45;
        const pTargetZ = entry.mesh.position.z + Math.cos(followAngle) * 1.45;
        const pdx = pTargetX - pEntry.mesh.position.x;
        const pdz = pTargetZ - pEntry.mesh.position.z;
        pEntry.mesh.position.x = THREE.MathUtils.damp(pEntry.mesh.position.x, pTargetX, 7, deltaSec);
        pEntry.mesh.position.z = THREE.MathUtils.damp(pEntry.mesh.position.z, pTargetZ, 7, deltaSec);
        if (Math.hypot(pdx, pdz) > 0.03) {
          pEntry.mesh.userData.actor.rotation.y = Math.atan2(pdx, pdz);
        }
        const bounce = isMoving ? Math.abs(Math.sin(nowMs * 0.012)) * 0.25 : Math.sin(nowMs * 0.004) * 0.08;
        pEntry.mesh.userData.actor.position.y = bounce;
        if (pEntry.mesh.userData.auraRing) {
          pEntry.mesh.userData.auraRing.rotation.z = nowMs * 0.0022;
          pEntry.mesh.userData.auraRing.scale.setScalar(1 + Math.sin(nowMs * 0.005) * 0.08);
        }
      } else if (petMeshes.has(m.id)) {
        actorsGroup.remove(petMeshes.get(m.id).mesh);
        petMeshes.delete(m.id);
      }
    });

    // 4b. Sync Roaming Foreign NPCs (Mr. Alex & Ms. Emma) in neighborhood
    const visibleNpcs = me.scene === 'neighborhood' && Array.isArray(foreignNpcs) ? foreignNpcs : [];
    const visibleNpcIds = new Set(visibleNpcs.map((n) => n.id));
    foreignNpcMeshes.forEach((entry, id) => {
      if (!visibleNpcIds.has(id)) {
        actorsGroup.remove(entry.mesh);
        foreignNpcMeshes.delete(id);
      }
    });
    visibleNpcs.forEach((npc) => {
      let nEntry = foreignNpcMeshes.get(npc.id);
      if (!nEntry) {
        const nm = buildForeignNpc3D(THREE, mats, textures.shadowTex, npc);
        nm.position.set(npc.x * WORLD_SCALE, 0.08, npc.y * WORLD_SCALE);
        actorsGroup.add(nm);
        nEntry = { mesh: nm };
        foreignNpcMeshes.set(npc.id, nEntry);
      }
      nEntry.mesh.position.x = THREE.MathUtils.damp(nEntry.mesh.position.x, npc.x * WORLD_SCALE, 16, deltaSec);
      nEntry.mesh.position.z = THREE.MathUtils.damp(nEntry.mesh.position.z, npc.y * WORLD_SCALE, 16, deltaSec);
      nEntry.mesh.position.y = 0.08;
      const ud = nEntry.mesh.userData;
      ud.targetYaw = typeof npc.facingYaw === 'number' ? npc.facingYaw : 0;
      let ndiff = ud.targetYaw - ud.currentYaw;
      while (ndiff > Math.PI) ndiff -= Math.PI * 2;
      while (ndiff < -Math.PI) ndiff += Math.PI * 2;
      ud.currentYaw += ndiff * Math.min(1, deltaSec * 12);
      ud.bodyRoot.rotation.y = ud.currentYaw;
      if (npc.isMoving) {
        const phase = nowMs * 0.012;
        const swing = Math.sin(phase) * 0.55;
        ud.leftLegPivot.rotation.x = swing;
        ud.rightLegPivot.rotation.x = -swing;
        ud.leftArmPivot.rotation.x = -swing * 0.75;
        ud.rightArmPivot.rotation.x = swing * 0.75;
      } else {
        ud.leftLegPivot.rotation.x = THREE.MathUtils.damp(ud.leftLegPivot.rotation.x, 0, 12, deltaSec);
        ud.rightLegPivot.rotation.x = THREE.MathUtils.damp(ud.rightLegPivot.rotation.x, 0, 12, deltaSec);
        ud.leftArmPivot.rotation.x = THREE.MathUtils.damp(ud.leftArmPivot.rotation.x, 0, 12, deltaSec);
        ud.rightArmPivot.rotation.x = -2.2 + Math.sin(nowMs * 0.01) * 0.35;
      }
      dynamicLabels.push({
        x: nEntry.mesh.position.x,
        y: nEntry.mesh.position.y + 2.55,
        z: nEntry.mesh.position.z,
        text: `${npc.gender === 'female' ? '👩‍🏫' : '👨‍🏫'} ${npc.name}`,
        kind: 'name',
      });
      dynamicLabels.push({
        x: nEntry.mesh.position.x,
        y: nEntry.mesh.position.y + 3.15,
        z: nEntry.mesh.position.z,
        text: npc.speechText || 'Speak to me! 💬',
        kind: 'speech-eng',
      });
    });

    // 4c. Sync Child Helper Robots (follow active schedule with raised scrolling sign, or rest in private room)
    const visibleRobots = Array.isArray(helperRobots)
      ? helperRobots.filter((r) => {
          if (r.scene !== me.scene) return false;
          if (me.scene === 'private_room') return (r.privateRoomId || null) === (me.privateRoomId || null);
          return true;
        })
      : [];
    const visibleRobotKeys = new Set(visibleRobots.map((r) => r.childId));
    helperRobotMeshes.forEach((entry, cid) => {
      if (!visibleRobotKeys.has(cid)) {
        actorsGroup.remove(entry.mesh);
        helperRobotMeshes.delete(cid);
      }
    });
    visibleRobots.forEach((r) => {
      const bTex = getOrCreateRobotBannerTex(r.childId, r.reminderText);
      bTex.offset.x = (nowMs * 0.00028) % 1;
      let rEntry = helperRobotMeshes.get(r.childId);
      if (!rEntry || rEntry.skin !== r.skin) {
        if (rEntry) actorsGroup.remove(rEntry.mesh);
        const rm = buildHelperRobot3D(THREE, mats, textures.shadowTex, r.skin, bTex);
        rm.position.set(r.x * WORLD_SCALE, 0.08, r.y * WORLD_SCALE);
        actorsGroup.add(rm);
        rEntry = { mesh: rm, skin: r.skin };
        helperRobotMeshes.set(r.childId, rEntry);
      }
      rEntry.mesh.position.x = THREE.MathUtils.damp(rEntry.mesh.position.x, r.x * WORLD_SCALE, 14, deltaSec);
      rEntry.mesh.position.z = THREE.MathUtils.damp(rEntry.mesh.position.z, r.y * WORLD_SCALE, 14, deltaSec);
      rEntry.mesh.position.y = me.scene === 'neighborhood' ? 0.08 : 0.1;

      const ud = rEntry.mesh.userData;
      ud.actor.rotation.y = r.isFollowing ? camState.yaw : r.facingYaw || 0.35;
      ud.actor.position.y = r.isFollowing ? Math.abs(Math.sin(nowMs * 0.008)) * 0.14 : Math.sin(nowMs * 0.003) * 0.04;
      ud.actor.rotation.z = r.isFollowing ? Math.sin(nowMs * 0.006) * 0.035 : 0;
      if (ud.propeller) {
        ud.propeller.rotation.y += deltaSec * (r.isFollowing ? 14 : 4.5);
      }
      ud.bannerHolder.visible = Boolean(r.isFollowing && r.reminderText);
      const targetArmX = r.isFollowing ? -2.55 : 0.08;
      ud.leftArmPivot.rotation.x = THREE.MathUtils.damp(ud.leftArmPivot.rotation.x, targetArmX, 12, deltaSec);
      ud.rightArmPivot.rotation.x = THREE.MathUtils.damp(ud.rightArmPivot.rotation.x, targetArmX, 12, deltaSec);

      dynamicLabels.push({
        x: rEntry.mesh.position.x,
        y: rEntry.mesh.position.y + (r.isFollowing ? 3.08 : 2.32),
        z: rEntry.mesh.position.z,
        text: `🤖 Robot (${r.childName})`,
        kind: 'name',
      });
    });

    // 5. Tap-to-move visual marker animation
    if (tapTarget) {
      tapMarker.visible = true;
      tapMarker.position.set(tapTarget.x * WORLD_SCALE, 0.02, tapTarget.y * WORLD_SCALE);
      const pulse = 0.85 + Math.sin(nowMs * 0.01) * 0.18;
      tapRing.scale.setScalar(pulse);
      tapDiamond.position.y = 0.85 + Math.sin(nowMs * 0.008) * 0.22;
      tapDiamond.rotation.y = nowMs * 0.004;
    } else {
      tapMarker.visible = false;
    }

    // 6. Camera follow + smooth exponential damping (Isometric 45°)
    const followX = me.x * WORLD_SCALE + camState.panX;
    const followZ = me.y * WORLD_SCALE + camState.panZ;
    camState.targetX = THREE.MathUtils.damp(camState.targetX, followX, 10, deltaSec);
    camState.targetZ = THREE.MathUtils.damp(camState.targetZ, followZ, 10, deltaSec);
    camState.yaw = THREE.MathUtils.damp(camState.yaw, camState.targetYaw, 10, deltaSec);
    camState.pitch = THREE.MathUtils.damp(camState.pitch, camState.targetPitch, 10, deltaSec);
    camState.zoom = THREE.MathUtils.damp(camState.zoom, camState.targetZoom, 12, deltaSec);

    if (Math.abs(camera.zoom - camState.zoom) > 0.001) {
      camera.zoom = camState.zoom;
      camera.updateProjectionMatrix();
    }

    const camDist = 90;
    const cosP = Math.cos(camState.pitch);
    camera.position.set(
      camState.targetX + camDist * cosP * Math.sin(camState.yaw),
      camDist * Math.sin(camState.pitch),
      camState.targetZ + camDist * cosP * Math.cos(camState.yaw)
    );
    camera.lookAt(camState.targetX, 0.8, camState.targetZ);

    // Anchor DirectionalLight shadow frustum around camera target so soft shadows stay razor-sharp everywhere!
    sunLight.position.set(camState.targetX + 36, 48, camState.targetZ + 30);
    sunLight.target.position.set(camState.targetX, 0, camState.targetZ);
    sunLight.target.updateMatrixWorld();

    // Update weather particles around camera target
    if (weatherParticles.length > 0) {
      weatherGroup.position.set(camState.targetX, 0, camState.targetZ);
      weatherParticles.forEach((wp) => {
        if (weatherMode === 'rain' || weatherMode === 'thunder') {
          wp.mesh.position.y -= deltaSec * 22;
          if (wp.mesh.position.y < 0.2) wp.mesh.position.y = 16;
        } else if (weatherMode === 'snow') {
          wp.mesh.position.y -= deltaSec * 2.5;
          wp.mesh.position.x += Math.sin(nowMs * 0.002 + wp.offset) * deltaSec * 0.8;
          if (wp.mesh.position.y < 0.2) wp.mesh.position.y = 16;
        } else if (weatherMode === 'fireflies') {
          wp.mesh.position.y = 1.6 + Math.sin(nowMs * 0.003 + wp.offset) * 0.9;
        }
      });
    }

    renderer.render(scene, camera);

    // 7. Project 3D floating labels cleanly onto HTML overlay
    if (labelLayerEl) {
      const allLabels = [...labelTargets, ...dynamicLabels];
      const viewW = window.innerWidth;
      const viewH = window.innerHeight;
      while (labelLayerEl.children.length < allLabels.length) {
        const el = document.createElement('div');
        el.className = 'world-float-label';
        labelLayerEl.appendChild(el);
      }
      for (let i = 0; i < labelLayerEl.children.length; i++) {
        const el = labelLayerEl.children[i];
        if (i >= allLabels.length) {
          el.style.display = 'none';
          continue;
        }
        const lbl = allLabels[i];
        projVec.set(lbl.x, lbl.y, lbl.z).project(camera);
        if (projVec.z > 1 || projVec.x < -1.15 || projVec.x > 1.15 || projVec.y < -1.15 || projVec.y > 1.15) {
          el.style.display = 'none';
          continue;
        }
        const sx = (projVec.x * 0.5 + 0.5) * viewW;
        const sy = (-projVec.y * 0.5 + 0.5) * viewH;
        el.style.display = 'block';
        el.style.left = `${sx.toFixed(1)}px`;
        el.style.top = `${sy.toFixed(1)}px`;
        if (el.textContent !== lbl.text) el.textContent = lbl.text;
        const cls =
          lbl.kind === 'name-me'
            ? 'world-float-label world-name-pill me'
            : lbl.kind === 'name'
              ? 'world-float-label world-name-pill'
              : lbl.kind === 'speech-eng'
                ? 'world-float-label world-speech-bubble eng'
                : lbl.kind === 'speech'
                  ? 'world-float-label world-speech-bubble'
                  : lbl.kind === 'live'
                    ? 'world-float-label world-live-banner'
                    : lbl.kind === 'lobby'
                      ? 'world-float-label world-live-banner lobby'
                      : 'world-float-label world-building-sign';
        if (el.className !== cls) el.className = cls;
      }
    }
  }

  return {
    THREE,
    camState,
    resize,
    raycastGround,
    renderFrame,
    setZoom(nextZoom) {
      camState.targetZoom = Math.max(0.55, Math.min(2.2, nextZoom));
    },
    resetCamera() {
      camState.targetYaw = Math.PI / 4;
      camState.targetPitch = Math.PI / 4;
      camState.panX = 0;
      camState.panZ = 0;
      camState.targetZoom = 1.0;
    },
    dispose() {
      mats.disposeAll();
      Object.values(textures).forEach((t) => t.dispose());
      leaderTex.dispose();
      ledAdTex.dispose();
      robotBannerCache.forEach((b) => b.tex.dispose());
      robotBannerCache.clear();
      _petGeoCache.forEach((g) => g.dispose());
      _petGeoCache.clear();
      renderer.dispose();
    },
  };
}

import { B2KSState, Member, SoccerOnlineRoom, SoccerPlayerInput } from '../types/b2ks';
import { formatFamilyBrand, getFamilyFirebaseRoot, normalizeFamilySlug, resolveNeighborhoodLocations } from './constants';
import { drawDetailedChibiOnContext } from './worldRenderer';

export interface SoccerEngineDeps {
  getState: () => B2KSState;
  getCurrentUser: () => Member;
  getFirebaseUrl: () => string;
  playClick: () => void;
  playCoin: () => void;
  playSuccess: () => void;
  playError: () => void;
  triggerConfetti: () => void;
  triggerSpeechBubble: (member: Member, text: string, isEng: boolean) => void;
  showToast: (msg: string) => void;
  openModal?: (id: string) => void;
  closeModal?: (id: string) => void;
}

const LOCAL_SOCCER_ROOM_KEY = 'b2ks_soccer_online_room';
const LOCAL_SOCCER_P2_KEY = 'b2ks_soccer_p2_input';

function createDefaultOnlineRoom(): SoccerOnlineRoom {
  return {
    status: 'idle',
    hostId: '',
    p1Id: '',
    p1Name: '',
    p2Id: null,
    p2Name: null,
    p1Goals: 0,
    p2Goals: 0,
    timeLeft: 60,
    p1x: 260,
    p1y: 295,
    p1Dir: 'up',
    p1Moving: false,
    p2x: 260,
    p2y: 65,
    p2Dir: 'down',
    p2Moving: false,
    bx: 260,
    by: 180,
    bvx: 0,
    bvy: 0,
    goalBannerText: '',
    goalBannerUntil: 0,
    readyMap: {},
    updatedAt: 0
  };
}

export function createSoccerMiniGame(deps: SoccerEngineDeps) {
  const W = 520;
  const H = 360;
  const GOAL_X1 = 185;
  const GOAL_X2 = 335;
  const GOAL_Y = 26;

  let rafId: number | null = null;
  let timerId: number | null = null;
  let syncPollId: number | null = null;
  let active = false;
  let mode: 'menu' | 'solo' | 'online_2p' | 'spectator' = 'menu';

  const heldDir = { up: false, down: false, left: false, right: false };

  // Solo match state
  let solo = {
    playerGoals: 0,
    aiGoals: 0,
    timeLeft: 45,
    finished: false,
    goalBannerUntil: 0,
    goalBannerText: '',
    px: 260,
    py: 295,
    pDir: 'up',
    pMoving: false,
    bx: 260,
    by: 255,
    bvx: 0,
    bvy: 0,
    bAngle: 0,
    gkX: 260,
    gkVx: 2.2,
    defX: 260,
    defY: 165,
    defVx: 2.0,
    kickCooldownUntil: 0
  };

  // Online 2P & Spectator shared room state
  let roomState: SoccerOnlineRoom = createDefaultOnlineRoom();
  let remoteP2Input: SoccerPlayerInput = { playerId: '', dx: 0, dy: 0, kickSeq: 0, ts: 0 };
  let lastHandledP2KickSeq = 0;
  let localP2KickSeq = 0;
  let localKickCooldownUntil = 0;
  let lastRoomPushAt = 0;
  let lastP2InputPushAt = 0;
  let lastLobbySignature = '';
  let bAngleOnline = 0;

  function pushOnlineRoom(immediate = false) {
    const now = Date.now();
    if (!immediate && now - lastRoomPushAt < 105) return;
    lastRoomPushAt = now;
    const slug = normalizeFamilySlug(deps.getState().familyName);
    const fbRoot = getFamilyFirebaseRoot(deps.getState().familyName);
    roomState.updatedAt = now;
    try {
      localStorage.setItem(`${LOCAL_SOCCER_ROOM_KEY}_${slug}`, JSON.stringify(roomState));
    } catch {
      // ignore
    }
    const fb = deps.getFirebaseUrl();
    if (fb) {
      fetch(`${fb}/${fbRoot}/soccer_room.json`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(roomState)
      }).catch(() => {});
    }
  }

  function pushP2Input(input: SoccerPlayerInput, immediate = false) {
    const now = Date.now();
    if (!immediate && now - lastP2InputPushAt < 85) return;
    lastP2InputPushAt = now;
    const slug = normalizeFamilySlug(deps.getState().familyName);
    const fbRoot = getFamilyFirebaseRoot(deps.getState().familyName);
    try {
      localStorage.setItem(`${LOCAL_SOCCER_P2_KEY}_${slug}`, JSON.stringify(input));
    } catch {
      // ignore
    }
    const fb = deps.getFirebaseUrl();
    if (fb) {
      fetch(`${fb}/${fbRoot}/soccer_p2_input.json`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(input)
      }).catch(() => {});
    }
  }

  function pullSoccerRoomFromFirebase() {
    const slug = normalizeFamilySlug(deps.getState().familyName);
    const fbRoot = getFamilyFirebaseRoot(deps.getState().familyName);
    const fb = deps.getFirebaseUrl();
    if (fb) {
      fetch(`${fb}/${fbRoot}/soccer_room.json`)
        .then((r) => r.json())
        .then((remote: SoccerOnlineRoom | null) => {
          if (remote && (remote.updatedAt || 0) > (roomState.updatedAt || 0)) {
            onRemoteSoccerRoomUpdate(remote);
          }
        })
        .catch(() => {});

      const me = deps.getCurrentUser();
      if (active && mode === 'online_2p' && roomState.status === 'playing' && roomState.hostId === me.id) {
        fetch(`${fb}/${fbRoot}/soccer_p2_input.json`)
          .then((r) => r.json())
          .then((inp: SoccerPlayerInput | null) => {
            if (inp && (inp.ts || 0) > (remoteP2Input.ts || 0)) {
              remoteP2Input = inp;
            }
          })
          .catch(() => {});
      }
    } else {
      try {
        const localStr = localStorage.getItem(`${LOCAL_SOCCER_ROOM_KEY}_${slug}`);
        if (localStr) {
          const parsed = JSON.parse(localStr) as SoccerOnlineRoom;
          if (parsed && (parsed.updatedAt || 0) > (roomState.updatedAt || 0)) {
            onRemoteSoccerRoomUpdate(parsed);
          }
        }
        const p2Str = localStorage.getItem(`${LOCAL_SOCCER_P2_KEY}_${slug}`);
        if (p2Str) {
          const inp = JSON.parse(p2Str) as SoccerPlayerInput;
          if (inp && (inp.ts || 0) > (remoteP2Input.ts || 0)) {
            remoteP2Input = inp;
          }
        }
      } catch {
        // ignore
      }
    }
  }

  function onRemoteSoccerRoomUpdate(remote: SoccerOnlineRoom) {
    const me = deps.getCurrentUser();
    const isHostActive = active && mode === 'online_2p' && roomState.hostId === me.id && roomState.status === 'playing';
    if (isHostActive) return; // Host owns live match physics
    const prevStatus = roomState.status;
    roomState = { ...createDefaultOnlineRoom(), ...remote };
    if (!roomState.readyMap) roomState.readyMap = {};

    const isParticipant = roomState.p1Id === me.id || roomState.p2Id === me.id;
    if (prevStatus === 'playing' && roomState.status === 'idle' && mode === 'online_2p') {
      if (timerId) {
        clearInterval(timerId);
        timerId = null;
      }
      deps.showToast('🚪 Chủ phòng đã thoát khỏi phòng bóng đá!');
    }

    if (prevStatus !== 'playing' && roomState.status === 'playing' && isParticipant) {
      mode = 'online_2p';
      const modalEl = document.getElementById('soccer-modal');
      if (!modalEl || modalEl.style.display !== 'flex') {
        if (deps.openModal) {
          deps.openModal('soccer-modal');
        } else if (modalEl) {
          modalEl.style.display = 'flex';
          openSoccerArena();
        }
      } else {
        renderUIState();
      }
      deps.playSuccess();
      deps.showToast('⚽ Trận đấu Bóng Đá đã bắt đầu!');
      return;
    }

    if (active) {
      const modalEl = document.getElementById('soccer-modal');
      if (modalEl && modalEl.style.display === 'flex') {
        if (roomState.status === 'playing') {
          if (isParticipant) {
            mode = 'online_2p';
          } else if (mode !== 'solo') {
            mode = 'spectator';
          }
        } else if (roomState.status === 'idle' && mode === 'spectator') {
          mode = 'menu';
        }
        renderUIState();
      }
    }
  }

  function onRemoteP2InputUpdate(inp: SoccerPlayerInput) {
    if ((inp.ts || 0) > (remoteP2Input.ts || 0)) {
      remoteP2Input = inp;
    }
  }

  function getNearbyMembersAtPitch(): Member[] {
    const st = deps.getState();
    const pitchLoc = resolveNeighborhoodLocations(st).find((l) => l.id === 'soccer');
    const px = pitchLoc ? pitchLoc.x : 2060;
    const py = pitchLoc ? pitchLoc.y : 1400;
    return st.members.filter(
      (m) => m.scene === 'neighborhood' && Math.hypot(m.x - px, m.y - py) <= 220
    );
  }

  function resetSoloPositions() {
    solo.px = 260;
    solo.py = 300;
    solo.pDir = 'up';
    solo.pMoving = false;
    solo.bx = 260;
    solo.by = 258;
    solo.bvx = 0;
    solo.bvy = 0;
    solo.gkX = 260;
    solo.defX = 260;
    solo.defY = 162;
  }

  function resetOnlinePositions() {
    roomState.p1x = 260;
    roomState.p1y = 298;
    roomState.p1Dir = 'up';
    roomState.p1Moving = false;
    roomState.p2x = 260;
    roomState.p2y = 62;
    roomState.p2Dir = 'down';
    roomState.p2Moving = false;
    roomState.bx = 260;
    roomState.by = 180;
    roomState.bvx = 0;
    roomState.bvy = 0;
  }

  function openSoccerArena() {
    active = true;
    lastLobbySignature = '';
    pullSoccerRoomFromFirebase();

    const me = deps.getCurrentUser();
    // Auto-route user cleanly based on ongoing 2P room!
    if (roomState.status === 'playing') {
      if (roomState.p1Id === me.id || roomState.p2Id === me.id) {
        mode = 'online_2p';
      } else {
        mode = 'spectator';
      }
    } else if (roomState.status === 'lobby') {
      mode = 'online_2p';
    } else {
      mode = 'solo';
      startSoloMatchInternal();
    }

    startLoopAndSync();
    renderUIState();
  }

  function startSoloMatchInternal() {
    mode = 'solo';
    solo.playerGoals = 0;
    solo.aiGoals = 0;
    solo.timeLeft = 45;
    solo.finished = false;
    solo.goalBannerUntil = 0;
    solo.goalBannerText = '';
    resetSoloPositions();

    if (timerId) clearInterval(timerId);
    timerId = window.setInterval(() => {
      if (!active || mode !== 'solo' || solo.finished) return;
      solo.timeLeft = Math.max(0, solo.timeLeft - 1);
      updateScoreHUD();
      if (solo.timeLeft <= 0) {
        finishSoloMatch();
      }
    }, 1000);
    renderUIState();
  }

  function startLoopAndSync() {
    if (syncPollId) clearInterval(syncPollId);
    syncPollId = window.setInterval(() => {
      if (!active) return;
      pullSoccerRoomFromFirebase();
      if (mode === 'online_2p' && roomState.status === 'lobby') {
        renderLobbyPanel();
      }
    }, 140);

    if (rafId) cancelAnimationFrame(rafId);
    rafId = requestAnimationFrame(loop);
  }

  function stopMatch() {
    active = false;
    heldDir.up = heldDir.down = heldDir.left = heldDir.right = false;
    if (timerId) {
      clearInterval(timerId);
      timerId = null;
    }
    if (syncPollId) {
      clearInterval(syncPollId);
      syncPollId = null;
    }
    if (rafId) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
  }

  function finishSoloMatch() {
    solo.finished = true;
    if (timerId) {
      clearInterval(timerId);
      timerId = null;
    }
    const me = deps.getCurrentUser();
    const brand = (deps.getState().familyName || 'B2KS').trim() || 'B2KS';
    if (solo.playerGoals > solo.aiGoals) {
      deps.playSuccess();
      deps.triggerConfetti();
      deps.triggerSpeechBubble(me, formatFamilyBrand(`We won ${solo.playerGoals}-${solo.aiGoals} at B2KS Stadium! ⚽🏆`, brand), true);
      deps.showToast(formatFamilyBrand(`🏆 Chiến thắng ${solo.playerGoals} - ${solo.aiGoals} tại Sân Bóng Đá B2KS!`, brand));
    } else if (solo.playerGoals === solo.aiGoals) {
      deps.playClick();
      deps.triggerSpeechBubble(me, `Nice draw ${solo.playerGoals}-${solo.aiGoals}! Good game! ⚽`, true);
    } else {
      deps.playClick();
      deps.triggerSpeechBubble(me, `Good match! Let's play again! ⚽`, true);
    }
    updateScoreHUD();
  }

  function finishOnlineMatch() {
    roomState.status = 'finished';
    roomState.readyMap = {
      ...(roomState.p1Id ? { [roomState.p1Id]: false } : {}),
      ...(roomState.p2Id ? { [roomState.p2Id]: false } : {})
    };
    if (timerId) {
      clearInterval(timerId);
      timerId = null;
    }
    pushOnlineRoom(true);
    const me = deps.getCurrentUser();
    if (roomState.p1Goals > roomState.p2Goals) {
      deps.playSuccess();
      deps.triggerConfetti();
      deps.showToast(`🏆 ${roomState.p1Name} thắng ${roomState.p1Goals} - ${roomState.p2Goals}!`);
      if (me.id === roomState.p1Id) {
        deps.triggerSpeechBubble(me, `Victory ${roomState.p1Goals}-${roomState.p2Goals}! ⚽🏆`, true);
      }
    } else if (roomState.p2Goals > roomState.p1Goals) {
      deps.playSuccess();
      deps.triggerConfetti();
      deps.showToast(`🏆 ${roomState.p2Name} thắng ${roomState.p2Goals} - ${roomState.p1Goals}!`);
      if (me.id === roomState.p2Id) {
        deps.triggerSpeechBubble(me, `Victory ${roomState.p2Goals}-${roomState.p1Goals}! ⚽🏆`, true);
      }
    } else {
      deps.playClick();
      deps.showToast(`🤝 Trận hòa ${roomState.p1Goals} - ${roomState.p2Goals}!`);
    }
    renderUIState();
  }

  // Lobby & Mode Controls
  function switchToSoloMode() {
    deps.playClick();
    startSoloMatchInternal();
  }

  function switchTo2PMode() {
    deps.playClick();
    mode = 'online_2p';
    pullSoccerRoomFromFirebase();
    renderUIState();
  }

  function create2PRoom() {
    const me = deps.getCurrentUser();
    deps.playClick();
    roomState = createDefaultOnlineRoom();
    roomState.status = 'lobby';
    roomState.hostId = me.id;
    roomState.p1Id = me.id;
    roomState.p1Name = me.name;
    roomState.readyMap = { [me.id]: false };
    lastHandledP2KickSeq = 0;
    remoteP2Input = { playerId: '', dx: 0, dy: 0, kickSeq: 0, ts: 0 };
    mode = 'online_2p';
    pushOnlineRoom(true);
    renderUIState();
    deps.showToast('⚽ Đã tạo phòng đấu 2 người! Đợi người thứ 2 bấm Tham Gia...');
  }

  function join2PRoom() {
    const me = deps.getCurrentUser();
    if (roomState.status !== 'lobby' && roomState.status !== 'finished') return;
    if (roomState.p1Id === me.id) return deps.showToast('ℹ️ Bạn đang là Chủ phòng (Đội Xanh P1)!');
    if (roomState.p2Id && roomState.p2Id !== me.id) return deps.showToast('⚠️ Phòng đã đủ 2 người! Bạn có thể làm Khán giả xem trực tiếp.');
    deps.playSuccess();
    roomState.p2Id = me.id;
    roomState.p2Name = me.name;
    roomState.readyMap = {
      ...(roomState.readyMap || {}),
      [roomState.p1Id]: Boolean(roomState.readyMap?.[roomState.p1Id]),
      [me.id]: false
    };
    mode = 'online_2p';
    pushOnlineRoom(true);
    renderUIState();
    deps.showToast(`🔴 ${me.name} đã vào Đội Đỏ (P2)!`);
  }

  function toggle2PReady() {
    const me = deps.getCurrentUser();
    if (roomState.status !== 'lobby' && roomState.status !== 'finished') return;
    if (roomState.p1Id !== me.id && roomState.p2Id !== me.id) return;
    deps.playClick();
    const curReady = Boolean(roomState.readyMap?.[me.id]);
    roomState.readyMap = {
      ...(roomState.readyMap || {}),
      [me.id]: !curReady
    };
    pushOnlineRoom(true);
    lastLobbySignature = '';
    renderLobbyPanel();
  }

  function start2PMatch() {
    const me = deps.getCurrentUser();
    if ((roomState.status !== 'lobby' && roomState.status !== 'finished') || roomState.hostId !== me.id) {
      if (roomState.hostId !== me.id) {
        deps.playError();
        deps.showToast('⚠️ Chỉ người tạo phòng mới có thể bấm Vào Game!');
      }
      return;
    }
    if (!roomState.p2Id) return deps.showToast('⏳ Cần có Người chơi 2 tham gia trước!');
    const p1Ready = Boolean(roomState.readyMap?.[roomState.p1Id]);
    const p2Ready = Boolean(roomState.readyMap?.[roomState.p2Id]);
    if (!p1Ready || !p2Ready) {
      deps.playError();
      return deps.showToast('⚠️ Cả 2 người chơi phải bấm "✅ Sẵn Sàng" mới có thể vào game!');
    }
    deps.playSuccess();
    roomState.status = 'playing';
    roomState.p1Goals = 0;
    roomState.p2Goals = 0;
    roomState.timeLeft = 60;
    roomState.goalBannerText = '';
    roomState.goalBannerUntil = 0;
    lastHandledP2KickSeq = remoteP2Input.kickSeq || 0;
    resetOnlinePositions();
    pushOnlineRoom(true);

    if (timerId) clearInterval(timerId);
    timerId = window.setInterval(() => {
      if (!active || mode !== 'online_2p' || roomState.status !== 'playing' || roomState.hostId !== deps.getCurrentUser().id) return;
      roomState.timeLeft = Math.max(0, roomState.timeLeft - 1);
      pushOnlineRoom(true);
      updateScoreHUD();
      if (roomState.timeLeft <= 0) {
        finishOnlineMatch();
      }
    }, 1000);
    renderUIState();
  }

  function leave2PRoom() {
    const me = deps.getCurrentUser();
    deps.playClick();
    if (timerId) {
      clearInterval(timerId);
      timerId = null;
    }
    if (roomState.p1Id === me.id || roomState.hostId === me.id) {
      roomState = createDefaultOnlineRoom();
    } else if (roomState.p2Id === me.id) {
      const nextReady = { ...(roomState.readyMap || {}) };
      delete nextReady[me.id];
      roomState.readyMap = nextReady;
      roomState.p2Id = null;
      roomState.p2Name = null;
      if (roomState.status === 'playing' || roomState.status === 'finished') {
        roomState.status = 'lobby';
      }
    }
    pushOnlineRoom(true);
    mode = 'online_2p';
    lastLobbySignature = '';
    renderUIState();
  }

  function spectateMatch() {
    deps.playClick();
    mode = 'spectator';
    renderUIState();
  }

  function renderUIState() {
    const btn1p = document.getElementById('soccer-mode-1p-btn');
    const btn2p = document.getElementById('soccer-mode-2p-btn');
    const btnSpec = document.getElementById('soccer-mode-spec-btn');
    const lobbyPanel = document.getElementById('soccer-2p-lobby');
    const pitchWrap = document.getElementById('soccer-pitch-wrap');
    const controlsWrap = document.getElementById('soccer-controls-wrap');
    const restartBtn = document.getElementById('soccer-restart-btn');

    const hasLiveOnline = roomState.status === 'playing' || roomState.status === 'lobby';
    if (btn1p) btn1p.style.background = mode === 'solo' ? '#15803D' : '#64748B';
    if (btn2p) btn2p.style.background = mode === 'online_2p' ? '#0284C7' : '#64748B';
    if (btnSpec) {
      btnSpec.style.display = hasLiveOnline ? 'inline-flex' : 'none';
      btnSpec.style.background = mode === 'spectator' ? '#DC2626' : '#64748B';
    }

    const showLobby = mode === 'online_2p' && (roomState.status === 'idle' || roomState.status === 'lobby' || roomState.status === 'finished');
    if (lobbyPanel) {
      lobbyPanel.style.display = showLobby ? 'block' : 'none';
      if (showLobby) renderLobbyPanel();
    }

    const showPitch =
      mode === 'solo' ||
      (mode === 'online_2p' && roomState.status === 'playing') ||
      mode === 'spectator';
    if (pitchWrap) pitchWrap.style.display = showPitch ? 'flex' : 'none';

    const showPlayerControls =
      mode === 'solo' ||
      (mode === 'online_2p' && roomState.status === 'playing');
    if (controlsWrap) controlsWrap.style.display = showPlayerControls ? 'flex' : 'none';

    if (restartBtn) {
      restartBtn.style.display = mode === 'solo' ? 'inline-flex' : 'none';
    }

    updateScoreHUD();
  }

  function renderLobbyPanel() {
    const lobbyPanel = document.getElementById('soccer-2p-lobby');
    if (!lobbyPanel) return;
    const me = deps.getCurrentUser();
    const nearby = getNearbyMembersAtPitch();
    const p1Ready = Boolean(roomState.p1Id && roomState.readyMap?.[roomState.p1Id]);
    const p2Ready = Boolean(roomState.p2Id && roomState.readyMap?.[roomState.p2Id]);
    const sig = `${roomState.status}|${roomState.p1Id}|${roomState.p2Id}|${p1Ready ? 1 : 0}|${p2Ready ? 1 : 0}|${roomState.p1Goals}|${roomState.p2Goals}|${me.id}|${nearby.map((m) => m.id).join(',')}`;
    if (sig === lastLobbySignature) return;
    lastLobbySignature = sig;

    const nearbyHtml = nearby.length > 0
      ? nearby.map((m) => `<span class="tag" style="background:#D1FAE5; color:#065F46; border-color:#10B981;">${m.name}</span>`).join(' ')
      : '<span style="font-size:11.5px; color:#64748B;">Chưa có thêm thành viên nào đứng cạnh sân</span>';

    if (roomState.status === 'idle') {
      lobbyPanel.innerHTML = `
        <div style="text-align:center; padding:10px;">
          <div style="font-size:30px;">⚽👥</div>
          <div style="font-weight:700; font-size:15px; color:#0F172A; margin-top:4px;">Đấu Bóng Đá 2 Người Online (Miễn Phí 0⭐)</div>
          <div style="font-size:12px; color:#475569; margin:6px 0 10px;">Thành viên đang có mặt tại Sân Bóng: ${nearbyHtml}</div>
          <button type="button" class="btn btn-primary" style="padding:10px 18px; font-size:14px;" onclick="createSoccer2PRoom()">🏟️ Tạo Phòng Đấu 1v1</button>
        </div>
      `;
      return;
    }

    const isP1 = roomState.p1Id === me.id;
    const isP2 = roomState.p2Id === me.id;
    const isHost = roomState.hostId === me.id;
    const isFinished = roomState.status === 'finished';
    const myReady = Boolean(roomState.readyMap?.[me.id]);
    const bothReady = Boolean(roomState.p1Id && roomState.p2Id && p1Ready && p2Ready);

    lobbyPanel.innerHTML = `
      <div style="display:flex; flex-direction:column; gap:10px;">
        ${isFinished ? `
          <div style="background:#FEF3C7; border:2px solid #F59E0B; border-radius:10px; padding:8px; text-align:center; font-weight:700; color:#92400E;">
            🏆 KẾT QUẢ TRẬN ĐẤU: 🔵 ${roomState.p1Name} (${roomState.p1Goals}) — (${roomState.p2Goals}) ${roomState.p2Name || 'P2'} 🔴
          </div>
        ` : ''}
        <div style="display:grid; grid-template-columns:1fr auto 1fr; gap:8px; align-items:center;">
          <div style="background:#EFF6FF; border:2.5px solid ${p1Ready ? '#16A34A' : '#2563EB'}; border-radius:10px; padding:10px; text-align:center;">
            <div style="font-size:11px; font-weight:700; color:#1D4ED8;">🔵 ĐỘI XANH (P1 • Chủ phòng)</div>
            <div style="font-size:15px; font-weight:700; color:#0F172A; margin-top:4px;">${roomState.p1Name}</div>
            <div style="font-size:11px; color:#64748B;">Tấn công lên ▲</div>
            <div style="margin-top:6px;">
              <span class="tag" style="background:${p1Ready ? '#16A34A' : '#F59E0B'}; color:#FFF; font-size:11px;">
                ${p1Ready ? '✅ Đã sẵn sàng' : '⏳ Chưa sẵn sàng'}
              </span>
            </div>
          </div>
          <div style="font-weight:700; font-size:16px; color:#0F172A;">VS</div>
          <div style="background:#FEF2F2; border:2.5px solid ${p2Ready ? '#16A34A' : '#DC2626'}; border-radius:10px; padding:10px; text-align:center;">
            <div style="font-size:11px; font-weight:700; color:#B91C1C;">🔴 ĐỘI ĐỎ (P2)</div>
            <div style="font-size:15px; font-weight:700; color:#0F172A; margin-top:4px;">${roomState.p2Name || '⏳ Đang chờ P2...'}</div>
            <div style="font-size:11px; color:#64748B;">Tấn công xuống ▼</div>
            <div style="margin-top:6px;">
              ${roomState.p2Id ? `<span class="tag" style="background:${p2Ready ? '#16A34A' : '#F59E0B'}; color:#FFF; font-size:11px;">${p2Ready ? '✅ Đã sẵn sàng' : '⏳ Chưa sẵn sàng'}</span>` : ''}
            </div>
          </div>
        </div>
        <div style="font-size:11.5px; color:#475569; text-align:center;">Đang ở Sân Bóng: ${nearbyHtml}</div>
        <div style="display:flex; gap:8px; justify-content:center; align-items:center; flex-wrap:wrap;">
          ${!isP1 && !isP2 && !roomState.p2Id ? `<button type="button" class="btn btn-primary" onclick="joinSoccer2PRoom()">🙋 Tham Gia Đội Đỏ (P2)</button>` : ''}
          ${(isP1 || isP2) ? `<button type="button" class="btn ${myReady ? 'btn-accent' : 'btn-primary'}" onclick="toggleSoccer2PReady()">${myReady ? '✅ Đã Sẵn Sàng (Hủy)' : '✋ Xác Nhận Sẵn Sàng'}</button>` : ''}
          ${isHost ? `<button type="button" class="btn" ${!bothReady ? 'disabled' : ''} style="background:${bothReady ? '#16A34A' : '#94A3B8'}; color:#FFF; ${!bothReady ? 'opacity:0.45; cursor:not-allowed; filter:grayscale(0.35);' : 'box-shadow:0 3px 0 #14532D;'}" onclick="startSoccer2PMatch()">🚀 ${isFinished ? 'Đá Lại Trận Mới' : 'Vào Game (Bắt Đầu!)'}</button>` : ''}
          ${isP2 ? `<span class="tag" style="background:#FEF9C3; color:#854D0E; border:1.5px solid #CA8A04; padding:7px 10px;">⏳ Chờ chủ phòng (${roomState.p1Name}) bấm Vào Game khi cả 2 Sẵn Sàng...</span>` : ''}
          ${(isP1 || isP2) ? `<button type="button" class="btn btn-danger btn-sm" onclick="leaveSoccer2PRoom()">🚪 Rời Phòng</button>` : ''}
          <button type="button" class="btn btn-sm" style="background:#7C3AED;" onclick="spectateSoccerMatch()">📺 Xem Đá (Khán giả)</button>
        </div>
      </div>
    `;
  }

  function updateScoreHUD() {
    const scoreEl = document.getElementById('soccer-scoreboard');
    const timeEl = document.getElementById('soccer-timer');
    const statusEl = document.getElementById('soccer-status-text');
    const me = deps.getCurrentUser();

    const brand = (deps.getState().familyName || 'B2KS').trim() || 'B2KS';
    if (mode === 'solo') {
      if (scoreEl) {
        scoreEl.innerHTML = `<span style="color:#0369A1;">⚽ ${me.name}: <b>${solo.playerGoals}</b></span> <span style="color:#64748B;">—</span> <span style="color:#B91C1C;"><b>${solo.aiGoals}</b> :Thủ môn ${brand} 🧤</span>`;
      }
      if (timeEl) timeEl.textContent = `⏱️ ${solo.timeLeft}s`;
      if (statusEl) {
        if (solo.finished) {
          statusEl.textContent =
            solo.playerGoals > solo.aiGoals
              ? `🏆 HẾT GIỜ! ${me.name} thắng ${solo.playerGoals} - ${solo.aiGoals}!`
              : solo.playerGoals === solo.aiGoals
              ? `🤝 HẾT GIỜ! Hòa ${solo.playerGoals} - ${solo.aiGoals}!`
              : `🧤 HẾT GIỜ! Đội ${brand} thắng ${solo.aiGoals} - ${solo.playerGoals}!`;
          statusEl.style.color = solo.playerGoals > solo.aiGoals ? '#15803D' : '#B45309';
        } else {
          statusEl.textContent = '🆓 Đá Solo 0⭐ • Rê bóng vượt hậu vệ & bấm ⚡ Sút vào lưới!';
          statusEl.style.color = '#1E293B';
        }
      }
      return;
    }

    if (scoreEl) {
      scoreEl.innerHTML = `<span style="color:#1D4ED8;">🔵 ${roomState.p1Name || 'P1'}: <b>${roomState.p1Goals}</b></span> <span style="color:#64748B;">—</span> <span style="color:#DC2626;"><b>${roomState.p2Goals}</b> :${roomState.p2Name || 'P2'} 🔴</span>`;
    }
    if (timeEl) timeEl.textContent = `⏱️ ${roomState.timeLeft}s`;
    if (statusEl) {
      if (mode === 'spectator') {
        statusEl.textContent =
          roomState.status === 'playing'
            ? `📺 KHÁN GIẢ TRỰC TIẾP: Đang theo dõi ${roomState.p1Name} vs ${roomState.p2Name}!`
            : roomState.status === 'finished'
            ? `🏁 Trận đấu kết thúc (${roomState.p1Goals} - ${roomState.p2Goals})!`
            : `🟡 Đang chờ ${roomState.p1Name || 'Chủ phòng'} bắt đầu trận đấu 2 người...`;
        statusEl.style.color = '#7C3AED';
      } else if (roomState.status === 'playing') {
        const mySide = roomState.p1Id === me.id ? '🔵 Đội Xanh (Sút lên ▲)' : '🔴 Đội Đỏ (Sút xuống ▼)';
        statusEl.textContent = `🔥 TRẬN ĐẤU 2 NGƯỜI ONLINE • Bạn là ${mySide}`;
        statusEl.style.color = '#0369A1';
      } else {
        statusEl.textContent = '👥 Phòng Đấu 2 Người Miễn Phí (0⭐) — Có thể rủ người khác đến sân xem trực tiếp!';
        statusEl.style.color = '#1E293B';
      }
    }
  }

  function applyKickVelocity(
    px: number,
    py: number,
    pDir: string,
    defaultDy: number,
    targetX?: number,
    targetY?: number
  ) {
    const d = Math.hypot(roomState.bx - px, roomState.by - py);
    if (d > 62) return false;
    let dx = 0;
    let dy = defaultDy;
    if (typeof targetX === 'number' && typeof targetY === 'number') {
      dx = targetX - roomState.bx;
      dy = targetY - roomState.by;
    } else if (pDir === 'left') {
      dx = -0.35;
      dy = defaultDy * 0.94;
    } else if (pDir === 'right') {
      dx = 0.35;
      dy = defaultDy * 0.94;
    } else if (pDir === 'up') {
      dx = ((GOAL_X1 + GOAL_X2) / 2 - roomState.bx) * 0.004;
      dy = -1;
    } else if (pDir === 'down') {
      dx = ((GOAL_X1 + GOAL_X2) / 2 - roomState.bx) * 0.004;
      dy = 1;
    }
    const len = Math.hypot(dx, dy) || 1;
    const power = 9.4;
    roomState.bvx = (dx / len) * power;
    roomState.bvy = (dy / len) * power;
    deps.playClick();
    return true;
  }

  function kickBall(targetX?: number, targetY?: number) {
    if (!active) return;
    const now = Date.now();

    if (mode === 'solo') {
      if (solo.finished || now < solo.kickCooldownUntil) return;
      const d = Math.hypot(solo.bx - solo.px, solo.by - solo.py);
      if (d > 58) {
        deps.showToast('🏃 Lại gần quả bóng hơn rồi mới sút nhé!');
        return;
      }
      solo.kickCooldownUntil = now + 260;
      let dx = 0;
      let dy = -1;
      if (typeof targetX === 'number' && typeof targetY === 'number') {
        dx = targetX - solo.bx;
        dy = targetY - solo.by;
      } else if (solo.pDir === 'left') {
        dx = -0.35;
        dy = -0.95;
      } else if (solo.pDir === 'right') {
        dx = 0.35;
        dy = -0.95;
      } else if (solo.pDir === 'down') {
        dx = 0;
        dy = 1;
      } else {
        const goalMid = (GOAL_X1 + GOAL_X2) / 2;
        dx = (goalMid - solo.bx) * 0.004;
        dy = -1;
      }
      const len = Math.hypot(dx, dy) || 1;
      solo.bvx = (dx / len) * 9.4;
      solo.bvy = (dy / len) * 9.4;
      deps.playClick();
      return;
    }

    if (mode !== 'online_2p' || roomState.status !== 'playing' || now < localKickCooldownUntil) return;
    localKickCooldownUntil = now + 260;
    const me = deps.getCurrentUser();

    if (roomState.p1Id === me.id) {
      if (!applyKickVelocity(roomState.p1x, roomState.p1y, roomState.p1Dir, -1, targetX, targetY)) {
        deps.showToast('🏃 Lại gần quả bóng hơn rồi mới sút nhé!');
      } else {
        pushOnlineRoom(true);
      }
    } else if (roomState.p2Id === me.id) {
      localP2KickSeq += 1;
      const { dx, dy } = getLocalDirVector();
      pushP2Input(
        {
          playerId: me.id,
          dx,
          dy,
          kickSeq: localP2KickSeq,
          kickTx: targetX,
          kickTy: targetY,
          ts: now
        },
        true
      );
      deps.playClick();
    }
  }

  function getLocalDirVector() {
    let dx = 0;
    let dy = 0;
    if (heldDir.up) dy -= 1;
    if (heldDir.down) dy += 1;
    if (heldDir.left) dx -= 1;
    if (heldDir.right) dx += 1;
    const len = Math.hypot(dx, dy);
    if (len > 1) { dx /= len; dy /= len; }
    return { dx, dy };
  }

  function setTouchDir(dir: 'up' | 'down' | 'left' | 'right', down: boolean) {
    heldDir[dir] = down;
  }

  function handleKey(key: string, down: boolean): boolean {
    if (!active) return false;
    const k = key.toLowerCase();
    if (k === 'arrowup' || k === 'w') { heldDir.up = down; return true; }
    if (k === 'arrowdown' || k === 's') { heldDir.down = down; return true; }
    if (k === 'arrowleft' || k === 'a') { heldDir.left = down; return true; }
    if (k === 'arrowright' || k === 'd') { heldDir.right = down; return true; }
    if (down && (k === ' ' || k === 'enter')) {
      kickBall();
      return true;
    }
    return false;
  }

  function loop() {
    if (!active) return;
    const canvas = document.getElementById('soccer-canvas') as HTMLCanvasElement | null;
    const ctx = canvas?.getContext('2d');
    const now = Date.now();

    if (mode === 'solo' && ctx) {
      stepSoloPhysics(now);
      drawPitchBase(ctx);
      drawSoloEntities(ctx, now);
    } else if ((mode === 'online_2p' || mode === 'spectator') && ctx) {
      const me = deps.getCurrentUser();
      if (mode === 'online_2p' && roomState.status === 'playing') {
        if (roomState.hostId === me.id) {
          stepOnlineHostPhysics(now);
        } else if (roomState.p2Id === me.id) {
          const { dx, dy } = getLocalDirVector();
          pushP2Input({
            playerId: me.id,
            dx,
            dy,
            kickSeq: localP2KickSeq,
            ts: now
          });
        }
      }
      bAngleOnline += Math.hypot(roomState.bvx || 0, roomState.bvy || 0) * 0.08;
      drawPitchBase(ctx);
      drawOnlineEntities(ctx, now);
      updateScoreHUD();
    }

    rafId = requestAnimationFrame(loop);
  }

  function stepSoloPhysics(now: number) {
    if (solo.finished || now < solo.goalBannerUntil) return;
    const { dx, dy } = getLocalDirVector();
    solo.pMoving = dx !== 0 || dy !== 0;

    if (solo.pMoving) {
      solo.px = Math.max(26, Math.min(W - 26, solo.px + dx * 3.8));
      solo.py = Math.max(46, Math.min(H - 22, solo.py + dy * 3.8));
      if (Math.abs(dx) > Math.abs(dy)) solo.pDir = dx < 0 ? 'left' : 'right';
      else solo.pDir = dy < 0 ? 'up' : 'down';
    }

    const distPB = Math.hypot(solo.bx - solo.px, solo.by - solo.py);
    if (distPB < 27 && now >= solo.kickCooldownUntil) {
      const px = solo.bx - solo.px;
      const py = solo.by - solo.py;
      const plen = Math.hypot(px, py) || 1;
      solo.bvx = (px / plen) * 3.6 + dx * 1.4;
      solo.bvy = (py / plen) * 3.6 + dy * 1.4;
    }

    const targetGkX = Math.max(GOAL_X1 + 16, Math.min(GOAL_X2 - 16, solo.bx));
    const gkDiff = targetGkX - solo.gkX;
    solo.gkX += Math.sign(gkDiff) * Math.min(Math.abs(gkDiff), 2.35);

    solo.defX += solo.defVx;
    if (solo.defX < 105 || solo.defX > W - 105) solo.defVx *= -1;
    if (solo.by > 90 && solo.by < 250) {
      solo.defX += Math.sign(solo.bx - solo.defX) * 0.9;
    }

    solo.bx += solo.bvx;
    solo.by += solo.bvy;
    solo.bvx *= 0.968;
    solo.bvy *= 0.968;
    const spd = Math.hypot(solo.bvx, solo.bvy);
    if (spd < 0.08) { solo.bvx = 0; solo.bvy = 0; }
    else solo.bAngle += spd * 0.09;

    if (solo.by <= GOAL_Y + 8 && solo.bx >= GOAL_X1 + 8 && solo.bx <= GOAL_X2 - 8) {
      solo.playerGoals += 1;
      solo.goalBannerUntil = now + 1500;
      solo.goalBannerText = '⚽ VÀOOO! GHI BÀN TUYỆT ĐẸP!';
      deps.playCoin();
      updateScoreHUD();
      setTimeout(() => { if (active && mode === 'solo' && !solo.finished) resetSoloPositions(); }, 1200);
    } else if (solo.by >= H - 22 && solo.bx >= GOAL_X1 + 8 && solo.bx <= GOAL_X2 - 8) {
      solo.aiGoals += 1;
      solo.goalBannerUntil = now + 1400;
      solo.goalBannerText = '🧤 Ôi! Đối phương phản công!';
      deps.playError();
      updateScoreHUD();
      setTimeout(() => { if (active && mode === 'solo' && !solo.finished) resetSoloPositions(); }, 1200);
    }

    if (solo.bx < 20) { solo.bx = 20; solo.bvx = Math.abs(solo.bvx) * 0.78; }
    if (solo.bx > W - 20) { solo.bx = W - 20; solo.bvx = -Math.abs(solo.bvx) * 0.78; }
    if (solo.by < 24 && (solo.bx < GOAL_X1 || solo.bx > GOAL_X2)) { solo.by = 24; solo.bvy = Math.abs(solo.bvy) * 0.78; }
    if (solo.by > H - 18 && (solo.bx < GOAL_X1 || solo.bx > GOAL_X2)) { solo.by = H - 18; solo.bvy = -Math.abs(solo.bvy) * 0.78; }

    if (Math.hypot(solo.bx - solo.gkX, solo.by - (GOAL_Y + 26)) < 24) {
      solo.bvx = (solo.bx - solo.gkX) * 0.25 + (Math.random() - 0.5) * 3.5;
      solo.bvy = 5.4;
      deps.playClick();
    }
    if (Math.hypot(solo.bx - solo.defX, solo.by - solo.defY) < 24) {
      solo.bvx = (solo.bx - solo.defX) * 0.28 + (Math.random() - 0.5) * 3;
      solo.bvy = 4.6;
      deps.playClick();
    }
  }

  function stepOnlineHostPhysics(now: number) {
    if (roomState.status !== 'playing' || now < (roomState.goalBannerUntil || 0)) return;

    // P1 local input
    const p1Vec = getLocalDirVector();
    roomState.p1Moving = p1Vec.dx !== 0 || p1Vec.dy !== 0;
    if (roomState.p1Moving) {
      roomState.p1x = Math.max(26, Math.min(W - 26, roomState.p1x + p1Vec.dx * 3.9));
      roomState.p1y = Math.max(38, Math.min(H - 22, roomState.p1y + p1Vec.dy * 3.9));
      if (Math.abs(p1Vec.dx) > Math.abs(p1Vec.dy)) roomState.p1Dir = p1Vec.dx < 0 ? 'left' : 'right';
      else roomState.p1Dir = p1Vec.dy < 0 ? 'up' : 'down';
    }

    // P2 remote input
    const isFreshP2 = now - (remoteP2Input.ts || 0) < 2500;
    const p2dx = isFreshP2 ? remoteP2Input.dx : 0;
    const p2dy = isFreshP2 ? remoteP2Input.dy : 0;
    roomState.p2Moving = Math.abs(p2dx) > 0.05 || Math.abs(p2dy) > 0.05;
    if (roomState.p2Moving) {
      roomState.p2x = Math.max(26, Math.min(W - 26, roomState.p2x + p2dx * 3.9));
      roomState.p2y = Math.max(38, Math.min(H - 22, roomState.p2y + p2dy * 3.9));
      if (Math.abs(p2dx) > Math.abs(p2dy)) roomState.p2Dir = p2dx < 0 ? 'left' : 'right';
      else roomState.p2Dir = p2dy < 0 ? 'up' : 'down';
    }

    // P2 remote kick command
    if (remoteP2Input.kickSeq > lastHandledP2KickSeq) {
      lastHandledP2KickSeq = remoteP2Input.kickSeq;
      applyKickVelocity(roomState.p2x, roomState.p2y, roomState.p2Dir, 1, remoteP2Input.kickTx, remoteP2Input.kickTy);
    }

    // Dribble push from P1 & P2
    if (Math.hypot(roomState.bx - roomState.p1x, roomState.by - roomState.p1y) < 26) {
      const px = roomState.bx - roomState.p1x;
      const py = roomState.by - roomState.p1y;
      const plen = Math.hypot(px, py) || 1;
      roomState.bvx = (px / plen) * 3.7 + p1Vec.dx * 1.4;
      roomState.bvy = (py / plen) * 3.7 + p1Vec.dy * 1.4;
    }
    if (Math.hypot(roomState.bx - roomState.p2x, roomState.by - roomState.p2y) < 26) {
      const px = roomState.bx - roomState.p2x;
      const py = roomState.by - roomState.p2y;
      const plen = Math.hypot(px, py) || 1;
      roomState.bvx = (px / plen) * 3.7 + p2dx * 1.4;
      roomState.bvy = (py / plen) * 3.7 + p2dy * 1.4;
    }

    // Ball motion
    roomState.bx += roomState.bvx;
    roomState.by += roomState.bvy;
    roomState.bvx *= 0.968;
    roomState.bvy *= 0.968;
    if (Math.hypot(roomState.bvx, roomState.bvy) < 0.08) {
      roomState.bvx = 0;
      roomState.bvy = 0;
    }

    // Check Goals: Top Goal belongs to P2 (P1 scores!), Bottom Goal belongs to P1 (P2 scores!)
    if (roomState.by <= GOAL_Y + 6 && roomState.bx >= GOAL_X1 + 8 && roomState.bx <= GOAL_X2 - 8) {
      roomState.p1Goals += 1;
      roomState.goalBannerUntil = now + 1500;
      roomState.goalBannerText = `🔵 ${roomState.p1Name} GHI BÀN!`;
      deps.playCoin();
      pushOnlineRoom(true);
      setTimeout(() => { if (roomState.status === 'playing') { resetOnlinePositions(); pushOnlineRoom(true); } }, 1200);
    } else if (roomState.by >= H - 20 && roomState.bx >= GOAL_X1 + 8 && roomState.bx <= GOAL_X2 - 8) {
      roomState.p2Goals += 1;
      roomState.goalBannerUntil = now + 1500;
      roomState.goalBannerText = `🔴 ${roomState.p2Name || 'P2'} GHI BÀN!`;
      deps.playCoin();
      pushOnlineRoom(true);
      setTimeout(() => { if (roomState.status === 'playing') { resetOnlinePositions(); pushOnlineRoom(true); } }, 1200);
    }

    if (roomState.bx < 20) { roomState.bx = 20; roomState.bvx = Math.abs(roomState.bvx) * 0.78; }
    if (roomState.bx > W - 20) { roomState.bx = W - 20; roomState.bvx = -Math.abs(roomState.bvx) * 0.78; }
    if (roomState.by < 24 && (roomState.bx < GOAL_X1 || roomState.bx > GOAL_X2)) {
      roomState.by = 24;
      roomState.bvy = Math.abs(roomState.bvy) * 0.78;
    }
    if (roomState.by > H - 18 && (roomState.bx < GOAL_X1 || roomState.bx > GOAL_X2)) {
      roomState.by = H - 18;
      roomState.bvy = -Math.abs(roomState.bvy) * 0.78;
    }

    pushOnlineRoom(false);
  }

  function drawPitchBase(ctx: CanvasRenderingContext2D) {
    ctx.clearRect(0, 0, W, H);
    const stripeCount = 9;
    const stripeH = H / stripeCount;
    for (let i = 0; i < stripeCount; i++) {
      ctx.fillStyle = i % 2 === 0 ? '#1E8449' : '#239B56';
      ctx.fillRect(0, i * stripeH, W, stripeH + 1);
    }

    ctx.strokeStyle = 'rgba(255,255,255,0.9)';
    ctx.lineWidth = 3;
    ctx.strokeRect(14, 24, W - 28, H - 38);

    ctx.beginPath();
    ctx.moveTo(14, H / 2);
    ctx.lineTo(W - 14, H / 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(W / 2, H / 2, 42, 0, Math.PI * 2);
    ctx.stroke();
    ctx.fillStyle = '#FFF';
    ctx.beginPath();
    ctx.arc(W / 2, H / 2, 3.5, 0, Math.PI * 2);
    ctx.fill();

    ctx.strokeRect(140, 24, 240, 68);
    ctx.strokeRect(140, H - 82, 240, 68);

    // Top Goal Net
    ctx.fillStyle = 'rgba(255,255,255,0.18)';
    ctx.fillRect(GOAL_X1, 4, GOAL_X2 - GOAL_X1, GOAL_Y - 2);
    ctx.strokeStyle = 'rgba(255,255,255,0.45)';
    ctx.lineWidth = 1;
    for (let gx = GOAL_X1 + 10; gx < GOAL_X2; gx += 12) {
      ctx.beginPath(); ctx.moveTo(gx, 4); ctx.lineTo(gx, GOAL_Y); ctx.stroke();
    }
    ctx.strokeStyle = '#FFFFFF';
    ctx.lineWidth = 4;
    ctx.strokeRect(GOAL_X1, 4, GOAL_X2 - GOAL_X1, GOAL_Y - 2);

    // Bottom Goal outline
    ctx.strokeStyle = 'rgba(255,255,255,0.75)';
    ctx.lineWidth = 3;
    ctx.strokeRect(GOAL_X1, H - 14, GOAL_X2 - GOAL_X1, 12);
  }

  function drawSoccerBall(ctx: CanvasRenderingContext2D, bx: number, by: number, angle: number) {
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,0.28)';
    ctx.beginPath();
    ctx.ellipse(bx, by + 8, 9, 4, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.translate(bx, by);
    ctx.rotate(angle);
    ctx.fillStyle = '#FFFFFF';
    ctx.strokeStyle = '#0F172A';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, 0, 9.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#0F172A';
    ctx.beginPath();
    ctx.arc(0, 0, 3.6, 0, Math.PI * 2);
    ctx.fill();
    [0, 120, 240].forEach((deg) => {
      const r = (deg * Math.PI) / 180;
      ctx.beginPath();
      ctx.arc(Math.cos(r) * 6.5, Math.sin(r) * 6.5, 2, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.restore();
  }

  function drawGoalBannerOverlay(ctx: CanvasRenderingContext2D, text: string) {
    ctx.fillStyle = 'rgba(15, 23, 42, 0.72)';
    ctx.beginPath();
    ctx.roundRect(65, H / 2 - 28, W - 130, 56, 16);
    ctx.fill();
    ctx.strokeStyle = '#FACC15';
    ctx.lineWidth = 3;
    ctx.stroke();
    ctx.fillStyle = '#FACC15';
    ctx.font = 'bold 20px Fredoka, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(text, W / 2, H / 2 + 7);
  }

  function drawSoloEntities(ctx: CanvasRenderingContext2D, now: number) {
    const brand = (deps.getState().familyName || 'B2KS').trim() || 'B2KS';
    drawDetailedChibiOnContext(ctx, {
      x: solo.gkX, y: GOAL_Y + 26, dir: 'down', name: `Thủ môn ${brand}`,
      hairStyle: 'short', hairColor: '#1E293B', shirtColor: '#F59E0B', shirtPattern: 'collar',
      pantsColor: '#1E293B', pantsStyle: 'shorts', outfit: '🧤', speech: null
    }, false, 0.72, false, true);

    drawDetailedChibiOnContext(ctx, {
      x: solo.defX, y: solo.defY, dir: solo.defVx >= 0 ? 'right' : 'left', name: 'Hậu vệ',
      hairStyle: 'spiky', hairColor: '#DC2626', shirtColor: '#B91C1C', shirtPattern: 'stripe',
      pantsColor: '#1F2937', pantsStyle: 'shorts', outfit: '', speech: null
    }, false, 0.74, true, true);

    drawSoccerBall(ctx, solo.bx, solo.by, solo.bAngle);

    const me = deps.getCurrentUser();
    drawDetailedChibiOnContext(ctx, { ...me, x: solo.px, y: solo.py, dir: solo.pDir, speech: null }, true, 0.82, true, solo.pMoving);

    if (now < solo.goalBannerUntil) {
      drawGoalBannerOverlay(ctx, solo.goalBannerText);
    }
  }

  function drawOnlineEntities(ctx: CanvasRenderingContext2D, now: number) {
    const st = deps.getState();
    const me = deps.getCurrentUser();
    const p1Member = st.members.find((m) => m.id === roomState.p1Id);
    const p2Member = st.members.find((m) => m.id === roomState.p2Id);

    // Waiting indicator if spectating during lobby
    if (roomState.status === 'lobby') {
      drawSoccerBall(ctx, 260, 180, 0);
      drawGoalBannerOverlay(ctx, `🟡 Chờ ${roomState.p1Name} bắt đầu trận...`);
      return;
    }

    drawSoccerBall(ctx, roomState.bx, roomState.by, bAngleOnline);

    if (p2Member) {
      drawDetailedChibiOnContext(
        ctx,
        {
          ...p2Member,
          x: roomState.p2x,
          y: roomState.p2y,
          dir: roomState.p2Dir,
          shirtColor: '#DC2626',
          speech: null
        },
        p2Member.id === me.id,
        0.82,
        true,
        roomState.p2Moving
      );
    }

    if (p1Member) {
      drawDetailedChibiOnContext(
        ctx,
        {
          ...p1Member,
          x: roomState.p1x,
          y: roomState.p1y,
          dir: roomState.p1Dir,
          shirtColor: '#2563EB',
          speech: null
        },
        p1Member.id === me.id,
        0.82,
        true,
        roomState.p1Moving
      );
    }

    if (now < (roomState.goalBannerUntil || 0)) {
      drawGoalBannerOverlay(ctx, roomState.goalBannerText);
    }
  }

  function checkZoneAutoExit() {
    if (roomState.status !== 'lobby' && roomState.status !== 'playing' && roomState.status !== 'finished') return;
    const me = deps.getCurrentUser();
    if (roomState.p1Id !== me.id && roomState.p2Id !== me.id) return;
    const st = deps.getState();
    const pitchLoc = resolveNeighborhoodLocations(st).find((l) => l.id === 'soccer');
    const px = pitchLoc ? pitchLoc.x : 2060;
    const py = pitchLoc ? pitchLoc.y : 1400;
    const dist = Math.hypot(me.x - px, me.y - py);
    if (me.scene !== 'neighborhood' || dist > 220) {
      leave2PRoom();
      stopMatch();
      if (deps.closeModal) {
        deps.closeModal('soccer-modal');
      } else {
        const modalEl = document.getElementById('soccer-modal');
        if (modalEl) modalEl.style.display = 'none';
      }
      deps.showToast('🚶 Bạn đã rời Sân Bóng Đá nên tự động thoát phòng!');
    }
  }

  return {
    openSoccerArena,
    startMatch: openSoccerArena,
    restartSoloMatch: startSoloMatchInternal,
    stopMatch,
    kickBall,
    setTouchDir,
    handleKey,
    switchToSoloMode,
    switchTo2PMode,
    create2PRoom,
    join2PRoom,
    toggle2PReady,
    start2PMatch,
    leave2PRoom,
    spectateMatch,
    pullSoccerRoomFromFirebase,
    onRemoteSoccerRoomUpdate,
    onRemoteP2InputUpdate,
    checkZoneAutoExit,
    getRoomState: () => roomState,
    isActive: () => active
  };
}

